            gaugeColor = '#fbbf24'; // Amber/Yellow
        } else if (agent.silenceTimer > 0) {
            activeTimer = agent.silenceTimer;
            maxTimer = agent.silenceMax || activeTimer;
            iconType = 'SILENCE';
            gaugeColor = '#94a3b8'; // Grey
        } else if (agent.castingSkillIdx !== -1) {
            // Casting (Existing Logic moved here)
            const skill = agent.skills[agent.castingSkillIdx];
            if (skill) {
                // UX FIX: Casting should FILL UP (Clockwise Growth)
                // castTimer counts DOWN from Max to 0.
                // So (1 - timer/max) goes from 0 to 1.
                const progress = 1 - (agent.castTimer / skill.cast);
                this.drawCircularGauge(ctx, x, y, progress, skill.visual || 'BOLT', skill.color, true);
                return;
            }
        }

        // Draw CC Gauge if any
        if (iconType && maxTimer > 0) {
            // UX FIX: CC should DRAIN DOWN (Counter-Clockwise Shrink)
            // timer counts DOWN from Max to 0.
            // So (timer/max) goes from 1 to 0.
            const progress = activeTimer / maxTimer;
            this.drawCircularGauge(ctx, x, y, progress, iconType, gaugeColor, false);
        }
    }

    private drawUnitBars(ctx: CanvasRenderingContext2D, agent: Agent, x: number, y: number) {
        const w = BAR_WIDTH;
        const h = BAR_HEIGHT;
        const b = BAR_BORDER;

        // Background (Black Border)
        ctx.fillStyle = '#000'; 
        ctx.fillRect(x - w/2 - b, y - b, w + b*2, h + b*2);

        // HP Fill
        const hpPct = Math.max(0, agent.hp / agent.maxHp);
        ctx.fillStyle = COLORS.HP; 
        ctx.fillRect(x - w/2, y, w * hpPct, h);

        // MP Bar (Only if unit uses MP)
        if (agent.maxMp > 0) {
            const mpH = h / 2 + 1;
            const mpY = y + h + b;

            ctx.fillStyle = '#000'; 
            ctx.fillRect(x - w/2 - b, mpY, w + b*2, mpH + b*2);

            const mpPct = Math.max(0, agent.mp / agent.maxMp);
            ctx.fillStyle = COLORS.MP; 
            ctx.fillRect(x - w/2, mpY + b, w * mpPct, mpH);
        }
    }

    // Unified Gauge Drawer for both Casting and CC
    // 'pct' should be 0.0 to 1.0
    // If Growing (Cast), call with 0->1. Arc draws clockwise from top.
    // If Shrinking (CC), call with 1->0. Arc shrinks counter-clockwise to top.
    private drawCircularGauge(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        pct: number, 
        visualKey: string, 
        color: string, 
        isSkill: boolean
    ) {
        const radius = 14;
        const iconY = y - 18; 

        // 1. Icon Background (Clip)
        ctx.save();
        ctx.beginPath();
        ctx.arc(x, iconY, radius, 0, Math.PI * 2);
        ctx.fillStyle = '#1e293b';
        ctx.fill();
        ctx.clip();

        // 2. Icon Sprite
        let icon;
        if (isSkill) {
            icon = AssetManager.getSkillIcon(visualKey, color);
        } else {
            icon = AssetManager.getStatusIcon(visualKey);
        }

        // Ensure icon fits nicely
        if (icon) {
            ctx.drawImage(icon, x - radius, iconY - radius, radius * 2, radius * 2);
        }
        ctx.restore();

        // 3. Dark Track
        ctx.beginPath();
        ctx.arc(x, iconY, radius, 0, Math.PI * 2);
        ctx.strokeStyle = 'rgba(0, 0, 0, 0.6)';
        ctx.lineWidth = 4;
        ctx.stroke();

        // 4. Progress Ring
        const safePct = Math.max(0, Math.min(1, pct));

        if (safePct > 0) {
            ctx.beginPath();
            // Start at Top (-PI/2)
            // Draw Clockwise towards End Angle
            // For Casting (0->1): End Angle moves Clockwise.
            // For CC (1->0): End Angle moves Counter-Clockwise (Retracting).
            ctx.arc(x, iconY, radius, -Math.PI / 2, -Math.PI / 2 + (Math.PI * 2 * safePct));

            ctx.strokeStyle = color;
            ctx.lineWidth = 3;
            ctx.lineCap = 'round';
            ctx.stroke();
        }

        // 5. Shine / Bevel
        ctx.beginPath();
        ctx.arc(x, iconY, radius, 0, Math.PI * 2);
        ctx.strokeStyle = 'rgba(255,255,255,0.2)';
        ctx.lineWidth = 1;
        ctx.stroke();
    }

    private drawFloatingText(ctx: CanvasRenderingContext2D) {
        this.damageNumbers.forEach(d => {
            const lifePct = d.life / d.maxLife;
            // Fade logic
            const alpha = lifePct < 0.3 ? lifePct / 0.3 : 1.0;

            ctx.globalAlpha = alpha;
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';

            if (d.type === 'KILL_STREAK') {
                // --- EPIC KILL STREAK ---
                ctx.save();
                ctx.translate(d.x, d.y);

                // Pop-in Scale Effect
                const pop = Math.min(1, (1 - lifePct) * 5); // Rapid entry
                // Pulse logic
                const pulse = 1 + Math.sin(lifePct * 10) * 0.1;
                const scale = pop * pulse * 1.5; 
                ctx.scale(scale, scale);

                // Text Style
                ctx.font = `900 italic ${d.size}px "Arial Black", sans-serif`;

                // Fancy Gradient
                const grad = ctx.createLinearGradient(0, -d.size/2, 0, d.size/2);
                grad.addColorStop(0, '#ffffff');
                grad.addColorStop(0.5, d.color);
                grad.addColorStop(1, '#000000');

                // Stroke
                ctx.lineWidth = 4;
                ctx.lineJoin = 'round';
                ctx.strokeStyle = '#000';
                ctx.strokeText(d.text, 0, 0);

                // Fill
                ctx.fillStyle = grad;
                ctx.fillText(d.text, 0, 0);

                // Shine
                ctx.fillStyle = '#fff';
                ctx.shadowColor = d.color;
                ctx.shadowBlur = 10 * pulse;
                ctx.fillText(d.text, 0, 0);

                ctx.restore();

            } else if (d.type === 'SHOUT') {
                if (d.isUlt) {
                    // --- ULTIMATE STYLE ---
                    const scale = 1 + (1 - lifePct) * 0.1; 
                    ctx.save();
                    ctx.translate(d.x, d.y);
                    ctx.scale(scale, scale);

                    ctx.font = `900 italic ${d.size}px "Arial Black", sans-serif`;
                    const textMetrics = ctx.measureText(d.text);
                    const w = textMetrics.width / 2 + 30;
                    const h = d.size + 16;

                    // Gradient Bar
                    const bgGrad = ctx.createLinearGradient(-w, 0, w, 0);
                    bgGrad.addColorStop(0, 'rgba(0,0,0,0)');
                    bgGrad.addColorStop(0.2, 'rgba(0,0,0,0.6)'); 
                    bgGrad.addColorStop(0.8, 'rgba(0,0,0,0.6)');
                    bgGrad.addColorStop(1, 'rgba(0,0,0,0)');

                    ctx.fillStyle = bgGrad;
                    ctx.fillRect(-w, -h/2, w*2, h);

                    // Text Glow
                    ctx.shadowColor = d.color;
                    ctx.shadowBlur = 10;
                    ctx.fillStyle = '#fff';
                    ctx.strokeStyle = '#000';
                    ctx.lineWidth = 3;

                    ctx.strokeText(d.text, 0, 0);
                    ctx.fillText(d.text, 0, 0);

                    ctx.restore();

                } else {
                    // --- NORMAL SKILL ---
                    ctx.font = `bold italic ${d.size}px "Segoe UI", sans-serif`;
                    ctx.lineWidth = 3;
                    ctx.lineJoin = 'round';
                    ctx.strokeStyle = 'rgba(0, 0, 0, 0.8)'; 
                    ctx.strokeText(d.text, d.x, d.y);
                    ctx.fillStyle = d.color;
                    ctx.fillText(d.text, d.x, d.y);
                }

            } else if (d.type === 'CC') {
                // CC is handled by status label mostly, but this is for immediate feedback
                // Make it smaller or different to avoid conflict
                ctx.font = `900 ${d.size}px "Arial Black", sans-serif`; 
                ctx.strokeStyle = 'rgba(0,0,0,1.0)';
                ctx.lineWidth = 3;
                ctx.strokeText(d.text, d.x, d.y);
                ctx.fillStyle = d.color;
                ctx.fillText(d.text, d.x, d.y);

            } else {
                // DAMAGE / HEAL
                ctx.font = `bold ${d.size}px "Segoe UI", sans-serif`;
                ctx.fillStyle = d.color; 
                ctx.strokeStyle = 'rgba(0,0,0,0.8)'; 
                ctx.lineWidth = 3; 
                ctx.strokeText(d.text, d.x, d.y); 
                ctx.fillText(d.text, d.x, d.y);
            }

            ctx.globalAlpha = 1.0;
            ctx.shadowBlur = 0;
            ctx.shadowColor = 'transparent';
        });
    }
}

import { VFXStateManager } from "./vfx/state";

const GRAVITY = 1800; // Gravity for particles

export class VFXSystem {
    // Encapsulated State
    public state: VFXStateManager = new VFXStateManager();

    // Ambient Spawn State
    private ambientTimer: number = 0;

    update(dt: number, globalTime: number, ambientType: string) {
        // Update Particles
        // Iterate backwards to allow safe removal
        for (let i = this.state.particles.length - 1; i >= 0; i--) {
            const p = this.state.particles[i];

            if (p.delay && p.delay > 0) {
                p.delay -= dt;
                continue;
            }

            p.life -= dt;
            if (p.life <= 0) {
                this.state.releaseParticle(p);
                this.state.particles.splice(i, 1);
                continue;
            }

            // Physics Integration
            p.x += p.vx * dt;
            p.y += p.vy * dt;
            p.z += p.vz * dt;
            p.rotation += p.vRotation * dt;

            // Gravity & Environment Logic
            if (p.type === 'DEBRIS' || p.type === 'SHARD') {
                p.vz -= GRAVITY * dt; // Gravity

                // Ground Bounce
                if (p.z < 0) {
                    p.z = 0;
                    if (Math.abs(p.vz) > 100) {
                        // High Energy: Bounce
                        p.vz = -p.vz * 0.5; 
                        p.vx *= 0.6; // Air/Bounce Friction
                        p.vy *= 0.6;
                        p.vRotation *= 0.5;
                    } else {
                        // Low Energy: Slide & Rest
                        p.vz = 0;

                        // Ground Friction
                        p.vx *= 0.1; 
                        p.vy *= 0.1;
                        p.vRotation *= 0.1;

                        // FIX: Sleep Threshold to prevent micro-jitter
                        // If velocity is negligible, force stop to prevent sub-pixel vibration
                        if (Math.abs(p.vx) < 5) p.vx = 0;
                        if (Math.abs(p.vy) < 5) p.vy = 0;
                        if (Math.abs(p.vRotation) < 0.1) p.vRotation = 0;
                    }
                }
            } else if (p.type === 'SPARK' || p.type === 'SMOKE') {
                p.vx *= 0.90; 
                p.vy *= 0.90;
                p.vz *= 0.90; // Drag
            } else if (p.type === 'GLOW') {
                // Ambient particles float/wobble
                p.vx += Math.sin(globalTime * 2 + p.x) * 50 * dt;
                p.vy += Math.cos(globalTime * 2 + p.y) * 50 * dt;
            }
        }

        // Update Decals
        for (let i = this.state.decals.length - 1; i >= 0; i--) {
            this.state.decals[i].life -= dt * 0.5;
            if (this.state.decals[i].life <= 0) this.state.decals.splice(i, 1);
        }

        // Update Grid Flashes
        for (let i = this.state.gridFlashes.length - 1; i >= 0; i--) {
            this.state.gridFlashes[i].life -= dt * 2.0;
            if (this.state.gridFlashes[i].life <= 0) this.state.gridFlashes.splice(i, 1);
        }

        // --- AMBIENT SPAWNER ---
        this.updateAmbient(dt, ambientType);
    }

    private updateAmbient(dt: number, type: string) {
        if (type === 'NONE') return;

        this.ambientTimer += dt;
        // Spawn rate based on type
        const rate = type === 'SNOW' || type === 'ASH' ? 0.05 : 0.2; 

        if (this.ambientTimer > rate) {
            this.ambientTimer = 0;
            this.spawnAmbientParticle(type);
        }
    }

    private spawnAmbientParticle(type: string) {
        // Spawn randomly in a large area around center
        // Hardcoded viewport assumption roughly 1000x800, better to pass camera but this works for ambient
        const x = Math.random() * 1200 - 100;
        const y = Math.random() * 800 - 100;

        const p = this.state.getParticle();
        p.x = x; p.y = y; p.z = Math.random() * 200 + 50; // Keep off ground
        p.type = 'GLOW';

        if (type === 'SNOW') {
            p.color = '#fff';
            p.size = Math.random() * 3 + 1;
            p.vx = 20 + Math.random() * 20; // Wind
            p.vy = 50 + Math.random() * 30; // Fall
            p.life = 3.0; p.maxLife = 3.0;
        } else if (type === 'ASH') {
            p.color = '#78350f'; // Dark grey/brown
            p.size = Math.random() * 4 + 1;
            p.vx = 30 + Math.random() * 30;
            p.vy = 20 + Math.random() * 20;
            p.life = 4.0; p.maxLife = 4.0;
        } else if (type === 'EMBER') {
            p.color = '#fbbf24';
            p.size = Math.random() * 2 + 1;
            p.vx = (Math.random() - 0.5) * 20;
            p.vy = -30 - Math.random() * 20; // Rise
            p.life = 2.0; p.maxLife = 2.0;
        } else if (type === 'SPORES') {
            p.color = Math.random() > 0.5 ? '#bef264' : '#a855f7';
            p.size = Math.random() * 2 + 1;
            p.vx = (Math.random() - 0.5) * 10;
            p.vy = (Math.random() - 0.5) * 10; // Float
            p.life = 5.0; p.maxLife = 5.0;
        }

        this.state.particles.push(p);
    }
}

