import React, { useEffect, useRef, useState, useCallback } from 'react';
import { GameEngine, Agent } from './engine/game';
import GameCanvas from './components/GameCanvas';
import { ToolType, Team, Skill, Role } from './types';
import { SCENE_DB } from './data/scenes';

// UI Components
import { ShowcaseOverlay } from './components/ui/ShowcaseOverlay';
import { PlaybackHUD } from './components/ui/PlaybackHUD';
import { MapEditorToolbar } from './components/ui/MapEditorToolbar';
import { UnitInspectorHUD } from './components/ui/UnitInspectorHUD';
import { SystemMenu } from './components/ui/SystemMenu';
import { UnitDetailView } from './components/ui/UnitDetailView';

// Independent Tab Contents
import { LogTab } from './components/inspector/tabs/LogTab';
import { SkillDbTab } from './components/inspector/tabs/SkillDbTab';

function App() {
  const engineRef = useRef(new GameEngine());

  // App States
  const [isShowcaseMode, setIsShowcaseMode] = useState(true);
  const [isPlaying, setIsPlaying] = useState(false);
  const [unitCount, setUnitCount] = useState(0); 

  // Tooling
  const [tool, setTool] = useState<ToolType>(ToolType.SELECT);
  const [selectedObstacle, setSelectedObstacle] = useState<string>('WALL'); 
  const [selectedAgent, setSelectedAgent] = useState<Agent | null>(null);
  const [hoveredSkill, setHoveredSkill] = useState<Skill | null>(null);

  // Settings
  const [hpInput, setHpInput] = useState(600); 
  const [mapW, setMapW] = useState(12);
  const [mapH, setMapH] = useState(8);
  const [timeScale, setTimeScale] = useState(1.0);
  const [winner, setWinner] = useState<Team | null>(null);
  const [currentSceneId, setCurrentSceneId] = useState('VOID');

  // Spawn Logic
  const [spawnMode, setSpawnMode] = useState<'RANDOM' | 'DRAFT'>('RANDOM');
  const [draftRole, setDraftRole] = useState<Role>(Role.WARRIOR);

  // Modals
  const [showLogs, setShowLogs] = useState(false);
  const [showDB, setShowDB] = useState(false);
  const [showUnitDetail, setShowUnitDetail] = useState(false);

  const [transitionPhase, setTransitionPhase] = useState<'IDLE' | 'IN' | 'OUT'>('IDLE');
  const [showFactionWarning, setShowFactionWarning] = useState(false);

  // --- Logic ---

  const setupShowcaseMap = useCallback(() => {
      const engine = engineRef.current;
      engine.stop();
      setWinner(null);
      setSelectedAgent(null);
      setShowUnitDetail(false); // Close details on reset
      engine.mapConfig.w = Math.floor(10 + Math.random() * 4);
      engine.mapConfig.h = Math.floor(8 + Math.random() * 4);
      engine.randomizeEnvironment(); 
      setCurrentSceneId(engine.currentScene.id);
  }, []);

  const spawnShowcaseUnits = useCallback(() => {
      const engine = engineRef.current;
      const validHexes = (Array.from(engine.mapKeys) as string[]).map(k => {
          const [q, r] = k.split(',').map(Number);
          return {q, r};
      });
      for (let i = validHexes.length - 1; i > 0; i--) {
          const j = Math.floor(Math.random() * (i + 1));
          [validHexes[i], validHexes[j]] = [validHexes[j], validHexes[i]];
      }
      let spawnIndex = 0;
      const spawn = (team: Team) => {
          if (spawnIndex < validHexes.length) {
              const h = validHexes[spawnIndex++];
              const hp = 500 + Math.floor(Math.random() * 400); 
              engine.addAgent(team, h.q, h.r, hp);
          }
      };
      for(let i=0; i<5; i++) spawn(Team.BLUE);
      for(let i=0; i<5; i++) spawn(Team.RED);
      engine.play();
      setIsPlaying(true);
  }, []);

  const startShowcaseMatch = useCallback(() => {
      setupShowcaseMap();
      spawnShowcaseUnits();
  }, [setupShowcaseMap, spawnShowcaseUnits]);

  useEffect(() => {
      startShowcaseMatch();
  }, [startShowcaseMatch]);

  const enterManualMode = () => {
      setIsShowcaseMode(false);
      engineRef.current.stop();
      setIsPlaying(false);
      setWinner(null);
      engineRef.current.clear(true); 
      engineRef.current.agents = [];
      setUnitCount(0);
      setMapW(engineRef.current.mapConfig.w);
      setMapH(engineRef.current.mapConfig.h);
      setCurrentSceneId(engineRef.current.currentScene.id);
  };

  useEffect(() => {
    const interval = setInterval(() => {
        setUnitCount(engineRef.current.agents.length);
    }, 500); 
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
      engineRef.current.timeScale = timeScale;
  }, [timeScale]);

  // --- Map Editor Logic ---

  const handleUpdateMapSize = useCallback((w: number, h: number) => {
      setMapW(w);
      setMapH(h);
      engineRef.current.mapConfig.w = w;
      engineRef.current.mapConfig.h = h;
      engineRef.current.clear(false); 
      setSelectedAgent(null);
      setWinner(null);
  }, []);

  const handleSetScene = useCallback((id: string) => {
      const scene = SCENE_DB.find(s => s.id === id);
      if (scene) {
          engineRef.current.currentScene = scene;
          engineRef.current.map.rebuildMap(engineRef.current);
          setCurrentSceneId(id);
      }
  }, []);

  const handleRandomBattlefield = useCallback(() => {
      const engine = engineRef.current;
      engine.stop();
      setWinner(null);
      setSelectedAgent(null);
      engine.clear(false); 

      engine.randomizeEnvironment();
      setMapW(engine.mapConfig.w);
      setMapH(engine.mapConfig.h);
      setCurrentSceneId(engine.currentScene.id);

      const validHexes = (Array.from(engine.mapKeys) as string[]).map(k => {
          const [q, r] = k.split(',').map(Number);
          return {q, r};
      });
      for (let i = validHexes.length - 1; i > 0; i--) {
          const j = Math.floor(Math.random() * (i + 1));
          [validHexes[i], validHexes[j]] = [validHexes[j], validHexes[i]];
      }
      let spawnIndex = 0;
      const spawn = (team: Team) => {
          if (spawnIndex < validHexes.length) {
              const h = validHexes[spawnIndex++];
              const hp = 500 + Math.floor(Math.random() * 400); 
              engine.addAgent(team, h.q, h.r, hp);
          }
      };
      for(let i=0; i<5; i++) spawn(Team.BLUE);
      for(let i=0; i<5; i++) spawn(Team.RED);

      setIsPlaying(false); 
  }, []);

  const handleReset = useCallback(() => {
      engineRef.current.restart();
      setIsPlaying(false); 
      setWinner(null);
  }, []);

  // --- Interaction ---

  const togglePlay = useCallback(() => {
    if (winner !== null) return;

    if (isPlaying) {
        engineRef.current.stop();
        setIsPlaying(false);
    } else {
        const hasBlue = engineRef.current.agents.some(a => a.team === Team.BLUE);
        const hasRed = engineRef.current.agents.some(a => a.team === Team.RED);

        if (!hasBlue || !hasRed) {
            setShowFactionWarning(true);
            setTimeout(() => setShowFactionWarning(false), 2500);
            return;
        }

        engineRef.current.play();
        setIsPlaying(true);
        setTool(ToolType.SELECT);
    }
  }, [isPlaying, winner]);

  const onWin = (team: Team) => {
    setWinner(team);
    if (isShowcaseMode) {
        setTimeout(() => {
            setTransitionPhase('OUT');
            engineRef.current.agents = [];
            engineRef.current.combat.projectiles = [];
            setTimeout(() => {
                setupShowcaseMap(); 
                setTransitionPhase('IN'); 
                setTimeout(() => {
                    setTransitionPhase('IDLE');
                    spawnShowcaseUnits(); 
                }, 1200);
            }, 1500);
        }, 2000);
    } else {
        setIsPlaying(false);
    }
  };

  const handleSelectAgent = (a: Agent | null) => {
      setSelectedAgent(a);
      if (!a) setShowUnitDetail(false);
  };

  return (
    <div className="h-[100dvh] w-screen bg-slate-950 text-slate-200 overflow-hidden font-sans flex flex-col relative select-none touch-none">

      {/* WARNING NOTIFICATION */}
      {showFactionWarning && (
            <div className="absolute top-24 left-1/2 -translate-x-1/2 z-50 animate-bounce-in pointer-events-none w-[90%] max-w-md">
                <div className="bg-red-950/90 text-red-200 px-6 py-3 rounded border border-red-500 flex items-center gap-3 shadow-xl">
                    <span className="text-xl">⚠️</span>
                    <div className="flex flex-col">
                        <span className="text-xs font-bold tracking-widest text-red-400 uppercase">部署錯誤</span>
                        <span className="text-xs">請部署雙方單位以開始戰鬥。</span>
                    </div>
                </div>
            </div>
      )}

      {/* SHOWCASE OVERLAY */}
      {isShowcaseMode && (
        <ShowcaseOverlay 
            onEnter={enterManualMode} 
            timeScale={timeScale} 
            setTimeScale={setTimeScale} 
        />
      )}

      {/* --- HUD LAYERS --- */}

      {/* 1. Playback Controls (Top Center) */}
      <PlaybackHUD 
          hidden={isShowcaseMode}
          isPlaying={isPlaying}
          winner={winner}
          timeScale={timeScale}
          onTogglePlay={togglePlay}
          onRestart={handleReset}
          onSetTimeScale={setTimeScale}
          onShowcase={() => { setIsShowcaseMode(true); startShowcaseMatch(); }}
      />

      {/* 2. System Menu (Top Right) */}
      {!isShowcaseMode && (
          <SystemMenu 
              onToggleLogs={() => setShowLogs(!showLogs)} 
              onToggleDB={() => setShowDB(!showDB)} 
          />
      )}

      {/* 3. Unit Inspector (Floating Right Bottom) */}
      {!isShowcaseMode && selectedAgent && (
          <UnitInspectorHUD 
              agent={selectedAgent} 
              onClose={() => handleSelectAgent(null)} 
              onExpand={() => setShowUnitDetail(true)}
          />
      )}

      {/* 4. MODALS (Logs / DB / Unit Detail) */}
      {/* Wrapper */}
      {(showLogs || showDB || (showUnitDetail && selectedAgent)) && !isShowcaseMode && (
          <div className="absolute inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-2 md:p-12 animate-fade-in" 
               onClick={() => { setShowLogs(false); setShowDB(false); setShowUnitDetail(false); }}>

              <div className="w-full md:w-auto h-[90%] md:h-full max-w-[95%] md:max-w-5xl bg-slate-900 border border-slate-700 shadow-2xl rounded-lg overflow-hidden flex flex-col transition-all" onClick={e => e.stopPropagation()}>

                  {/* Modal Header */}
                  <div className="flex justify-between items-center p-3 md:p-4 border-b border-slate-800 bg-slate-950 shrink-0">
                      <h2 className="text-base md:text-lg font-bold text-cyan-400 truncate pr-4">
                          {showLogs && '戰況紀錄'}
                          {showDB && '技能資料庫'}
                          {showUnitDetail && '單位神經網路分析'}
                      </h2>
                      <button onClick={() => { setShowLogs(false); setShowDB(false); setShowUnitDetail(false); }} className="text-slate-500 hover:text-white px-2 py-1">✕</button>
                  </div>

                  {/* Modal Content */}
                  <div className="flex-1 overflow-hidden relative bg-slate-900 min-h-0">
                      {showLogs && <LogTab engine={engineRef.current} />}
                      {showDB && <SkillDbTab db={engineRef.current.skillDB} onUpdate={() => {}} />}
                      {showUnitDetail && selectedAgent && <UnitDetailView agent={selectedAgent} db={engineRef.current.skillDB} />}
                  </div>
              </div>
          </div>
      )}

      {/* MAIN GAME VIEW */}
      <div className="flex-1 relative z-0 bg-slate-900">
            <GameCanvas 
                engine={engineRef.current} 
                tool={tool}
                selectedObstacle={selectedObstacle}
                hpInput={hpInput}
                selectedAgent={selectedAgent}
                hoveredSkill={hoveredSkill}
                isShowcaseMode={isShowcaseMode}
                spawnMode={spawnMode}
                draftRole={draftRole}
                onSelect={handleSelectAgent} 
                onWin={onWin}
                winner={winner}
                rematch={() => { setWinner(null); engineRef.current.restart(); setIsPlaying(true); }}
                transitionPhase={transitionPhase}
            />
      </div>

      {/* 5. Map Editor Toolbar (Bottom) */}
      {!isShowcaseMode && (
          <MapEditorToolbar 
              tool={tool}
              setTool={setTool}
              mapW={mapW} setMapW={(w) => handleUpdateMapSize(w, mapH)}
              mapH={mapH} setMapH={(h) => handleUpdateMapSize(mapW, h)}
              currentSceneId={currentSceneId}
              onSetScene={handleSetScene}
              spawnMode={spawnMode} setSpawnMode={setSpawnMode}
              draftRole={draftRole} setDraftRole={setDraftRole}
              hpInput={hpInput} setHpInput={setHpInput}
              selectedObstacle={selectedObstacle} setSelectedObstacle={setSelectedObstacle}
              onRandomBattlefield={handleRandomBattlefield}
              onReset={handleReset}
          />
      )}
    </div>
  );
}

export default App;

import React, { useRef, useEffect } from 'react';
import { Agent, GameEngine } from '../engine/game';
import { GameRenderer } from '../engine/renderer';
import { HexUtils } from '../engine/utils';
import { SpriteManager } from '../engine/sprites';
import { Team, ToolType, Hex, Skill, GameEvent, Role } from '../types';
import { BLOCK_HEIGHT } from '../constants'; 

interface GameCanvasProps {
    engine: GameEngine;
    tool: ToolType;
    selectedObstacle: string; 
    hpInput: number;
    selectedAgent: Agent | null; 
    hoveredSkill: Skill | null;
    isShowcaseMode: boolean; 
    spawnMode: 'RANDOM' | 'DRAFT';
    draftRole: Role; 
    onSelect: (a: Agent | null) => void;
    onWin: (team: Team) => void;
    winner: Team | null;
    rematch: () => void;
    transitionPhase: 'IDLE' | 'IN' | 'OUT';
}

const GameCanvas: React.FC<GameCanvasProps> = ({ engine, tool, selectedObstacle, hpInput, selectedAgent, hoveredSkill, isShowcaseMode, spawnMode, draftRole, onSelect, onWin, winner, rematch, transitionPhase }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const wrapperRef = useRef<HTMLDivElement>(null);
    const camera = useRef({ x: 0, y: 0, zoom: 1.0 }); 
    const fpsRef = useRef(60);

    // Instantiate Renderer
    const rendererRef = useRef(new GameRenderer());
    const transitionStartTime = useRef(0);

    // Bridge for Synchronous Redraw
    const drawCurrentFrameRef = useRef<() => void>(() => {});

    // Handle Transition Phase Timing
    useEffect(() => {
        transitionStartTime.current = performance.now();
    }, [transitionPhase]);

    // --- INTERACTION STATE ---
    // Interaction Mode State Machine
    type InteractionMode = 'IDLE' | 'DOWN' | 'DRAG_UNIT' | 'DRAG_OBS' | 'PAN' | 'PAINT';
    const interactionMode = useRef<InteractionMode>('IDLE');

    // Unit Dragging
    const pressedAgentRef = useRef<Agent | null>(null);

    // Obstacle Dragging
    const draggedObstacleRef = useRef<{ 
        type: string; 
        originQ: number; 
        originR: number; 
        px: number; 
        py: number; 
    } | null>(null);

    // General Input State
    const pressStartPos = useRef<{x: number, y: number} | null>(null);
    const dragStartHex = useRef<{q: number, r: number} | null>(null);
    const lastPaintHex = useRef<string>(""); 

    // Touch specific state
    const lastPinchDist = useRef<number>(0);
    const lastTouchPos = useRef<{x: number, y: number} | null>(null);

    // Track hovered hex for visual feedback
    const hoveredHexRef = useRef<Hex | null>(null);

    // Track selected agent for the render loop
    const selectedAgentRef = useRef<Agent | null>(selectedAgent);
    useEffect(() => {
        selectedAgentRef.current = selectedAgent;
    }, [selectedAgent]);

    // --- Camera Control Logic ---
    const centerCamera = () => {
        if (!canvasRef.current || !wrapperRef.current) return;

        canvasRef.current.width = wrapperRef.current.clientWidth;
        canvasRef.current.height = wrapperRef.current.clientHeight;

        const cw = engine.mapConfig.w;
        const ch = engine.mapConfig.h;

        const centerHex = { q: Math.floor(cw / 2), r: Math.floor(ch / 2) };
        const p = HexUtils.toPx(centerHex.q, centerHex.r, engine.mapConfig);
        const verticalOffset = -BLOCK_HEIGHT * 2; 

        camera.current.x = p.x - (canvasRef.current.width / camera.current.zoom) / 2;
        camera.current.y = p.y + verticalOffset - (canvasRef.current.height / camera.current.zoom) / 2;
    };

    useEffect(() => {
        if (isShowcaseMode || transitionPhase === 'IN') {
            const t = setTimeout(centerCamera, 350);
            return () => clearTimeout(t);
        } else if (!isShowcaseMode && transitionPhase === 'IDLE') {
             const t = setTimeout(centerCamera, 350);
             return () => clearTimeout(t);
        }
    }, [isShowcaseMode, transitionPhase, engine.mapConfig.w, engine.mapConfig.h]);

    useEffect(() => {
        if (!wrapperRef.current || !canvasRef.current) return;

        const resizeObserver = new ResizeObserver(() => {
            // Fix: Wrap in requestAnimationFrame to avoid "ResizeObserver loop completed with undelivered notifications"
            window.requestAnimationFrame(() => {
                if (wrapperRef.current && canvasRef.current) {
                    canvasRef.current.width = wrapperRef.current.clientWidth;
                    canvasRef.current.height = wrapperRef.current.clientHeight;
                    if (engine.agents.length === 0) centerCamera();
                    drawCurrentFrameRef.current();
                }
            });
        });

        resizeObserver.observe(wrapperRef.current);
        centerCamera();

        return () => resizeObserver.disconnect();
    }, [engine]);

    // Render Loop
    useEffect(() => {
        let frameId: number;
        let lastTime = 0;
        let acc = 0;
        const targetFPS = 60;
        const step = 1000 / targetFPS;
        let frameCount = 0;
        let lastFpsTime = 0;

        const drawFrame = () => {
            const ctx = canvasRef.current?.getContext('2d');
            if (ctx && canvasRef.current) {
                const highlight = pressedAgentRef.current || selectedAgentRef.current || null;
                rendererRef.current.draw(ctx, engine, camera.current, highlight, fpsRef.current, hoveredHexRef.current, hoveredSkill); 

                // Draw Dragged Obstacle Ghost
                if (draggedObstacleRef.current) {
                    const { type, px, py } = draggedObstacleRef.current;
                    const { x, y, zoom } = camera.current;
                    const { width, height } = canvasRef.current;

                    ctx.save();
                    ctx.translate(width / 2, height / 2);
                    ctx.scale(zoom, zoom);
                    ctx.translate(-x - width / 2 / zoom, -y - height / 2 / zoom);

                    const sprite = SpriteManager.getObstacleSprite(type);
                    const liftOffset = 40; // Higher lift for visibility
                    ctx.shadowColor = 'rgba(0,0,0,0.5)';
                    ctx.shadowBlur = 30;
                    ctx.shadowOffsetY = 30;
                    ctx.globalAlpha = 0.9;
                    // Adjusted offset from 86 to 80 to match engine renderer
                    ctx.drawImage(sprite, px - 32, py - 80 - liftOffset);
                    ctx.restore();
                }
            }
        };

        drawCurrentFrameRef.current = drawFrame;

        const loop = (t: number) => {
            if (!lastTime) lastTime = t;
            const dt = t - lastTime;
            lastTime = t;

            frameCount++;
            if (t - lastFpsTime >= 1000) {
                fpsRef.current = frameCount;
                frameCount = 0;
                lastFpsTime = t;
            }

            if (engine.isRunning) {
                acc += dt;
                if (acc > 200) acc = 200;
                const frameEvents: GameEvent[] = [];
                while (acc >= step) {
                    const sdt = (step / 1000) * engine.timeScale;
                    engine.tick(sdt);
                    engine.battleTime += sdt;
                    acc -= step;
                    frameEvents.push(...engine.events);
                }
                if (frameEvents.length > 0) {
                    rendererRef.current.processEventsWithEngine(frameEvents, engine);
                }
            }

            rendererRef.current.update(dt / 1000, engine);

            if (transitionPhase !== 'IDLE') {
                const elapsed = (performance.now() - transitionStartTime.current) / 1000;
                const progress = Math.min(1.0, elapsed / 1.2);
                rendererRef.current.setTransition(progress, transitionPhase);
            } else {
                rendererRef.current.setTransition(0, 'IDLE');
            }

            drawFrame();
            frameId = requestAnimationFrame(loop);
        };

        engine.onWin = (team) => { onWin(team); };
        frameId = requestAnimationFrame(loop);
        return () => cancelAnimationFrame(frameId);
    }, [engine, onWin, hoveredSkill, transitionPhase]);

    // Input Handling
    useEffect(() => {
        const cvs = canvasRef.current;
        if (!cvs) return;

        const getScreenCoords = (x: number, y: number) => {
            const rect = cvs.getBoundingClientRect();
            return { x: x - rect.left, y: y - rect.top };
        };

        const getHexFromCoords = (sx: number, sy: number) => {
            const hex = rendererRef.current.getHexAtScreenPoint(sx, sy, camera.current, engine);
            if (hex) return hex;
            return HexUtils.fromPx(
                sx / camera.current.zoom + camera.current.x,
                sy / camera.current.zoom + camera.current.y,
                engine.mapConfig
            );
        };

        const getHitAgentFromCoords = (sx: number, sy: number) => {
            const wx = sx / camera.current.zoom + camera.current.x;
            const wy = sy / camera.current.zoom + camera.current.y;
            const sorted = [...engine.agents].sort((a, b) => b.py - a.py);

            for (const agent of sorted) {
                if (agent.hp <= 0 && agent.fullyDead) continue;
                const h = rendererRef.current.getTerrainHeight(agent.q, agent.r, engine);
                const baseX = agent.px;
                const baseY = agent.py - h;
                const dx = Math.abs(wx - baseX);
                const dy = wy - (baseY - 40); 
                if (dx < 35 && Math.abs(dy) < 60) return agent;
            }
            return null;
        };

        const getWorldPosFromCoords = (sx: number, sy: number) => {
            const wx = sx / camera.current.zoom + camera.current.x;
            const hex = rendererRef.current.getHexAtScreenPoint(sx, sy, camera.current, engine);
            let h = BLOCK_HEIGHT + 6;
            if (hex) h = rendererRef.current.getTerrainHeight(hex.q, hex.r, engine);
            const wy = sy / camera.current.zoom + camera.current.y + h;
            return { x: wx, y: wy };
        };

        const executeToolAction = (h: Hex) => {
            if (engine.isRunning || winner !== null) return;
            const k = HexUtils.key(h);
            if (lastPaintHex.current === k) return; 

            lastPaintHex.current = k;
            const existingAgent = engine.getAgentAt(h.q, h.r);
            let agent: Agent | null = null;

            if (tool === ToolType.DELETE) {
                if (engine.hasObstacle(h.q, h.r)) engine.removeObstacle(h.q, h.r);
                if (existingAgent) {
                    engine.removeAgent(h.q, h.r);
                    onSelect(null);
                }
                return;
            }

            if (tool === ToolType.OBSTACLE) {
                if (existingAgent) engine.removeAgent(h.q, h.r);
                engine.setObstacle(h.q, h.r, selectedObstacle);
                return;
            }

            if (!existingAgent && !engine.hasObstacle(h.q, h.r)) {
                if (tool === ToolType.ADD_BLUE) agent = engine.addAgent(Team.BLUE, h.q, h.r, hpInput);
                else if (tool === ToolType.ADD_RED) agent = engine.addAgent(Team.RED, h.q, h.r, hpInput);
            }

            if (agent && spawnMode === 'DRAFT') {
                agent.role = draftRole;
                const validSkills = engine.skillDB.filter(s => s.role === agent!.role && (s.team === undefined || s.team === agent!.team));
                const rnd = (ar: Skill[]) => ar.length > 0 ? ar[Math.floor(Math.random() * ar.length)].id : null;
                agent.skillIds = [
                    rnd(validSkills.filter(s => s.tag === 'ULT')),
                    rnd(validSkills.filter(s => s.tag === 'ACTIVE')),
                    rnd(validSkills.filter(s => s.tag === 'BASIC'))
                ];
                agent.saveState();
                agent.reset(engine.mapConfig);
            }
        };

        // --- UNIFIED INPUT HANDLER ---

        const handleDown = (sx: number, sy: number, button: number = 0) => {
            pressStartPos.current = { x: sx, y: sy };
            lastPaintHex.current = "";
            interactionMode.current = 'DOWN';

            // Right Click always Pans
            if (button === 2) {
                interactionMode.current = 'PAN';
                return;
            }

            if (engine.isRunning) {
                interactionMode.current = 'PAN';
                return;
            }

            // Identify potential targets for drag start
            const hitAgent = getHitAgentFromCoords(sx, sy);
            if (hitAgent) {
                pressedAgentRef.current = hitAgent;
                if (tool !== ToolType.DELETE) {
                    dragStartHex.current = { q: hitAgent.q, r: hitAgent.r };
                }
                // Don't set mode to DRAG_UNIT yet, wait for move threshold
                return;
            }

            // Check Obstacle
            const h = getHexFromCoords(sx, sy);
            const validGrid = engine.isValid(h.q, h.r);

            if (validGrid && engine.hasObstacle(h.q, h.r)) {
                if (tool !== ToolType.DELETE) {
                    // Pre-load obstacle drag data but don't activate
                    const obsType = engine.obstacles.get(HexUtils.key(h));
                    if (obsType) {
                        draggedObstacleRef.current = {
                            type: obsType,
                            originQ: h.q, originR: h.r,
                            px: 0, py: 0
                        };
                    }
                }
            }
        };

        const handleMove = (sx: number, sy: number, dx: number, dy: number) => {
            const h = getHexFromCoords(sx, sy);
            hoveredHexRef.current = engine.isValid(h.q, h.r) ? h : null;

            // Cursor Logic
            const hitAgent = getHitAgentFromCoords(sx, sy);
            if (cvs) {
                if (interactionMode.current === 'DRAG_UNIT' || interactionMode.current === 'DRAG_OBS') cvs.style.cursor = 'grabbing';
                else if (interactionMode.current === 'PAN') cvs.style.cursor = 'move';
                else if (hitAgent) cvs.style.cursor = 'pointer'; 
                else if (engine.hasObstacle(h.q, h.r)) cvs.style.cursor = 'grab';
                else if (tool === ToolType.SELECT) cvs.style.cursor = 'default';
                else cvs.style.cursor = 'crosshair'; 
            }

            // 1. If IDLE, just update cursor (already done above)
            if (interactionMode.current === 'IDLE') return;

            // 2. If PANNING, apply movement
            if (interactionMode.current === 'PAN') {
                camera.current.x -= dx / camera.current.zoom;
                camera.current.y -= dy / camera.current.zoom;
                return;
            }

            // 3. If PAINTING, execute paint
            if (interactionMode.current === 'PAINT') {
                if (engine.isValid(h.q, h.r)) {
                    executeToolAction(h);
                }
                return;
            }

            // 4. If DRAGGING UNIT
            if (interactionMode.current === 'DRAG_UNIT' && pressedAgentRef.current) {
                const wPos = getWorldPosFromCoords(sx, sy);
                pressedAgentRef.current.px = wPos.x;
                pressedAgentRef.current.py = wPos.y;
                return;
            }

            // 5. If DRAGGING OBS
            if (interactionMode.current === 'DRAG_OBS' && draggedObstacleRef.current) {
                const wPos = getWorldPosFromCoords(sx, sy);
                draggedObstacleRef.current.px = wPos.x;
                draggedObstacleRef.current.py = wPos.y;
                return;
            }

            // 6. ARBITRATION (Transition from DOWN to specific mode)
            if (interactionMode.current === 'DOWN' && pressStartPos.current) {
                const dist = Math.sqrt((sx - pressStartPos.current.x)**2 + (sy - pressStartPos.current.y)**2);

                // Threshold exceeded: Decide intent
                if (dist > 10) {
                    // A. Prioritize Unit Drag
                    if (pressedAgentRef.current && tool !== ToolType.DELETE) {
                        interactionMode.current = 'DRAG_UNIT';
                        pressedAgentRef.current.physics.z = 20; // Lift visual
                        onSelect(pressedAgentRef.current);
                        return;
                    }

                    // B. Secondary Obstacle Drag
                    if (draggedObstacleRef.current && tool !== ToolType.DELETE) {
                        interactionMode.current = 'DRAG_OBS';
                        // Lift logical obstacle from map
                        const { originQ, originR } = draggedObstacleRef.current;
                        engine.removeObstacle(originQ, originR);
                        onSelect(null);

                        // Set initial visual pos
                        const wPos = getWorldPosFromCoords(sx, sy);
                        draggedObstacleRef.current.px = wPos.x;
                        draggedObstacleRef.current.py = wPos.y;
                        return;
                    }

                    // C. Paint vs Pan
                    // If hitting a valid tile AND using a paint-friendly tool (Obstacle/Delete)
                    if (engine.isValid(h.q, h.r) && (tool === ToolType.OBSTACLE || tool === ToolType.DELETE)) {
                        interactionMode.current = 'PAINT';
                        executeToolAction(h);
                    } else {
                        // Default to Pan for Unit Spawning tools or Select tool on empty space
                        interactionMode.current = 'PAN';
                        // Catch up camera movement for the initial drag distance
                        camera.current.x -= dx / camera.current.zoom;
                        camera.current.y -= dy / camera.current.zoom;
                    }
                }
            }
        };

        const handleUp = (sx: number, sy: number) => {
            const h = getHexFromCoords(sx, sy);

            // 1. CLICK Logic (If we never left DOWN state)
            if (interactionMode.current === 'DOWN') {
                if (pressedAgentRef.current) {
                    if (tool === ToolType.DELETE) {
                        const a = pressedAgentRef.current;
                        engine.removeAgent(a.q, a.r);
                        onSelect(null);
                    } else {
                        onSelect(pressedAgentRef.current);
                    }
                } else if (engine.hasObstacle(h.q, h.r)) {
                    if (tool === ToolType.DELETE) {
                        engine.removeObstacle(h.q, h.r);
                    }
                    // Else: Select obstacle? Not implemented, maybe highlight.
                } else if (tool !== ToolType.SELECT && tool !== ToolType.DELETE) {
                    // Place Unit logic
                    if (engine.isValid(h.q, h.r)) executeToolAction(h);
                } else {
                    // Click on empty/void with Select tool
                    onSelect(null);
                }
            }

            // 2. Drop Unit
            if (interactionMode.current === 'DRAG_UNIT' && pressedAgentRef.current) {
                const agent = pressedAgentRef.current;
                const isValidHex = engine.isValid(h.q, h.r);
                const isObstacle = engine.obstacles.has(HexUtils.key(h));
                const occupant = engine.getAgentAt(h.q, h.r);
                const isOccupiedByOther = occupant && occupant !== agent;

                agent.physics.z = 0; // Drop visual

                if (isValidHex && !isObstacle && !isOccupiedByOther) {
                    engine.updateAgentPosition(agent, h.q, h.r);
                    const p = HexUtils.toPx(h.q, h.r, engine.mapConfig);
                    agent.px = p.x; agent.py = p.y;
                } else {
                    // Revert
                    if (dragStartHex.current) {
                        agent.q = dragStartHex.current.q;
                        agent.r = dragStartHex.current.r;
                        const p = HexUtils.toPx(agent.q, agent.r, engine.mapConfig);
                        agent.px = p.x; agent.py = p.y;
                        engine.updateAgentPosition(agent, agent.q, agent.r);
                    }
                }
                onSelect(agent);
            }

            // 3. Drop Obstacle
            if (interactionMode.current === 'DRAG_OBS' && draggedObstacleRef.current) {
                const { type, originQ, originR } = draggedObstacleRef.current;
                const isValidHex = engine.isValid(h.q, h.r);
                const occupant = engine.getAgentAt(h.q, h.r);
                const hasExistingObstacle = engine.hasObstacle(h.q, h.r);

                if (isValidHex && !occupant && !hasExistingObstacle) {
                    engine.setObstacle(h.q, h.r, type);
                } else {
                    engine.setObstacle(originQ, originR, type); // Revert
                }
            }

            // Reset
            interactionMode.current = 'IDLE';
            pressedAgentRef.current = null;
            draggedObstacleRef.current = null;
            pressStartPos.current = null;
            lastPaintHex.current = "";
            if (cvs) cvs.style.cursor = 'default';
        };

        // Event Listeners
        const handleMouseDown = (e: MouseEvent) => {
            const pos = getScreenCoords(e.clientX, e.clientY);
            handleDown(pos.x, pos.y, e.button);
        };
        const handleMouseMove = (e: MouseEvent) => {
            const pos = getScreenCoords(e.clientX, e.clientY);
            handleMove(pos.x, pos.y, e.movementX, e.movementY);
        };
        const handleMouseUp = (e: MouseEvent) => {
            const pos = getScreenCoords(e.clientX, e.clientY);
            handleUp(pos.x, pos.y);
        };

        const onTouchStart = (e: TouchEvent) => {
            if (e.touches.length === 1) {
                const pos = getScreenCoords(e.touches[0].clientX, e.touches[0].clientY);
                lastTouchPos.current = pos;
                handleDown(pos.x, pos.y, 0);
            } else if (e.touches.length === 2) {
                const t1 = getScreenCoords(e.touches[0].clientX, e.touches[0].clientY);
                const t2 = getScreenCoords(e.touches[1].clientX, e.touches[1].clientY);
                lastPinchDist.current = Math.hypot(t1.x - t2.x, t1.y - t2.y);
                // Reset interaction if pinch starts
                interactionMode.current = 'IDLE';
                pressedAgentRef.current = null;
                draggedObstacleRef.current = null;
            }
        };

        const onTouchMove = (e: TouchEvent) => {
            if (e.cancelable) e.preventDefault(); 
            if (e.touches.length === 1 && lastTouchPos.current) {
                const pos = getScreenCoords(e.touches[0].clientX, e.touches[0].clientY);
                const dx = pos.x - lastTouchPos.current.x;
                const dy = pos.y - lastTouchPos.current.y;
                handleMove(pos.x, pos.y, dx, dy);
                lastTouchPos.current = pos;
            } else if (e.touches.length === 2) {
                const t1 = getScreenCoords(e.touches[0].clientX, e.touches[0].clientY);
                const t2 = getScreenCoords(e.touches[1].clientX, e.touches[1].clientY);
                const currentDist = Math.hypot(t1.x - t2.x, t1.y - t2.y);

                if (lastPinchDist.current > 0) {
                    const delta = currentDist - lastPinchDist.current;
                    const zoomSensitivity = 0.005;
                    camera.current.zoom = Math.max(0.5, Math.min(3.0, camera.current.zoom + delta * zoomSensitivity));
                }
                lastPinchDist.current = currentDist;
            }
        };

        const onTouchEnd = (e: TouchEvent) => {
            if (e.cancelable) e.preventDefault();
            if (e.changedTouches.length > 0 && lastTouchPos.current) {
                const pos = getScreenCoords(e.changedTouches[0].clientX, e.changedTouches[0].clientY);
                handleUp(pos.x, pos.y);
            }
            lastTouchPos.current = null;
            lastPinchDist.current = 0;
        };

        const handleWheel = (e: WheelEvent) => {
            e.preventDefault();
            const delta = e.deltaY > 0 ? -0.1 : 0.1;
            camera.current.zoom = Math.max(0.5, Math.min(3.0, camera.current.zoom + delta));
        };

        const handleContextMenu = (e: MouseEvent) => e.preventDefault();

        cvs.addEventListener('mousedown', handleMouseDown);
        window.addEventListener('mousemove', handleMouseMove);
        window.addEventListener('mouseup', handleMouseUp);
        cvs.addEventListener('wheel', handleWheel, { passive: false });
        cvs.addEventListener('contextmenu', handleContextMenu);

        cvs.addEventListener('touchstart', onTouchStart, { passive: false });
        cvs.addEventListener('touchmove', onTouchMove, { passive: false });
        cvs.addEventListener('touchend', onTouchEnd, { passive: false });

        return () => {
            cvs.removeEventListener('mousedown', handleMouseDown);
            window.removeEventListener('mousemove', handleMouseMove);
            window.removeEventListener('mouseup', handleMouseUp);
            cvs.removeEventListener('wheel', handleWheel);
            cvs.removeEventListener('contextmenu', handleContextMenu);
            cvs.removeEventListener('touchstart', onTouchStart);
            cvs.removeEventListener('touchmove', onTouchMove);
            cvs.removeEventListener('touchend', onTouchEnd);
        };
    }, [engine, tool, selectedObstacle, hpInput, onSelect, winner, spawnMode, draftRole]);

    return (
        <div ref={wrapperRef} className="w-full h-full overflow-hidden relative bg-slate-950">
            <canvas 
                ref={canvasRef} 
                className={`block shadow-inner w-full h-full`}
                style={{ backgroundColor: engine.currentScene.background }} 
            />

            {/* STANDARD MODE VICTORY SCREEN */}
            {winner !== null && !isShowcaseMode && (
                <div className="absolute inset-0 flex items-center justify-center bg-black/70 z-50 pointer-events-auto">
                    <div className="text-center p-8 bg-slate-900 rounded-lg border border-slate-700 shadow-2xl animate-bounce-in">
                        <h2 className={`text-4xl font-bold mb-4 font-serif tracking-widest ${winner === Team.BLUE ? 'text-blue-400' : 'text-red-400'}`}>
                            {winner === Team.BLUE ? 'VICTORY' : 'DEFEAT'}
                        </h2>
                        <button onClick={rematch} className="bg-slate-700 hover:bg-slate-600 text-white font-bold py-2 px-6 rounded border border-slate-500">REMATCH</button>
                    </div>
                </div>
            )}
        </div>
    );
};

export default GameCanvas;

import React, { useRef, useEffect } from 'react';
import { Agent, GameEngine } from '../engine/game';
import { GameRenderer } from '../engine/renderer';
import { HexUtils } from '../engine/utils';
import { SpriteManager } from '../engine/sprites';
import { Team, ToolType, Hex, Skill, GameEvent, Role } from '../types';
import { BLOCK_HEIGHT } from '../constants'; 

interface GameCanvasProps {
    engine: GameEngine;
    tool: ToolType;
    selectedObstacle: string; 
    hpInput: number;
    selectedAgent: Agent | null; 
    hoveredSkill: Skill | null;
    isShowcaseMode: boolean; 
    spawnMode: 'RANDOM' | 'DRAFT';
    draftRole: Role; 
    onSelect: (a: Agent | null) => void;
    onWin: (team: Team) => void;
    winner: Team | null;
    rematch: () => void;
    transitionPhase: 'IDLE' | 'IN' | 'OUT';
}

const GameCanvas: React.FC<GameCanvasProps> = ({ engine, tool, selectedObstacle, hpInput, selectedAgent, hoveredSkill, isShowcaseMode, spawnMode, draftRole, onSelect, onWin, winner, rematch, transitionPhase }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const wrapperRef = useRef<HTMLDivElement>(null);
    const camera = useRef({ x: 0, y: 0, zoom: 1.0 }); 
    const fpsRef = useRef(60);

    // Instantiate Renderer
    const rendererRef = useRef(new GameRenderer());
    const transitionStartTime = useRef(0);

    // Bridge for Synchronous Redraw
    const drawCurrentFrameRef = useRef<() => void>(() => {});

    // Handle Transition Phase Timing
    useEffect(() => {
        transitionStartTime.current = performance.now();
    }, [transitionPhase]);

    // --- INTERACTION STATE ---
    // Interaction Mode State Machine
    type InteractionMode = 'IDLE' | 'DOWN' | 'DRAG_UNIT' | 'DRAG_OBS' | 'PAN' | 'PAINT';
    const interactionMode = useRef<InteractionMode>('IDLE');

    // Unit Dragging
    const pressedAgentRef = useRef<Agent | null>(null);

    // Obstacle Dragging
    const draggedObstacleRef = useRef<{ 
        type: string; 
        originQ: number; 
        originR: number; 
        px: number; 
        py: number; 
    } | null>(null);

    // General Input State
    const pressStartPos = useRef<{x: number, y: number} | null>(null);
    const dragStartHex = useRef<{q: number, r: number} | null>(null);
    const lastPaintHex = useRef<string>(""); 

    // Touch specific state
    const lastPinchDist = useRef<number>(0);
    const lastTouchPos = useRef<{x: number, y: number} | null>(null);

    // Track hovered hex for visual feedback
    const hoveredHexRef = useRef<Hex | null>(null);

    // Track selected agent for the render loop
    const selectedAgentRef = useRef<Agent | null>(selectedAgent);
    useEffect(() => {
        selectedAgentRef.current = selectedAgent;
    }, [selectedAgent]);

    // --- Camera Control Logic ---
    const centerCamera = () => {
        if (!canvasRef.current || !wrapperRef.current) return;

        canvasRef.current.width = wrapperRef.current.clientWidth;
        canvasRef.current.height = wrapperRef.current.clientHeight;

        const cw = engine.mapConfig.w;
        const ch = engine.mapConfig.h;

        const centerHex = { q: Math.floor(cw / 2), r: Math.floor(ch / 2) };
        const p = HexUtils.toPx(centerHex.q, centerHex.r, engine.mapConfig);
        const verticalOffset = -BLOCK_HEIGHT * 2; 

        camera.current.x = p.x - (canvasRef.current.width / camera.current.zoom) / 2;
        camera.current.y = p.y + verticalOffset - (canvasRef.current.height / camera.current.zoom) / 2;
    };

    useEffect(() => {
        if (isShowcaseMode || transitionPhase === 'IN') {
            const t = setTimeout(centerCamera, 350);
            return () => clearTimeout(t);
        } else if (!isShowcaseMode && transitionPhase === 'IDLE') {
             const t = setTimeout(centerCamera, 350);
             return () => clearTimeout(t);
        }
    }, [isShowcaseMode, transitionPhase, engine.mapConfig.w, engine.mapConfig.h]);

    useEffect(() => {
        if (!wrapperRef.current || !canvasRef.current) return;

        const resizeObserver = new ResizeObserver(() => {
            // Fix: Wrap in requestAnimationFrame to avoid "ResizeObserver loop completed with undelivered notifications"
            window.requestAnimationFrame(() => {
                if (wrapperRef.current && canvasRef.current) {
                    canvasRef.current.width = wrapperRef.current.clientWidth;
                    canvasRef.current.height = wrapperRef.current.clientHeight;
                    if (engine.agents.length === 0) centerCamera();
                    drawCurrentFrameRef.current();
                }
            });
        });

        resizeObserver.observe(wrapperRef.current);
        centerCamera();

        return () => resizeObserver.disconnect();
    }, [engine]);

    // Render Loop
    useEffect(() => {
        let frameId: number;
        let lastTime = 0;
        let acc = 0;
        const targetFPS = 60;
        const step = 1000 / targetFPS;
        let frameCount = 0;
        let lastFpsTime = 0;

        const drawFrame = () => {
            const ctx = canvasRef.current?.getContext('2d');
            if (ctx && canvasRef.current) {
                const highlight = pressedAgentRef.current || selectedAgentRef.current || null;
                rendererRef.current.draw(ctx, engine, camera.current, highlight, fpsRef.current, hoveredHexRef.current, hoveredSkill); 

                // Draw Dragged Obstacle Ghost
                if (draggedObstacleRef.current) {
                    const { type, px, py } = draggedObstacleRef.current;
                    const { x, y, zoom } = camera.current;
                    const { width, height } = canvasRef.current;

                    ctx.save();
                    ctx.translate(width / 2, height / 2);
                    ctx.scale(zoom, zoom);
                    ctx.translate(-x - width / 2 / zoom, -y - height / 2 / zoom);

                    const sprite = SpriteManager.getObstacleSprite(type);
                    const liftOffset = 40; // Higher lift for visibility
                    ctx.shadowColor = 'rgba(0,0,0,0.5)';
                    ctx.shadowBlur = 30;
                    ctx.shadowOffsetY = 30;
                    ctx.globalAlpha = 0.9;
                    // Adjusted offset from 86 to 80 to match engine renderer
                    ctx.drawImage(sprite, px - 32, py - 80 - liftOffset);
                    ctx.restore();
                }
            }
        };

        drawCurrentFrameRef.current = drawFrame;

        const loop = (t: number) => {
            if (!lastTime) lastTime = t;
            const dt = t - lastTime;
            lastTime = t;

            frameCount++;
            if (t - lastFpsTime >= 1000) {
                fpsRef.current = frameCount;
                frameCount = 0;
                lastFpsTime = t;
            }

            if (engine.isRunning) {
                acc += dt;
                if (acc > 200) acc = 200;
                const frameEvents: GameEvent[] = [];
                while (acc >= step) {
                    const sdt = (step / 1000) * engine.timeScale;
                    engine.tick(sdt);
                    engine.battleTime += sdt;
                    acc -= step;
                    frameEvents.push(...engine.events);
                }
                if (frameEvents.length > 0) {
                    rendererRef.current.processEventsWithEngine(frameEvents, engine);
                }
            }

            rendererRef.current.update(dt / 1000, engine);

            if (transitionPhase !== 'IDLE') {
                const elapsed = (performance.now() - transitionStartTime.current) / 1000;
                const progress = Math.min(1.0, elapsed / 1.2);
                rendererRef.current.setTransition(progress, transitionPhase);
            } else {
                rendererRef.current.setTransition(0, 'IDLE');
            }

            drawFrame();
            frameId = requestAnimationFrame(loop);
        };

        engine.onWin = (team) => { onWin(team); };
        frameId = requestAnimationFrame(loop);
        return () => cancelAnimationFrame(frameId);
    }, [engine, onWin, hoveredSkill, transitionPhase]);

    // Input Handling
    useEffect(() => {
        const cvs = canvasRef.current;
        if (!cvs) return;

        const getScreenCoords = (x: number, y: number) => {
            const rect = cvs.getBoundingClientRect();
            return { x: x - rect.left, y: y - rect.top };
        };

        const getHexFromCoords = (sx: number, sy: number) => {
            const hex = rendererRef.current.getHexAtScreenPoint(sx, sy, camera.current, engine);
            if (hex) return hex;
            return HexUtils.fromPx(
                sx / camera.current.zoom + camera.current.x,
                sy / camera.current.zoom + camera.current.y,
                engine.mapConfig
            );
        };

        const getHitAgentFromCoords = (sx: number, sy: number) => {
            const wx = sx / camera.current.zoom + camera.current.x;
            const wy = sy / camera.current.zoom + camera.current.y;
            const sorted = [...engine.agents].sort((a, b) => b.py - a.py);

            for (const agent of sorted) {
                if (agent.hp <= 0 && agent.fullyDead) continue;
                const h = rendererRef.current.getTerrainHeight(agent.q, agent.r, engine);
                const baseX = agent.px;
                const baseY = agent.py - h;
                const dx = Math.abs(wx - baseX);
                const dy = wy - (baseY - 40); 
                if (dx < 35 && Math.abs(dy) < 60) return agent;
            }
            return null;
        };

        const getWorldPosFromCoords = (sx: number, sy: number) => {
            const wx = sx / camera.current.zoom + camera.current.x;
            const hex = rendererRef.current.getHexAtScreenPoint(sx, sy, camera.current, engine);
            let h = BLOCK_HEIGHT + 6;
            if (hex) h = rendererRef.current.getTerrainHeight(hex.q, hex.r, engine);
            const wy = sy / camera.current.zoom + camera.current.y + h;
            return { x: wx, y: wy };
        };

        const executeToolAction = (h: Hex) => {
            if (engine.isRunning || winner !== null) return;
            const k = HexUtils.key(h);
            if (lastPaintHex.current === k) return; 

            lastPaintHex.current = k;
            const existingAgent = engine.getAgentAt(h.q, h.r);
            let agent: Agent | null = null;

            if (tool === ToolType.DELETE) {
                if (engine.hasObstacle(h.q, h.r)) engine.removeObstacle(h.q, h.r);
                if (existingAgent) {
                    engine.removeAgent(h.q, h.r);
                    onSelect(null);
                }
                return;
            }

            if (tool === ToolType.OBSTACLE) {
                if (existingAgent) engine.removeAgent(h.q, h.r);
                engine.setObstacle(h.q, h.r, selectedObstacle);
                return;
            }

            if (!existingAgent && !engine.hasObstacle(h.q, h.r)) {
                if (tool === ToolType.ADD_BLUE) agent = engine.addAgent(Team.BLUE, h.q, h.r, hpInput);
                else if (tool === ToolType.ADD_RED) agent = engine.addAgent(Team.RED, h.q, h.r, hpInput);
            }

            if (agent && spawnMode === 'DRAFT') {
                agent.role = draftRole;
                const validSkills = engine.skillDB.filter(s => s.role === agent!.role && (s.team === undefined || s.team === agent!.team));
                const rnd = (ar: Skill[]) => ar.length > 0 ? ar[Math.floor(Math.random() * ar.length)].id : null;
                agent.skillIds = [
                    rnd(validSkills.filter(s => s.tag === 'ULT')),
                    rnd(validSkills.filter(s => s.tag === 'ACTIVE')),
                    rnd(validSkills.filter(s => s.tag === 'BASIC'))
                ];
                agent.saveState();
                agent.reset(engine.mapConfig);
            }
        };

        // --- UNIFIED INPUT HANDLER ---

        const handleDown = (sx: number, sy: number, button: number = 0) => {
            pressStartPos.current = { x: sx, y: sy };
            lastPaintHex.current = "";
            interactionMode.current = 'DOWN';

            // Right Click always Pans
            if (button === 2) {
                interactionMode.current = 'PAN';
                return;
            }

            if (engine.isRunning) {
                interactionMode.current = 'PAN';
                return;
            }

            // Identify potential targets for drag start
            const hitAgent = getHitAgentFromCoords(sx, sy);
            if (hitAgent) {
                pressedAgentRef.current = hitAgent;
                if (tool !== ToolType.DELETE) {
                    dragStartHex.current = { q: hitAgent.q, r: hitAgent.r };
                }
                // Don't set mode to DRAG_UNIT yet, wait for move threshold
                return;
            }

            // Check Obstacle
            const h = getHexFromCoords(sx, sy);
            const validGrid = engine.isValid(h.q, h.r);

            if (validGrid && engine.hasObstacle(h.q, h.r)) {
                if (tool !== ToolType.DELETE) {
                    // Pre-load obstacle drag data but don't activate
                    const obsType = engine.obstacles.get(HexUtils.key(h));
                    if (obsType) {
                        draggedObstacleRef.current = {
                            type: obsType,
                            originQ: h.q, originR: h.r,
                            px: 0, py: 0
                        };
                    }
                }
            }
        };

        const handleMove = (sx: number, sy: number, dx: number, dy: number) => {
            const h = getHexFromCoords(sx, sy);
            hoveredHexRef.current = engine.isValid(h.q, h.r) ? h : null;

            // Cursor Logic
            const hitAgent = getHitAgentFromCoords(sx, sy);
            if (cvs) {
                if (interactionMode.current === 'DRAG_UNIT' || interactionMode.current === 'DRAG_OBS') cvs.style.cursor = 'grabbing';
                else if (interactionMode.current === 'PAN') cvs.style.cursor = 'move';
                else if (hitAgent) cvs.style.cursor = 'pointer'; 
                else if (engine.hasObstacle(h.q, h.r)) cvs.style.cursor = 'grab';
                else if (tool === ToolType.SELECT) cvs.style.cursor = 'default';
                else cvs.style.cursor = 'crosshair'; 
            }

            // 1. If IDLE, just update cursor (already done above)
            if (interactionMode.current === 'IDLE') return;

            // 2. If PANNING, apply movement
            if (interactionMode.current === 'PAN') {
                camera.current.x -= dx / camera.current.zoom;
                camera.current.y -= dy / camera.current.zoom;
                return;
            }

            // 3. If PAINTING, execute paint
            if (interactionMode.current === 'PAINT') {
                if (engine.isValid(h.q, h.r)) {
                    executeToolAction(h);
                }
                return;
            }

            // 4. If DRAGGING UNIT
            if (interactionMode.current === 'DRAG_UNIT' && pressedAgentRef.current) {
                const wPos = getWorldPosFromCoords(sx, sy);
                pressedAgentRef.current.px = wPos.x;
                pressedAgentRef.current.py = wPos.y;
                return;
            }

            // 5. If DRAGGING OBS
            if (interactionMode.current === 'DRAG_OBS' && draggedObstacleRef.current) {
                const wPos = getWorldPosFromCoords(sx, sy);
                draggedObstacleRef.current.px = wPos.x;
                draggedObstacleRef.current.py = wPos.y;
                return;
            }

            // 6. ARBITRATION (Transition from DOWN to specific mode)
            if (interactionMode.current === 'DOWN' && pressStartPos.current) {
                const dist = Math.sqrt((sx - pressStartPos.current.x)**2 + (sy - pressStartPos.current.y)**2);

                // Threshold exceeded: Decide intent
                if (dist > 10) {
                    // A. Prioritize Unit Drag
                    if (pressedAgentRef.current && tool !== ToolType.DELETE) {
                        interactionMode.current = 'DRAG_UNIT';
                        pressedAgentRef.current.physics.z = 20; // Lift visual
                        onSelect(pressedAgentRef.current);
                        return;
                    }

                    // B. Secondary Obstacle Drag
                    if (draggedObstacleRef.current && tool !== ToolType.DELETE) {
                        interactionMode.current = 'DRAG_OBS';
                        // Lift logical obstacle from map
                        const { originQ, originR } = draggedObstacleRef.current;
                        engine.removeObstacle(originQ, originR);
                        onSelect(null);

                        // Set initial visual pos
                        const wPos = getWorldPosFromCoords(sx, sy);
                        draggedObstacleRef.current.px = wPos.x;
                        draggedObstacleRef.current.py = wPos.y;
                        return;
                    }

                    // C. Paint vs Pan
                    // If hitting a valid tile AND using a paint-friendly tool (Obstacle/Delete)
                    if (engine.isValid(h.q, h.r) && (tool === ToolType.OBSTACLE || tool === ToolType.DELETE)) {
                        interactionMode.current = 'PAINT';
                        executeToolAction(h);
                    } else {
                        // Default to Pan for Unit Spawning tools or Select tool on empty space
                        interactionMode.current = 'PAN';

                        // FIX for Mobile "Sticky Pan" and Sinking:
                        // Apply the TOTAL accumulated distance since pressStart, not just this frame's delta (dx).
                        // If we use 'dx' here, we lose the first 10px of movement, making it feel laggy.
                        // Also prevents weird drifting if delta calc was slightly off during mode switch.
                        const totalDx = sx - pressStartPos.current.x;
                        const totalDy = sy - pressStartPos.current.y;

                        camera.current.x -= totalDx / camera.current.zoom;
                        camera.current.y -= totalDy / camera.current.zoom;
                    }
                }
            }
        };

        const handleUp = (sx: number, sy: number) => {
            const h = getHexFromCoords(sx, sy);

            // 1. CLICK Logic (If we never left DOWN state)
            if (interactionMode.current === 'DOWN') {
                if (pressedAgentRef.current) {
                    if (tool === ToolType.DELETE) {
                        const a = pressedAgentRef.current;
                        engine.removeAgent(a.q, a.r);
                        onSelect(null);
                    } else {
                        onSelect(pressedAgentRef.current);
                    }
                } else if (engine.hasObstacle(h.q, h.r)) {
                    if (tool === ToolType.DELETE) {
                        engine.removeObstacle(h.q, h.r);
                    }
                    // Else: Select obstacle? Not implemented, maybe highlight.
                } else if (tool !== ToolType.SELECT && tool !== ToolType.DELETE) {
                    // Place Unit logic
                    if (engine.isValid(h.q, h.r)) executeToolAction(h);
                } else {
                    // Click on empty/void with Select tool
                    onSelect(null);
                }
            }

            // 2. Drop Unit
            if (interactionMode.current === 'DRAG_UNIT' && pressedAgentRef.current) {
                const agent = pressedAgentRef.current;
                const isValidHex = engine.isValid(h.q, h.r);
                const isObstacle = engine.obstacles.has(HexUtils.key(h));
                const occupant = engine.getAgentAt(h.q, h.r);
                const isOccupiedByOther = occupant && occupant !== agent;

                agent.physics.z = 0; // Drop visual

                if (isValidHex && !isObstacle && !isOccupiedByOther) {
                    engine.updateAgentPosition(agent, h.q, h.r);
                    const p = HexUtils.toPx(h.q, h.r, engine.mapConfig);
                    agent.px = p.x; agent.py = p.y;
                } else {
                    // Revert
                    if (dragStartHex.current) {
                        agent.q = dragStartHex.current.q;
                        agent.r = dragStartHex.current.r;
                        const p = HexUtils.toPx(agent.q, agent.r, engine.mapConfig);
                        agent.px = p.x; agent.py = p.y;
                        engine.updateAgentPosition(agent, agent.q, agent.r);
                    }
                }
                onSelect(agent);
            }

            // 3. Drop Obstacle
            if (interactionMode.current === 'DRAG_OBS' && draggedObstacleRef.current) {
                const { type, originQ, originR } = draggedObstacleRef.current;
                const isValidHex = engine.isValid(h.q, h.r);
                const occupant = engine.getAgentAt(h.q, h.r);
                const hasExistingObstacle = engine.hasObstacle(h.q, h.r);

                if (isValidHex && !occupant && !hasExistingObstacle) {
                    engine.setObstacle(h.q, h.r, type);
                } else {
                    engine.setObstacle(originQ, originR, type); // Revert
                }
            }

            // Reset
            interactionMode.current = 'IDLE';
            pressedAgentRef.current = null;
            draggedObstacleRef.current = null;
            pressStartPos.current = null;
            lastPaintHex.current = "";
            if (cvs) cvs.style.cursor = 'default';
        };

        // Event Listeners
        const handleMouseDown = (e: MouseEvent) => {
            const pos = getScreenCoords(e.clientX, e.clientY);
            handleDown(pos.x, pos.y, e.button);
        };
        const handleMouseMove = (e: MouseEvent) => {
            const pos = getScreenCoords(e.clientX, e.clientY);
            handleMove(pos.x, pos.y, e.movementX, e.movementY);
        };
        const handleMouseUp = (e: MouseEvent) => {
            const pos = getScreenCoords(e.clientX, e.clientY);
            handleUp(pos.x, pos.y);
        };

        const onTouchStart = (e: TouchEvent) => {
            // Preventing default here is crucial for mobile. 
            // It stops browser scrolling, zooming, and "pull-to-refresh" behaviors that confuse the canvas coordinates.
            if (e.cancelable) e.preventDefault();

            if (e.touches.length === 1) {
                const pos = getScreenCoords(e.touches[0].clientX, e.touches[0].clientY);
                lastTouchPos.current = pos;
                handleDown(pos.x, pos.y, 0);
            } else if (e.touches.length === 2) {
                const t1 = getScreenCoords(e.touches[0].clientX, e.touches[0].clientY);
                const t2 = getScreenCoords(e.touches[1].clientX, e.touches[1].clientY);
                lastPinchDist.current = Math.hypot(t1.x - t2.x, t1.y - t2.y);
                // Reset interaction if pinch starts
                interactionMode.current = 'IDLE';
                pressedAgentRef.current = null;
                draggedObstacleRef.current = null;
            }
        };

        const onTouchMove = (e: TouchEvent) => {
            if (e.cancelable) e.preventDefault(); 
            if (e.touches.length === 1 && lastTouchPos.current) {
                const pos = getScreenCoords(e.touches[0].clientX, e.touches[0].clientY);
                const dx = pos.x - lastTouchPos.current.x;
                const dy = pos.y - lastTouchPos.current.y;
                handleMove(pos.x, pos.y, dx, dy);
                lastTouchPos.current = pos;
            } else if (e.touches.length === 2) {
                const t1 = getScreenCoords(e.touches[0].clientX, e.touches[0].clientY);
                const t2 = getScreenCoords(e.touches[1].clientX, e.touches[1].clientY);
                const currentDist = Math.hypot(t1.x - t2.x, t1.y - t2.y);

                if (lastPinchDist.current > 0) {
                    const delta = currentDist - lastPinchDist.current;
                    const zoomSensitivity = 0.005;
                    camera.current.zoom = Math.max(0.5, Math.min(3.0, camera.current.zoom + delta * zoomSensitivity));
                }
                lastPinchDist.current = currentDist;
            }
        };

        const onTouchEnd = (e: TouchEvent) => {
            if (e.cancelable) e.preventDefault();
            if (e.changedTouches.length > 0 && lastTouchPos.current) {
                const pos = getScreenCoords(e.changedTouches[0].clientX, e.changedTouches[0].clientY);
                handleUp(pos.x, pos.y);
            }
            lastTouchPos.current = null;
            lastPinchDist.current = 0;
        };

        const handleWheel = (e: WheelEvent) => {
            e.preventDefault();
            const delta = e.deltaY > 0 ? -0.1 : 0.1;
            camera.current.zoom = Math.max(0.5, Math.min(3.0, camera.current.zoom + delta));
        };

        const handleContextMenu = (e: MouseEvent) => e.preventDefault();

        cvs.addEventListener('mousedown', handleMouseDown);
        window.addEventListener('mousemove', handleMouseMove);
        window.addEventListener('mouseup', handleMouseUp);
        cvs.addEventListener('wheel', handleWheel, { passive: false });
        cvs.addEventListener('contextmenu', handleContextMenu);

        cvs.addEventListener('touchstart', onTouchStart, { passive: false });
        cvs.addEventListener('touchmove', onTouchMove, { passive: false });
        cvs.addEventListener('touchend', onTouchEnd, { passive: false });

        return () => {
            cvs.removeEventListener('mousedown', handleMouseDown);
            window.removeEventListener('mousemove', handleMouseMove);
            window.removeEventListener('mouseup', handleMouseUp);
            cvs.removeEventListener('wheel', handleWheel);
            cvs.removeEventListener('contextmenu', handleContextMenu);
            cvs.removeEventListener('touchstart', onTouchStart);
            cvs.removeEventListener('touchmove', onTouchMove);
            cvs.removeEventListener('touchend', onTouchEnd);
        };
    }, [engine, tool, selectedObstacle, hpInput, onSelect, winner, spawnMode, draftRole]);

    return (
        <div ref={wrapperRef} className="w-full h-full overflow-hidden relative bg-slate-950">
            <canvas 
                ref={canvasRef} 
                className={`block shadow-inner w-full h-full`}
                style={{ 
                    backgroundColor: engine.currentScene.background,
                    touchAction: 'none' // Important: Disables browser touch handling
                }} 
            />

            {/* STANDARD MODE VICTORY SCREEN */}
            {winner !== null && !isShowcaseMode && (
                <div className="absolute inset-0 flex items-center justify-center bg-black/70 z-50 pointer-events-auto">
                    <div className="text-center p-8 bg-slate-900 rounded-lg border border-slate-700 shadow-2xl animate-bounce-in">
                        <h2 className={`text-4xl font-bold mb-4 font-serif tracking-widest ${winner === Team.BLUE ? 'text-blue-400' : 'text-red-400'}`}>
                            {winner === Team.BLUE ? 'VICTORY' : 'DEFEAT'}
                        </h2>
                        <button onClick={rematch} className="bg-slate-700 hover:bg-slate-600 text-white font-bold py-2 px-6 rounded border border-slate-500">REMATCH</button>
                    </div>
                </div>
            )}
        </div>
    );
};

export default GameCanvas;

import { useRef, useEffect, MutableRefObject } from 'react';
import { GameEngine, GameEvent } from '../engine/game';
import { GameRenderer } from '../engine/renderer';

export const useGameLoop = (
    engine: GameEngine,
    canvasRef: MutableRefObject<HTMLCanvasElement | null>,
    wrapperRef: MutableRefObject<HTMLDivElement | null>,
    rendererRef: MutableRefObject<GameRenderer>,
    onDraw: (ctx: CanvasRenderingContext2D, fps: number) => void,
    onResize: () => void
) => {
    const fpsRef = useRef(60);
    const frameRef = useRef<number>(0);
    const transitionStartTime = useRef(0);

    // Resize Observer with Safety Check
    useEffect(() => {
        if (!wrapperRef.current || !canvasRef.current) return;

        const resizeObserver = new ResizeObserver(() => {
            // Prevent "ResizeObserver loop completed with undelivered notifications"
            window.requestAnimationFrame(() => {
                if (wrapperRef.current && canvasRef.current) {
                    canvasRef.current.width = wrapperRef.current.clientWidth;
                    canvasRef.current.height = wrapperRef.current.clientHeight;
                    onResize();
                }
            });
        });

        resizeObserver.observe(wrapperRef.current);
        return () => resizeObserver.disconnect();
    }, [wrapperRef, canvasRef, onResize]);

    // Main Loop
    useEffect(() => {
        let lastTime = 0;
        let acc = 0;
        const targetFPS = 60;
        const step = 1000 / targetFPS;
        let frameCount = 0;
        let lastFpsTime = 0;

        const loop = (t: number) => {
            if (!canvasRef.current) return;
            const ctx = canvasRef.current.getContext('2d');
            if (!ctx) return;

            if (!lastTime) lastTime = t;
            const dt = t - lastTime;
            lastTime = t;

            // FPS Counter
            frameCount++;
            if (t - lastFpsTime >= 1000) {
                fpsRef.current = frameCount;
                frameCount = 0;
                lastFpsTime = t;
            }

            // Logic Update (Fixed Time Step)
            if (engine.isRunning) {
                acc += dt;
                if (acc > 200) acc = 200; // Spiral of death protection
                const frameEvents: GameEvent[] = [];
                while (acc >= step) {
                    const sdt = (step / 1000) * engine.timeScale;
                    engine.tick(sdt);
                    engine.battleTime += sdt;
                    acc -= step;
                    frameEvents.push(...engine.events);
                }
                if (frameEvents.length > 0) {
                    rendererRef.current.processEventsWithEngine(frameEvents, engine);
                }
            }

            // Render Update (Variable Time Step)
            rendererRef.current.update(dt / 1000, engine);

            // Draw Callback
            onDraw(ctx, fpsRef.current);

            frameRef.current = requestAnimationFrame(loop);
        };

        frameRef.current = requestAnimationFrame(loop);
        return () => cancelAnimationFrame(frameRef.current);
    }, [engine, onDraw]);

    return { fpsRef };
};

import { useRef } from 'react';
import { GameEngine } from '../engine/game';
import { HexUtils } from '../engine/utils';
import { Hex } from '../types';
import { BLOCK_HEIGHT } from '../constants';

export const useGameCamera = (engine: GameEngine) => {
    const camera = useRef({ x: 0, y: 0, zoom: 1.0 });

    const centerCamera = (width: number, height: number) => {
        const cw = engine.mapConfig.w;
        const ch = engine.mapConfig.h;

        const centerHex = { q: Math.floor(cw / 2), r: Math.floor(ch / 2) };
        const p = HexUtils.toPx(centerHex.q, centerHex.r, engine.mapConfig);
        const verticalOffset = -BLOCK_HEIGHT * 2; 

        camera.current.x = p.x - (width / camera.current.zoom) / 2;
        camera.current.y = p.y + verticalOffset - (height / camera.current.zoom) / 2;
    };

    const pan = (dx: number, dy: number) => {
        camera.current.x -= dx / camera.current.zoom;
        camera.current.y -= dy / camera.current.zoom;
    };

    const zoom = (delta: number) => {
        camera.current.zoom = Math.max(0.5, Math.min(3.0, camera.current.zoom + delta));
    };

    // Coordinate Conversions
    const getScreenCoords = (clientX: number, clientY: number, rect: DOMRect) => {
        return { x: clientX - rect.left, y: clientY - rect.top };
    };

    // Note: getHexAtScreenPoint is usually delegated to GridSystem because it needs tile cache,
    // but simple projection can be done here if needed.
    // For consistency with existing logic, we often rely on Renderer's GridSystem for precise hex picking.

    return { 
        camera, 
        centerCamera, 
        pan, 
        zoom,
        getScreenCoords
    };
};

import { useRef, useEffect, MutableRefObject } from 'react';
import { GameEngine, Agent } from '../engine/game';
import { ToolType, Hex, Team, Role, Skill } from '../types';
import { HexUtils } from '../engine/utils';
import { GameRenderer } from '../engine/renderer';
import { BLOCK_HEIGHT } from '../constants';

interface GameInputProps {
    canvasRef: MutableRefObject<HTMLCanvasElement | null>;
    engine: GameEngine;
    rendererRef: MutableRefObject<GameRenderer>;
    cameraRef: MutableRefObject<{ x: number; y: number; zoom: number }>;

    // Tool State
    tool: ToolType;
    selectedObstacle: string;
    hpInput: number;
    spawnMode: 'RANDOM' | 'DRAFT';
    draftRole: Role;
    winner: Team | null;

    // Callbacks
    onSelect: (a: Agent | null) => void;
    onCameraPan: (dx: number, dy: number) => void;
    onCameraZoom: (delta: number) => void;
}

export const useGameInput = ({
    canvasRef, engine, rendererRef, cameraRef,
    tool, selectedObstacle, hpInput, spawnMode, draftRole, winner,
    onSelect, onCameraPan, onCameraZoom
}: GameInputProps) => {

    // Interaction State Machine
    type InteractionMode = 'IDLE' | 'DOWN' | 'DRAG_UNIT' | 'DRAG_OBS' | 'PAN' | 'PAINT';
    const interactionMode = useRef<InteractionMode>('IDLE');

    // Drag Data
    const pressedAgentRef = useRef<Agent | null>(null);
    const draggedObstacleRef = useRef<{ type: string; originQ: number; originR: number; px: number; py: number; } | null>(null);

    // Tracking
    const pressStartPos = useRef<{x: number, y: number} | null>(null);
    const dragStartHex = useRef<{q: number, r: number} | null>(null);
    const lastPaintHex = useRef<string>(""); 

    // Touch
    const lastPinchDist = useRef<number>(0);
    const lastTouchPos = useRef<{x: number, y: number} | null>(null);
    const hoveredHexRef = useRef<Hex | null>(null);

    // --- Helpers ---

    const getHexFromCoords = (sx: number, sy: number) => {
        const hex = rendererRef.current.getHexAtScreenPoint(sx, sy, cameraRef.current, engine);
        if (hex) return hex;
        // Fallback: Plane projection
        return HexUtils.fromPx(
            sx / cameraRef.current.zoom + cameraRef.current.x,
            sy / cameraRef.current.zoom + cameraRef.current.y,
            engine.mapConfig
        );
    };

    const getWorldPosFromCoords = (sx: number, sy: number) => {
        const wx = sx / cameraRef.current.zoom + cameraRef.current.x;
        const hex = rendererRef.current.getHexAtScreenPoint(sx, sy, cameraRef.current, engine);
        let h = BLOCK_HEIGHT + 6;
        if (hex) h = rendererRef.current.getTerrainHeight(hex.q, hex.r, engine);
        const wy = sy / cameraRef.current.zoom + cameraRef.current.y + h;
        return { x: wx, y: wy };
    };

    const getHitAgentFromCoords = (sx: number, sy: number) => {
        const wx = sx / cameraRef.current.zoom + cameraRef.current.x;
        const wy = sy / cameraRef.current.zoom + cameraRef.current.y;
        const sorted = [...engine.agents].sort((a, b) => b.py - a.py); // Front to back

        for (const agent of sorted) {
            if (agent.hp <= 0 && agent.fullyDead) continue;
            const h = rendererRef.current.getTerrainHeight(agent.q, agent.r, engine);
            const baseX = agent.px;
            const baseY = agent.py - h;
            const dx = Math.abs(wx - baseX);
            const dy = wy - (baseY - 40); 
            if (dx < 35 && Math.abs(dy) < 60) return agent;
        }
        return null;
    };

    const executeToolAction = (h: Hex) => {
        if (engine.isRunning || winner !== null) return;
        const k = HexUtils.key(h);
        if (lastPaintHex.current === k) return; 

        lastPaintHex.current = k;
        const existingAgent = engine.getAgentAt(h.q, h.r);
        let agent: Agent | null = null;

        if (tool === ToolType.DELETE) {
            if (engine.hasObstacle(h.q, h.r)) engine.removeObstacle(h.q, h.r);
            if (existingAgent) {
                engine.removeAgent(h.q, h.r);
                onSelect(null);
            }
            return;
        }

        if (tool === ToolType.OBSTACLE) {
            if (existingAgent) engine.removeAgent(h.q, h.r);
            engine.setObstacle(h.q, h.r, selectedObstacle);
            return;
        }

        if (!existingAgent && !engine.hasObstacle(h.q, h.r)) {
            if (tool === ToolType.ADD_BLUE) agent = engine.addAgent(Team.BLUE, h.q, h.r, hpInput);
            else if (tool === ToolType.ADD_RED) agent = engine.addAgent(Team.RED, h.q, h.r, hpInput);
        }

        if (agent && spawnMode === 'DRAFT') {
            agent.role = draftRole;
            const validSkills = engine.skillDB.filter(s => s.role === agent!.role && (s.team === undefined || s.team === agent!.team));
            const rnd = (ar: Skill[]) => ar.length > 0 ? ar[Math.floor(Math.random() * ar.length)].id : null;
            agent.skillIds = [
                rnd(validSkills.filter(s => s.tag === 'ULT')),
                rnd(validSkills.filter(s => s.tag === 'ACTIVE')),
                rnd(validSkills.filter(s => s.tag === 'BASIC'))
            ];
            agent.saveState();
            agent.reset(engine.mapConfig);
        }
    };

    // --- Input Handlers ---

    const handleDown = (sx: number, sy: number, button: number = 0) => {
        pressStartPos.current = { x: sx, y: sy };
        lastPaintHex.current = "";
        interactionMode.current = 'DOWN';

        if (button === 2 || engine.isRunning) {
            interactionMode.current = 'PAN';
            return;
        }

        const hitAgent = getHitAgentFromCoords(sx, sy);
        if (hitAgent) {
            pressedAgentRef.current = hitAgent;
            if (tool !== ToolType.DELETE) {
                dragStartHex.current = { q: hitAgent.q, r: hitAgent.r };
            }
            return;
        }

        const h = getHexFromCoords(sx, sy);
        if (engine.isValid(h.q, h.r) && engine.hasObstacle(h.q, h.r) && tool !== ToolType.DELETE) {
            const obsType = engine.obstacles.get(HexUtils.key(h));
            if (obsType) {
                draggedObstacleRef.current = { type: obsType, originQ: h.q, originR: h.r, px: 0, py: 0 };
            }
        }
    };

    const handleMove = (sx: number, sy: number, dx: number, dy: number) => {
        const h = getHexFromCoords(sx, sy);
        hoveredHexRef.current = engine.isValid(h.q, h.r) ? h : null;

        // Cursor Management
        const cvs = canvasRef.current;
        if (cvs) {
            const hitAgent = getHitAgentFromCoords(sx, sy);
            if (interactionMode.current === 'DRAG_UNIT' || interactionMode.current === 'DRAG_OBS') cvs.style.cursor = 'grabbing';
            else if (interactionMode.current === 'PAN') cvs.style.cursor = 'move';
            else if (hitAgent) cvs.style.cursor = 'pointer'; 
            else if (engine.hasObstacle(h.q, h.r)) cvs.style.cursor = 'grab';
            else if (tool === ToolType.SELECT) cvs.style.cursor = 'default';
            else cvs.style.cursor = 'crosshair'; 
        }

        if (interactionMode.current === 'IDLE') return;

        if (interactionMode.current === 'PAN') {
            onCameraPan(dx, dy);
            return;
        }

        if (interactionMode.current === 'PAINT') {
            if (engine.isValid(h.q, h.r)) executeToolAction(h);
            return;
        }

        if (interactionMode.current === 'DRAG_UNIT' && pressedAgentRef.current) {
            const wPos = getWorldPosFromCoords(sx, sy);
            pressedAgentRef.current.px = wPos.x;
            pressedAgentRef.current.py = wPos.y;
            return;
        }

        if (interactionMode.current === 'DRAG_OBS' && draggedObstacleRef.current) {
            const wPos = getWorldPosFromCoords(sx, sy);
            draggedObstacleRef.current.px = wPos.x;
            draggedObstacleRef.current.py = wPos.y;
            return;
        }

        // Logic to switch from DOWN to PAN/DRAG/PAINT
        if (interactionMode.current === 'DOWN' && pressStartPos.current) {
            const dist = Math.sqrt((sx - pressStartPos.current.x)**2 + (sy - pressStartPos.current.y)**2);
            if (dist > 10) {
                if (pressedAgentRef.current && tool !== ToolType.DELETE) {
                    interactionMode.current = 'DRAG_UNIT';
                    pressedAgentRef.current.physics.z = 20; 
                    onSelect(pressedAgentRef.current);
                    return;
                }
                if (draggedObstacleRef.current && tool !== ToolType.DELETE) {
                    interactionMode.current = 'DRAG_OBS';
                    const { originQ, originR } = draggedObstacleRef.current;
                    engine.removeObstacle(originQ, originR);
                    onSelect(null);
                    const wPos = getWorldPosFromCoords(sx, sy);
                    draggedObstacleRef.current.px = wPos.x;
                    draggedObstacleRef.current.py = wPos.y;
                    return;
                }
                if (engine.isValid(h.q, h.r) && (tool === ToolType.OBSTACLE || tool === ToolType.DELETE)) {
                    interactionMode.current = 'PAINT';
                    executeToolAction(h);
                } else {
                    interactionMode.current = 'PAN';
                    // Catch up initial movement
                    const totalDx = sx - pressStartPos.current.x;
                    const totalDy = sy - pressStartPos.current.y;
                    onCameraPan(totalDx, totalDy);
                }
            }
        }
    };

    const handleUp = (sx: number, sy: number) => {
        const h = getHexFromCoords(sx, sy);

        // Click Logic
        if (interactionMode.current === 'DOWN') {
            if (pressedAgentRef.current) {
                if (tool === ToolType.DELETE) {
                    engine.removeAgent(pressedAgentRef.current.q, pressedAgentRef.current.r);
                    onSelect(null);
                } else {
                    onSelect(pressedAgentRef.current);
                }
            } else if (engine.hasObstacle(h.q, h.r)) {
                if (tool === ToolType.DELETE) engine.removeObstacle(h.q, h.r);
            } else if (tool !== ToolType.SELECT && tool !== ToolType.DELETE) {
                if (engine.isValid(h.q, h.r)) executeToolAction(h);
            } else {
                onSelect(null);
            }
        }

        // Drop Unit
        if (interactionMode.current === 'DRAG_UNIT' && pressedAgentRef.current) {
            const agent = pressedAgentRef.current;
            agent.physics.z = 0;
            const valid = engine.isValid(h.q, h.r) && !engine.hasObstacle(h.q, h.r) && (!engine.getAgentAt(h.q, h.r) || engine.getAgentAt(h.q, h.r) === agent);

            if (valid) {
                engine.updateAgentPosition(agent, h.q, h.r);
                const p = HexUtils.toPx(h.q, h.r, engine.mapConfig);
                agent.px = p.x; agent.py = p.y;
            } else if (dragStartHex.current) {
                // Revert
                agent.q = dragStartHex.current.q;
                agent.r = dragStartHex.current.r;
                const p = HexUtils.toPx(agent.q, agent.r, engine.mapConfig);
                agent.px = p.x; agent.py = p.y;
                engine.updateAgentPosition(agent, agent.q, agent.r);
            }
            onSelect(agent);
        }

        // Drop Obstacle
        if (interactionMode.current === 'DRAG_OBS' && draggedObstacleRef.current) {
            const { type, originQ, originR } = draggedObstacleRef.current;
            const valid = engine.isValid(h.q, h.r) && !engine.getAgentAt(h.q, h.r) && !engine.hasObstacle(h.q, h.r);

            if (valid) engine.setObstacle(h.q, h.r, type);
            else engine.setObstacle(originQ, originR, type); // Revert
        }

        interactionMode.current = 'IDLE';
        pressedAgentRef.current = null;
        draggedObstacleRef.current = null;
        pressStartPos.current = null;
        lastPaintHex.current = "";
        if (canvasRef.current) canvasRef.current.style.cursor = 'default';
    };

    // --- Listeners Binding ---
    useEffect(() => {
        const cvs = canvasRef.current;
        if (!cvs) return;

        const getCoords = (e: MouseEvent | Touch) => {
            const rect = cvs.getBoundingClientRect();
            return { x: e.clientX - rect.left, y: e.clientY - rect.top };
        };

        const onMouseDown = (e: MouseEvent) => {
            const {x, y} = getCoords(e);
            handleDown(x, y, e.button);
        };
        const onMouseMove = (e: MouseEvent) => {
            const {x, y} = getCoords(e);
            handleMove(x, y, e.movementX, e.movementY);
        };
        const onMouseUp = (e: MouseEvent) => {
            const {x, y} = getCoords(e);
            handleUp(x, y);
        };

        const onTouchStart = (e: TouchEvent) => {
            if (e.cancelable) e.preventDefault();
            if (e.touches.length === 1) {
                const {x, y} = getCoords(e.touches[0]);
                lastTouchPos.current = {x, y};
                handleDown(x, y, 0);
            } else if (e.touches.length === 2) {
                const t1 = getCoords(e.touches[0]);
                const t2 = getCoords(e.touches[1]);
                lastPinchDist.current = Math.hypot(t1.x - t2.x, t1.y - t2.y);
                interactionMode.current = 'IDLE';
                pressedAgentRef.current = null;
                draggedObstacleRef.current = null;
            }
        };

        const onTouchMove = (e: TouchEvent) => {
            if (e.cancelable) e.preventDefault();
            if (e.touches.length === 1 && lastTouchPos.current) {
                const {x, y} = getCoords(e.touches[0]);
                handleMove(x, y, x - lastTouchPos.current.x, y - lastTouchPos.current.y);
                lastTouchPos.current = {x, y};
            } else if (e.touches.length === 2) {
                const t1 = getCoords(e.touches[0]);
                const t2 = getCoords(e.touches[1]);
                const dist = Math.hypot(t1.x - t2.x, t1.y - t2.y);
                if (lastPinchDist.current > 0) {
                    const delta = dist - lastPinchDist.current;
                    onCameraZoom(delta * 0.005);
                }
                lastPinchDist.current = dist;
            }
        };

        const onTouchEnd = (e: TouchEvent) => {
            if (e.cancelable) e.preventDefault();
            if (e.changedTouches.length > 0 && lastTouchPos.current) {
                const {x, y} = getCoords(e.changedTouches[0]);
                handleUp(x, y);
            }
            lastTouchPos.current = null;
            lastPinchDist.current = 0;
        };

        const onWheel = (e: WheelEvent) => {
            e.preventDefault();
            const delta = e.deltaY > 0 ? -0.1 : 0.1;
            onCameraZoom(delta);
        };

        const onCtx = (e: MouseEvent) => e.preventDefault();

        cvs.addEventListener('mousedown', onMouseDown);
        window.addEventListener('mousemove', onMouseMove);
        window.addEventListener('mouseup', onMouseUp);
        cvs.addEventListener('wheel', onWheel, { passive: false });
        cvs.addEventListener('contextmenu', onCtx);
        cvs.addEventListener('touchstart', onTouchStart, { passive: false });
        cvs.addEventListener('touchmove', onTouchMove, { passive: false });
        cvs.addEventListener('touchend', onTouchEnd, { passive: false });

        return () => {
            cvs.removeEventListener('mousedown', onMouseDown);
            window.removeEventListener('mousemove', onMouseMove);
            window.removeEventListener('mouseup', onMouseUp);
            cvs.removeEventListener('wheel', onWheel);
            cvs.removeEventListener('contextmenu', onCtx);
            cvs.removeEventListener('touchstart', onTouchStart);
            cvs.removeEventListener('touchmove', onTouchMove);
            cvs.removeEventListener('touchend', onTouchEnd);
        };
    }, [engine, tool, selectedObstacle, hpInput, spawnMode, draftRole, winner, onSelect, onCameraPan, onCameraZoom]);

    return {
        pressedAgent: pressedAgentRef.current,
        draggedObstacle: draggedObstacleRef.current,
        hoveredHex: hoveredHexRef.current
    };
};

import React, { useRef, useEffect } from 'react';
import { Agent, GameEngine } from '../engine/game';
import { GameRenderer } from '../engine/renderer';
import { SpriteManager } from '../engine/sprites';
import { Team, ToolType, Skill, Role } from '../types';

// Hooks
import { useGameLoop } from '../hooks/useGameLoop';
import { useGameCamera } from '../hooks/useGameCamera';
import { useGameInput } from '../hooks/useGameInput';

interface GameCanvasProps {
    engine: GameEngine;
    tool: ToolType;
    selectedObstacle: string; 
    hpInput: number;
    selectedAgent: Agent | null; 
    hoveredSkill: Skill | null;
    isShowcaseMode: boolean; 
    spawnMode: 'RANDOM' | 'DRAFT';
    draftRole: Role; 
    onSelect: (a: Agent | null) => void;
    onWin: (team: Team) => void;
    winner: Team | null;
    rematch: () => void;
    transitionPhase: 'IDLE' | 'IN' | 'OUT';
}

const GameCanvas: React.FC<GameCanvasProps> = (props) => {
    const { 
        engine, tool, selectedObstacle, hpInput, selectedAgent, hoveredSkill, 
        isShowcaseMode, spawnMode, draftRole, onSelect, onWin, winner, rematch, transitionPhase 
    } = props;

    const canvasRef = useRef<HTMLCanvasElement>(null);
    const wrapperRef = useRef<HTMLDivElement>(null);
    const rendererRef = useRef(new GameRenderer());

    // 1. Camera System
    const { camera, centerCamera, pan, zoom } = useGameCamera(engine);

    // 2. Input System
    const { pressedAgent, draggedObstacle, hoveredHex } = useGameInput({
        canvasRef, engine, rendererRef, cameraRef: camera,
        tool, selectedObstacle, hpInput, spawnMode, draftRole, winner,
        onSelect, onCameraPan: pan, onCameraZoom: zoom
    });

    // 3. Render Loop
    const handleDraw = (ctx: CanvasRenderingContext2D, fps: number) => {
        // Handle Transition FX
        if (transitionPhase !== 'IDLE') {
            // Using a simple approximation for elapsed time here or we'd need to pass start time
            // Ideally GameCanvas tracks start time, but for simplicity relying on loop updates
            // In a full refactor, transition state should be in the loop or engine.
            const now = performance.now();
            // Since we don't have start time in handleDraw args, we rely on hook internal state or pass it.
            // For now, let's assume the renderer handles the interpolation based on global time
            // or we move transition logic fully into renderer update.
            // (Compatibility Fix: We'll set a rough progress in the renderer update cycle inside useGameLoop if needed,
            // but here we just call draw)
        }

        // Pass transition phase to renderer
        // Note: Actual transition timing is best handled in the loop's update phase, 
        // but setting the flag here ensures the drawer knows what to do.
        rendererRef.current.setTransition(0, transitionPhase); // Progress handled in renderer update if we pass time?
        // Wait, the original code calculated progress in the loop. 
        // Let's rely on the renderer's internal state update which we can drive from the loop hook if we expand it,
        // or just let the visual effects play out.
        // For strict compatibility with the previous `useEffect` loop:

        const highlight = pressedAgent || selectedAgent || null;
        rendererRef.current.draw(ctx, engine, camera.current, highlight, fps, hoveredHex, hoveredSkill);

        // Draw Ghost Obstacle (Drag Visual)
        if (draggedObstacle && canvasRef.current) {
            const { type, px, py } = draggedObstacle;
            const { x, y, zoom } = camera.current;
            const { width, height } = canvasRef.current;

            ctx.save();
            ctx.translate(width / 2, height / 2);
            ctx.scale(zoom, zoom);
            ctx.translate(-x - width / 2 / zoom, -y - height / 2 / zoom);

            const sprite = SpriteManager.getObstacleSprite(type);
            const liftOffset = 40; 
            ctx.shadowColor = 'rgba(0,0,0,0.5)';
            ctx.shadowBlur = 30;
            ctx.shadowOffsetY = 30;
            ctx.globalAlpha = 0.9;
            ctx.drawImage(sprite, px - 32, py - 80 - liftOffset);
            ctx.restore();
        }
    };

    const handleResize = () => {
        if(engine.agents.length === 0) {
            if(wrapperRef.current) centerCamera(wrapperRef.current.clientWidth, wrapperRef.current.clientHeight);
        }
    };

    const { fpsRef } = useGameLoop(engine, canvasRef, wrapperRef, rendererRef, handleDraw, handleResize);

    // Initial Camera Center
    useEffect(() => {
        if (wrapperRef.current) {
            centerCamera(wrapperRef.current.clientWidth, wrapperRef.current.clientHeight);
        }
    }, [engine.mapConfig.w, engine.mapConfig.h, isShowcaseMode, transitionPhase]);

    // Win Callback Sync
    useEffect(() => {
        engine.onWin = onWin;
    }, [engine, onWin]);

    return (
        <div ref={wrapperRef} className="w-full h-full overflow-hidden relative bg-slate-950">
            <canvas 
                ref={canvasRef} 
                className={`block shadow-inner w-full h-full`}
                style={{ 
                    backgroundColor: engine.currentScene.background,
                    touchAction: 'none' 
                }} 
            />

            {/* VICTORY SCREEN */}
            {winner !== null && !isShowcaseMode && (
                <div className="absolute inset-0 flex items-center justify-center bg-black/70 z-50 pointer-events-auto">
                    <div className="text-center p-8 bg-slate-900 rounded-lg border border-slate-700 shadow-2xl animate-bounce-in">
                        <h2 className={`text-4xl font-bold mb-4 font-serif tracking-widest ${winner === Team.BLUE ? 'text-blue-400' : 'text-red-400'}`}>
                            {winner === Team.BLUE ? 'VICTORY' : 'DEFEAT'}
                        </h2>
                        <button onClick={rematch} className="bg-slate-700 hover:bg-slate-600 text-white font-bold py-2 px-6 rounded border border-slate-500">REMATCH</button>
                    </div>
                </div>
            )}
        </div>
    );
};

export default GameCanvas;

import { useRef, useEffect, MutableRefObject } from 'react';
import { GameEngine } from '../engine/game';
import { GameEvent } from '../types';
import { GameRenderer } from '../engine/renderer';

export const useGameLoop = (
    engine: GameEngine,
    canvasRef: MutableRefObject<HTMLCanvasElement | null>,
    wrapperRef: MutableRefObject<HTMLDivElement | null>,
    rendererRef: MutableRefObject<GameRenderer>,
    onDraw: (ctx: CanvasRenderingContext2D, fps: number) => void,
    onResize: () => void
) => {
    const fpsRef = useRef(60);
    const frameRef = useRef<number>(0);
    const transitionStartTime = useRef(0);

    // Resize Observer with Safety Check
    useEffect(() => {
        if (!wrapperRef.current || !canvasRef.current) return;

        const resizeObserver = new ResizeObserver(() => {
            // Prevent "ResizeObserver loop completed with undelivered notifications"
            window.requestAnimationFrame(() => {
                if (wrapperRef.current && canvasRef.current) {
                    canvasRef.current.width = wrapperRef.current.clientWidth;
                    canvasRef.current.height = wrapperRef.current.clientHeight;
                    onResize();
                }
            });
        });

        resizeObserver.observe(wrapperRef.current);
        return () => resizeObserver.disconnect();
    }, [wrapperRef, canvasRef, onResize]);

    // Main Loop
    useEffect(() => {
        let lastTime = 0;
        let acc = 0;
        const targetFPS = 60;
        const step = 1000 / targetFPS;
        let frameCount = 0;
        let lastFpsTime = 0;

        const loop = (t: number) => {
            if (!canvasRef.current) return;
            const ctx = canvasRef.current.getContext('2d');
            if (!ctx) return;

            if (!lastTime) lastTime = t;
            const dt = t - lastTime;
            lastTime = t;

            // FPS Counter
            frameCount++;
            if (t - lastFpsTime >= 1000) {
                fpsRef.current = frameCount;
                frameCount = 0;
                lastFpsTime = t;
            }

            // Logic Update (Fixed Time Step)
            if (engine.isRunning) {
                acc += dt;
                if (acc > 200) acc = 200; // Spiral of death protection
                const frameEvents: GameEvent[] = [];
                while (acc >= step) {
                    const sdt = (step / 1000) * engine.timeScale;
                    engine.tick(sdt);
                    engine.battleTime += sdt;
                    acc -= step;
                    frameEvents.push(...engine.events);
                }
                if (frameEvents.length > 0) {
                    rendererRef.current.processEventsWithEngine(frameEvents, engine);
                }
            }

            // Render Update (Variable Time Step)
            rendererRef.current.update(dt / 1000, engine);

            // Draw Callback
            onDraw(ctx, fpsRef.current);

            frameRef.current = requestAnimationFrame(loop);
        };

        frameRef.current = requestAnimationFrame(loop);
        return () => cancelAnimationFrame(frameRef.current);
    }, [engine, onDraw]);

    return { fpsRef };
};

