                                                );
                                            })}
                                        </select>
                                    </div>
                                </div>

                                {currentSkill && (
                                    <div className="p-3 text-sm">
                                        <div className="text-slate-400 italic mb-3 leading-relaxed border-l-2 border-slate-700 pl-3">
                                            "{currentSkill.desc}"
                                        </div>
                                        <div className="grid grid-cols-4 gap-2 text-xs font-mono text-slate-300">
                                            <div className="bg-slate-950 p-2 rounded text-center border border-slate-800">
                                                <div className="text-slate-500 text-[10px] mb-1">威力</div>
                                                <div className="font-bold text-base">{currentSkill.power}</div>
                                            </div>
                                            <div className="bg-slate-950 p-2 rounded text-center border border-slate-800">
                                                <div className="text-slate-500 text-[10px] mb-1">冷卻</div>
                                                <div className="font-bold text-base">{currentSkill.cd}s</div>
                                            </div>
                                            <div className="bg-slate-950 p-2 rounded text-center border border-slate-800">
                                                <div className="text-slate-500 text-[10px] mb-1">消耗</div>
                                                <div className="font-bold text-base text-blue-400">{currentSkill.cost}</div>
                                            </div>
                                            <div className="bg-slate-950 p-2 rounded text-center border border-slate-800">
                                                <div className="text-slate-500 text-[10px] mb-1">射程</div>
                                                <div className="font-bold text-base">{currentSkill.range}</div>
                                            </div>
                                        </div>
                                        {(currentSkill.ccType || currentSkill.effectType) && (
                                            <div className="mt-3 pt-2 border-t border-slate-800 flex gap-2 flex-wrap">
                                                {currentSkill.ccType && <span className="px-2 py-1 bg-amber-900/30 text-amber-400 border border-amber-900/50 rounded text-xs font-bold">{currentSkill.ccType}</span>}
                                                {currentSkill.effectType && <span className="px-2 py-1 bg-purple-900/30 text-purple-400 border border-purple-900/50 rounded text-xs font-bold">{currentSkill.effectType}</span>}
                                            </div>
                                        )}
                                    </div>
                                )}
                            </div>
                        );
                    })}
                </div>
            </div>
        </div>
    );
};

import { useRef, useEffect, MutableRefObject } from 'react';
import { GameEngine } from '../engine/game';
import { GameEvent } from '../types';
import { GameRenderer } from '../engine/renderer';

export const useGameLoop = (
    engine: GameEngine,
    canvasRef: MutableRefObject<HTMLCanvasElement | null>,
    wrapperRef: MutableRefObject<HTMLDivElement | null>,
    rendererRef: MutableRefObject<GameRenderer>,
    onDraw: (ctx: CanvasRenderingContext2D, fps: number) => void,
    onResize: () => void
) => {
    const fpsRef = useRef(60);
    const frameRef = useRef<number>(0);

    // Store callbacks in refs to avoid restarting the loop when parent re-renders
    const drawCallbackRef = useRef(onDraw);
    const resizeCallbackRef = useRef(onResize);

    // Always keep refs updated
    useEffect(() => {
        drawCallbackRef.current = onDraw;
        resizeCallbackRef.current = onResize;
    }, [onDraw, onResize]);

    // Resize Observer with Safety Check
    useEffect(() => {
        if (!wrapperRef.current || !canvasRef.current) return;

        const resizeObserver = new ResizeObserver(() => {
            // Prevent "ResizeObserver loop completed with undelivered notifications"
            window.requestAnimationFrame(() => {
                if (wrapperRef.current && canvasRef.current) {
                    // Sync canvas size explicitly
                    const w = wrapperRef.current.clientWidth;
                    const h = wrapperRef.current.clientHeight;

                    if (w > 0 && h > 0) {
                        canvasRef.current.width = w;
                        canvasRef.current.height = h;
                        resizeCallbackRef.current();
                    }
                }
            });
        });

        resizeObserver.observe(wrapperRef.current);
        return () => resizeObserver.disconnect();
    }, [wrapperRef, canvasRef]);

    // Main Loop
    useEffect(() => {
        let lastTime = 0;
        let acc = 0;
        const targetFPS = 60;
        const step = 1000 / targetFPS;
        let frameCount = 0;
        let lastFpsTime = 0;

        const loop = (t: number) => {
            if (!canvasRef.current) {
                frameRef.current = requestAnimationFrame(loop);
                return;
            }
            const ctx = canvasRef.current.getContext('2d');
            if (!ctx) {
                frameRef.current = requestAnimationFrame(loop);
                return;
            }

            if (!lastTime) lastTime = t;
            const dt = t - lastTime;
            lastTime = t;

            // FPS Counter
            frameCount++;
            if (t - lastFpsTime >= 1000) {
                fpsRef.current = frameCount;
                frameCount = 0;
                lastFpsTime = t;
            }

            // Logic Update (Fixed Time Step)
            if (engine.isRunning) {
                acc += dt;
                // Clamp max time to avoid "Spiral of Death" on slow devices/tab switching
                if (acc > 100) acc = 100; 

                const frameEvents: GameEvent[] = [];
                while (acc >= step) {
                    const sdt = (step / 1000) * engine.timeScale;
                    engine.tick(sdt);
                    engine.battleTime += sdt;
                    acc -= step;
                    frameEvents.push(...engine.events);
                }

                // Process Events strictly once per frame update
                if (frameEvents.length > 0) {
                    rendererRef.current.processEventsWithEngine(frameEvents, engine);
                }
            }

            // Render Update (Variable Time Step)
            rendererRef.current.update(dt / 1000, engine);

            // Draw Callback (Invoke the Ref)
            drawCallbackRef.current(ctx, fpsRef.current);

            frameRef.current = requestAnimationFrame(loop);
        };

        frameRef.current = requestAnimationFrame(loop);
        return () => cancelAnimationFrame(frameRef.current);
    }, [engine, canvasRef, rendererRef]); // Dependencies minimized to prevent loop restart

    return { fpsRef };
};

import { useRef } from 'react';
import { GameEngine } from '../engine/game';
import { HexUtils } from '../engine/utils';
import { Hex } from '../types';
import { BLOCK_HEIGHT } from '../constants';

export const useGameCamera = (engine: GameEngine) => {
    // Default safe values
    const camera = useRef({ x: 0, y: 0, zoom: 1.0 });

    const centerCamera = (width: number, height: number) => {
        // Safety: Mobile browsers might report 0 width during layout thrashing
        if (!width || !height || width <= 0 || height <= 0) return;

        const cw = engine.mapConfig.w;
        const ch = engine.mapConfig.h;

        const centerHex = { q: Math.floor(cw / 2), r: Math.floor(ch / 2) };
        const p = HexUtils.toPx(centerHex.q, centerHex.r, engine.mapConfig);
        const verticalOffset = -BLOCK_HEIGHT * 2; 

        let targetX = p.x - (width / camera.current.zoom) / 2;
        let targetY = p.y + verticalOffset - (height / camera.current.zoom) / 2;

        // NaN Protection
        if (isNaN(targetX)) targetX = 0;
        if (isNaN(targetY)) targetY = 0;

        camera.current.x = targetX;
        camera.current.y = targetY;
    };

    const pan = (dx: number, dy: number) => {
        if (isNaN(dx) || isNaN(dy)) return;
        camera.current.x -= dx / camera.current.zoom;
        camera.current.y -= dy / camera.current.zoom;
    };

    const zoom = (delta: number) => {
        if (isNaN(delta)) return;
        const newZoom = Math.max(0.5, Math.min(3.0, camera.current.zoom + delta));

        // Optional: Zoom towards center of screen (Simplified here to center zoom)
        // Adjusting x/y based on zoom center would be ideal but complex without mouse pos
        camera.current.zoom = newZoom;
    };

    const getScreenCoords = (clientX: number, clientY: number, rect: DOMRect) => {
        return { x: clientX - rect.left, y: clientY - rect.top };
    };

    return { 
        camera, 
        centerCamera, 
        pan, 
        zoom,
        getScreenCoords
    };
};

import React, { useRef, useEffect, useCallback } from 'react';
import { Agent, GameEngine } from '../engine/game';
import { GameRenderer } from '../engine/renderer';
import { SpriteManager } from '../engine/sprites';
import { Team, ToolType, Skill, Role } from '../types';

// Hooks
import { useGameLoop } from '../hooks/useGameLoop';
import { useGameCamera } from '../hooks/useGameCamera';
import { useGameInput } from '../hooks/useGameInput';

interface GameCanvasProps {
    engine: GameEngine;
    tool: ToolType;
    selectedObstacle: string; 
    hpInput: number;
    selectedAgent: Agent | null; 
    hoveredSkill: Skill | null;
    isShowcaseMode: boolean; 
    spawnMode: 'RANDOM' | 'DRAFT';
    draftRole: Role; 
    onSelect: (a: Agent | null) => void;
    onWin: (team: Team) => void;
    winner: Team | null;
    rematch: () => void;
    transitionPhase: 'IDLE' | 'IN' | 'OUT';
}

const GameCanvas: React.FC<GameCanvasProps> = (props) => {
    const { 
        engine, tool, selectedObstacle, hpInput, selectedAgent, hoveredSkill, 
        isShowcaseMode, spawnMode, draftRole, onSelect, onWin, winner, rematch, transitionPhase 
    } = props;

    const canvasRef = useRef<HTMLCanvasElement>(null);
    const wrapperRef = useRef<HTMLDivElement>(null);
    // Persist renderer instance across renders
    const rendererRef = useRef(new GameRenderer());

    // 1. Camera System
    const { camera, centerCamera, pan, zoom } = useGameCamera(engine);

    // 2. Input System
    const { pressedAgent, draggedObstacle, hoveredHex } = useGameInput({
        canvasRef, engine, rendererRef, cameraRef: camera,
        tool, selectedObstacle, hpInput, spawnMode, draftRole, winner,
        onSelect, onCameraPan: pan, onCameraZoom: zoom
    });

    // 3. Render Loop Handler (Memoized to prevent Loop Restart)
    const handleDraw = useCallback((ctx: CanvasRenderingContext2D, fps: number) => {
        // Handle Transition State inside Renderer
        rendererRef.current.setTransition(0, transitionPhase); 

        // Pass current UI selection state to renderer
        const highlight = pressedAgent || selectedAgent || null;

        rendererRef.current.draw(
            ctx, 
            engine, 
            camera.current, 
            highlight, 
            fps, 
            hoveredHex, 
            hoveredSkill
        );

        // Draw Ghost Obstacle (Drag Visual Overlay)
        // Done here instead of inside renderer to keep interaction logic separate
        if (draggedObstacle && canvasRef.current) {
            const { type, px, py } = draggedObstacle;
            const { x, y, zoom: camZoom } = camera.current;
            const { width, height } = canvasRef.current;

            ctx.save();
            // Apply Camera Transform manually for the ghost
            ctx.translate(width / 2, height / 2);
            ctx.scale(camZoom, camZoom);
            ctx.translate(-x - width / 2 / camZoom, -y - height / 2 / camZoom);

            const sprite = SpriteManager.getObstacleSprite(type);
            const liftOffset = 40; 

            // Draw Shadow
            ctx.shadowColor = 'rgba(0,0,0,0.5)';
            ctx.shadowBlur = 30;
            ctx.shadowOffsetY = 30;
            ctx.globalAlpha = 0.9;

            // Match Obstacle Anchor Point (Center bottom roughly)
            ctx.drawImage(sprite, px - 32, py - 80 - liftOffset);
            ctx.restore();
        }
    }, [engine, transitionPhase, pressedAgent, selectedAgent, hoveredHex, hoveredSkill, draggedObstacle, camera]);

    // Resize Handler (Memoized)
    const handleResize = useCallback(() => {
        if(wrapperRef.current) {
            const w = wrapperRef.current.clientWidth;
            const h = wrapperRef.current.clientHeight;
            // Only re-center if map is empty (initial load) or explicit reset requested
            // Otherwise we keep user's pan position
            if(engine.agents.length === 0 || isShowcaseMode) {
                centerCamera(w, h);
            }
        }
    }, [engine, centerCamera, isShowcaseMode]);

    // 4. Hook Up Game Loop
    // Passing stable callbacks prevents internal useEffect cleanup
    const { fpsRef } = useGameLoop(engine, canvasRef, wrapperRef, rendererRef, handleDraw, handleResize);

    // Initial Camera Center (Triggered once or when Map Size/Mode changes)
    useEffect(() => {
        if (wrapperRef.current) {
            // Slight delay to ensure DOM layout is final on mobile
            const t = setTimeout(() => {
                if (wrapperRef.current) {
                    centerCamera(wrapperRef.current.clientWidth, wrapperRef.current.clientHeight);
                }
            }, 100);
            return () => clearTimeout(t);
        }
    }, [engine.mapConfig.w, engine.mapConfig.h, isShowcaseMode, transitionPhase, centerCamera]);

    // Win Callback Sync
    useEffect(() => {
        engine.onWin = onWin;
    }, [engine, onWin]);

    return (
        <div ref={wrapperRef} className="w-full h-full overflow-hidden relative bg-slate-950">
            <canvas 
                ref={canvasRef} 
                className="block shadow-inner w-full h-full"
                style={{ 
                    backgroundColor: engine.currentScene.background,
                    touchAction: 'none' // Critical for preventing pull-to-refresh on mobile
                }} 
                onContextMenu={(e) => e.preventDefault()}
            />

            {/* VICTORY SCREEN */}
            {winner !== null && !isShowcaseMode && (
                <div className="absolute inset-0 flex items-center justify-center bg-black/70 z-50 pointer-events-auto">
                    <div className="text-center p-8 bg-slate-900 rounded-lg border border-slate-700 shadow-2xl animate-bounce-in">
                        <h2 className={`text-4xl font-bold mb-4 font-serif tracking-widest ${winner === Team.BLUE ? 'text-blue-400' : 'text-red-400'}`}>
                            {winner === Team.BLUE ? 'VICTORY' : 'DEFEAT'}
                        </h2>
                        <button onClick={rematch} className="bg-slate-700 hover:bg-slate-600 text-white font-bold py-2 px-6 rounded border border-slate-500">REMATCH</button>
                    </div>
                </div>
            )}
        </div>
    );
};

