import { useRef } from 'react';
import { GameEngine } from '../engine/game';
import { HexUtils } from '../engine/utils';
import { Hex } from '../types';
import { BLOCK_HEIGHT, HEX_SIZE } from '../constants';

export const useGameCamera = (engine: GameEngine) => {
    // Default safe values
    const camera = useRef({ x: 0, y: 0, zoom: 1.0 });

    // Calculate map boundaries in world pixels
    const getMapBounds = () => {
        const cw = engine.mapConfig.w;
        const ch = engine.mapConfig.h;
        // Approximation of hexagonal map size
        const mapWidth = cw * HEX_SIZE * 1.8; 
        const mapHeight = ch * HEX_SIZE * 1.6;

        const centerHex = { q: Math.floor(cw / 2), r: Math.floor(ch / 2) };
        const center = HexUtils.toPx(centerHex.q, centerHex.r, engine.mapConfig);

        return {
            minX: center.x - mapWidth,
            maxX: center.x + mapWidth,
            minY: center.y - mapHeight - 500, // Extra space for height
            maxY: center.y + mapHeight
        };
    };

    const centerCamera = (width: number, height: number) => {
        // Safety: Mobile browsers might report 0 width during layout thrashing
        if (!width || !height || width <= 0 || height <= 0) return;

        const cw = engine.mapConfig.w;
        const ch = engine.mapConfig.h;

        const centerHex = { q: Math.floor(cw / 2), r: Math.floor(ch / 2) };
        const p = HexUtils.toPx(centerHex.q, centerHex.r, engine.mapConfig);
        const verticalOffset = -BLOCK_HEIGHT * 2; 

        let targetX = p.x - (width / camera.current.zoom) / 2;
        let targetY = p.y + verticalOffset - (height / camera.current.zoom) / 2;

        // NaN Protection
        if (isNaN(targetX)) targetX = 0;
        if (isNaN(targetY)) targetY = 0;

        camera.current.x = targetX;
        camera.current.y = targetY;
    };

    const pan = (dx: number, dy: number) => {
        if (isNaN(dx) || isNaN(dy)) return;

        const nextX = camera.current.x - dx / camera.current.zoom;
        const nextY = camera.current.y - dy / camera.current.zoom;

        // --- BOUNDARY CLAMPING ---
        // Prevents the map from being dragged completely off screen.
        // We calculate bounds relative to the current center of the map.
        // But simply restricting movement such that the map center is never too far from screen center is easier.

        // Get Map Center
        const cw = engine.mapConfig.w;
        const ch = engine.mapConfig.h;
        const centerHex = { q: Math.floor(cw / 2), r: Math.floor(ch / 2) };
        const mapCenter = HexUtils.toPx(centerHex.q, centerHex.r, engine.mapConfig);

        // Allowed distance from map center (in pixels)
        const maxDistX = 1500;
        const maxDistY = 1200;

        // Camera position represents the Top-Left of the viewport.
        // We roughly estimate viewport center relative to camera to check dist.
        // Assuming a standard 1920x1080 or mobile 400x800 reference doesn't matter too much for clamping 
        // as long as we prevent infinity.

        // Clamp relative to map center
        // Note: camera.x is "World X at Screen Left". 
        const distX = nextX - (mapCenter.x - 500); // 500 is approx half screen offset
        const distY = nextY - (mapCenter.y - 400);

        if (Math.abs(distX) < maxDistX) {
            camera.current.x = nextX;
        }
        if (Math.abs(distY) < maxDistY) {
            camera.current.y = nextY;
        }
    };

    const zoom = (delta: number) => {
        if (isNaN(delta)) return;
        const newZoom = Math.max(0.5, Math.min(3.0, camera.current.zoom + delta));
        camera.current.zoom = newZoom;
    };

    const getScreenCoords = (clientX: number, clientY: number, rect: DOMRect) => {
        return { x: clientX - rect.left, y: clientY - rect.top };
    };

    return { 
        camera, 
        centerCamera, 
        pan, 
        zoom,
        getScreenCoords
    };
};

