            const h = wrapperRef.current.clientHeight;

            // Critical Fix: Always center camera on resize.
            // This ensures when switching platforms (Desktop -> Mobile), the map doesn't get lost off-screen.
            // Previously we only centered if map was empty, which caused the bug.
            centerCamera(w, h);
        }
