import { useRef, useEffect, MutableRefObject } from 'react';
import { GameEngine } from '../engine/game';
import { GameEvent } from '../types';
import { GameRenderer } from '../engine/renderer';

export const useGameLoop = (
    engine: GameEngine,
    canvasRef: MutableRefObject<HTMLCanvasElement | null>,
    wrapperRef: MutableRefObject<HTMLDivElement | null>,
    rendererRef: MutableRefObject<GameRenderer>,
    onDraw: (ctx: CanvasRenderingContext2D, fps: number) => void,
    onResize: () => void
) => {
    const fpsRef = useRef(60);
    const frameRef = useRef<number>(0);

    // Store callbacks in refs to avoid restarting the loop when parent re-renders
    const drawCallbackRef = useRef(onDraw);
    const resizeCallbackRef = useRef(onResize);

    // Keep refs synchronized
    useEffect(() => {
        drawCallbackRef.current = onDraw;
        resizeCallbackRef.current = onResize;
    }, [onDraw, onResize]);

    // RESIZE OBSERVER (CRITICAL FIX)
    useEffect(() => {
        if (!wrapperRef.current || !canvasRef.current) return;

        const resizeObserver = new ResizeObserver((entries) => {
            // Use requestAnimationFrame to debounce and prevent "ResizeObserver loop limit exceeded"
            window.requestAnimationFrame(() => {
                if (!wrapperRef.current || !canvasRef.current) return;

                // 1. Get exact integers for dimensions
                const newW = Math.floor(wrapperRef.current.clientWidth);
                const newH = Math.floor(wrapperRef.current.clientHeight);

                // 2. SAFETY CHECK: Ignore invalid dimensions (prevents Infinity/NaN logic later)
                if (newW === 0 || newH === 0) return;

                // 3. DIFF CHECK: Only update if size ACTUALLY changed.
                // This prevents the infinite layout thrashing loop.
                if (canvasRef.current.width !== newW || canvasRef.current.height !== newH) {
                    canvasRef.current.width = newW;
                    canvasRef.current.height = newH;

                    // Trigger game logic resize (Camera centering, etc)
                    resizeCallbackRef.current();
                }
            });
        });

        resizeObserver.observe(wrapperRef.current);
        return () => resizeObserver.disconnect();
    }, [wrapperRef, canvasRef]);

    // MAIN GAME LOOP
    useEffect(() => {
        let lastTime = 0;
        let acc = 0;
        const targetFPS = 60;
        const step = 1000 / targetFPS;
        let frameCount = 0;
        let lastFpsTime = 0;

        const loop = (t: number) => {
            if (!canvasRef.current) {
                frameRef.current = requestAnimationFrame(loop);
                return;
            }
            const ctx = canvasRef.current.getContext('2d');
            if (!ctx) {
                frameRef.current = requestAnimationFrame(loop);
                return;
            }

            if (!lastTime) lastTime = t;
            const dt = t - lastTime;
            lastTime = t;

            // FPS Counter
            frameCount++;
            if (t - lastFpsTime >= 1000) {
                fpsRef.current = frameCount;
                frameCount = 0;
                lastFpsTime = t;
            }

            // Logic Update (Fixed Time Step)
            if (engine.isRunning) {
                acc += dt;
                if (acc > 100) acc = 100; // Panic check: spiral of death prevention

                const frameEvents: GameEvent[] = [];
                while (acc >= step) {
                    const sdt = (step / 1000) * engine.timeScale;
                    engine.tick(sdt);
                    engine.battleTime += sdt;
                    acc -= step;
                    frameEvents.push(...engine.events);
                }

                if (frameEvents.length > 0) {
                    rendererRef.current.processEventsWithEngine(frameEvents, engine);
                }
            }

            // Render Update
            rendererRef.current.update(dt / 1000, engine);
            drawCallbackRef.current(ctx, fpsRef.current);

            frameRef.current = requestAnimationFrame(loop);
        };

        frameRef.current = requestAnimationFrame(loop);
        return () => cancelAnimationFrame(frameRef.current);
    }, [engine, canvasRef, rendererRef]); // Minimized dependencies

    return { fpsRef };
};

import { useRef, useCallback } from 'react';
import { GameEngine } from '../engine/game';
import { HexUtils } from '../engine/utils';
import { BLOCK_HEIGHT, HEX_SIZE } from '../constants';

export const useGameCamera = (engine: GameEngine) => {
    // Default safe values
    const camera = useRef({ x: 0, y: 0, zoom: 1.0 });

    const centerCamera = useCallback((width: number, height: number) => {
        // Safety: Mobile browsers might report 0 width during layout thrashing
        if (!width || !height || width <= 0 || height <= 0) return;

        const cw = engine.mapConfig.w;
        const ch = engine.mapConfig.h;

        const centerHex = { q: Math.floor(cw / 2), r: Math.floor(ch / 2) };
        const p = HexUtils.toPx(centerHex.q, centerHex.r, engine.mapConfig);
        const verticalOffset = -BLOCK_HEIGHT * 2; 

        let targetX = p.x - (width / camera.current.zoom) / 2;
        let targetY = p.y + verticalOffset - (height / camera.current.zoom) / 2;

        // NaN / Infinity Protection (The "Black Screen" Fix)
        if (!Number.isFinite(targetX)) targetX = 0;
        if (!Number.isFinite(targetY)) targetY = 0;

        camera.current.x = targetX;
        camera.current.y = targetY;
    }, [engine.mapConfig]); // Depend on mapConfig, not engine itself to avoid constant updates if engine mutates

    const pan = useCallback((dx: number, dy: number) => {
        if (isNaN(dx) || isNaN(dy)) return;
        if (dx === 0 && dy === 0) return;

        const nextX = camera.current.x - dx / camera.current.zoom;
        const nextY = camera.current.y - dy / camera.current.zoom;

        // --- BOUNDARY CLAMPING ---
        // Prevent losing the map off-screen.
        const centerHex = { q: Math.floor(engine.mapConfig.w / 2), r: Math.floor(engine.mapConfig.h / 2) };
        const mapCenter = HexUtils.toPx(centerHex.q, centerHex.r, engine.mapConfig);

        // Allow looking slightly away, but force center to stay roughly within view
        const maxDistX = 2000;
        const maxDistY = 1500;

        const distX = nextX - (mapCenter.x - 500);
        const distY = nextY - (mapCenter.y - 400);

        // Update X if within bounds
        if (Math.abs(distX) < maxDistX) {
            camera.current.x = nextX;
        }
        // Update Y if within bounds
        if (Math.abs(distY) < maxDistY) {
            camera.current.y = nextY;
        }
    }, [engine.mapConfig]);

    const zoom = useCallback((delta: number) => {
        if (isNaN(delta)) return;
        const newZoom = Math.max(0.5, Math.min(3.0, camera.current.zoom + delta));
        camera.current.zoom = newZoom;
    }, []);

    const getScreenCoords = useCallback((clientX: number, clientY: number, rect: DOMRect) => {
        return { x: clientX - rect.left, y: clientY - rect.top };
    }, []);

    return { 
        camera, 
        centerCamera, 
        pan, 
        zoom,
        getScreenCoords
    };
};

