    useEffect(() => {
        isMountedRef.current = true;
        if (!wrapperRef.current || !canvasRef.current) return;

        const resizeObserver = new ResizeObserver((entries) => {
            if (!isMountedRef.current) return;

            // Performance: Use contentRect directly to avoid DOM unnecessary reflows
            for (const entry of entries) {
                const { width, height } = entry.contentRect;
                const newW = Math.floor(width);
                const newH = Math.floor(height);

                if (newW === 0 || newH === 0) continue;

                if (canvasRef.current && (canvasRef.current.width !== newW || canvasRef.current.height !== newH)) {
                    // Update DOM size immediately to prevent visual glitches
                    canvasRef.current.width = newW;
                    canvasRef.current.height = newH;

