                    // This prevents expensive game logic from running hundreds of times during a drag resize
                    if (resizeTimerRef.current) window.clearTimeout(resizeTimerRef.current);
                    resizeTimerRef.current = window.setTimeout(() => {
                        if (isMountedRef.current) {
                            resizeCallbackRef.current();
                        }
                    }, 100); // 100ms debounce
                }
            }
        });

        resizeObserver.observe(wrapperRef.current);

        return () => {
            isMountedRef.current = false;
            resizeObserver.disconnect();
            if (resizeTimerRef.current) window.clearTimeout(resizeTimerRef.current);
            cancelAnimationFrame(frameRef.current);
        };
    }, [wrapperRef, canvasRef]);

    // 2. MAIN GAME LOOP
    useEffect(() => {
        let lastTime = 0;
        let acc = 0;
        const targetFPS = 60;
        const step = 1000 / targetFPS;
        let frameCount = 0;
        let lastFpsTime = 0;

        const loop = (t: number) => {
            // Safety Guard: Stop loop immediately if unmounted
            if (!isMountedRef.current) return;

            if (!canvasRef.current) {
                frameRef.current = requestAnimationFrame(loop);
                return;
            }
            const ctx = canvasRef.current.getContext('2d');
            if (!ctx) {
                frameRef.current = requestAnimationFrame(loop);
                return;
            }

            if (!lastTime) lastTime = t;
            const dt = t - lastTime;
            lastTime = t;

            // FPS Counter
            frameCount++;
            if (t - lastFpsTime >= 1000) {
                fpsRef.current = frameCount;
                frameCount = 0;
                lastFpsTime = t;
            }

            // Logic Update (Fixed Time Step)
            if (engine.isRunning) {
                acc += dt;
                // Spiral of Death protection: Clamp max simulation time per frame
                if (acc > 250) acc = 250; 

                const frameEvents: GameEvent[] = [];
                while (acc >= step) {
                    const sdt = (step / 1000) * engine.timeScale;
                    engine.tick(sdt);
                    engine.battleTime += sdt;
                    acc -= step;
                    frameEvents.push(...engine.events);
                }

                if (frameEvents.length > 0) {
                    rendererRef.current.processEventsWithEngine(frameEvents, engine);
                }
            }

            // Render Update
            rendererRef.current.update(dt / 1000, engine);
            drawCallbackRef.current(ctx, fpsRef.current);

            frameRef.current = requestAnimationFrame(loop);
        };

        frameRef.current = requestAnimationFrame(loop);

        return () => {
            cancelAnimationFrame(frameRef.current);
        };
    }, [engine, canvasRef, rendererRef]);

    return { fpsRef };
};

