import { useRef, useEffect, MutableRefObject } from 'react';
import { GameEngine } from '../engine/game';
import { GameEvent } from '../types';
import { GameRenderer } from '../engine/renderer';

export const useGameLoop = (
    engine: GameEngine,
    canvasRef: MutableRefObject<HTMLCanvasElement | null>,
    wrapperRef: MutableRefObject<HTMLDivElement | null>,
    rendererRef: MutableRefObject<GameRenderer>,
    onDraw: (ctx: CanvasRenderingContext2D, fps: number) => void,
    onResize: () => void
) => {
    const fpsRef = useRef(60);
    const frameRef = useRef<number>(0);
    const isMountedRef = useRef(true);
    const resizeTimerRef = useRef<number | null>(null);

    // Store callbacks to prevent effect re-triggering
    const drawCallbackRef = useRef(onDraw);
    const resizeCallbackRef = useRef(onResize);

    useEffect(() => {
        drawCallbackRef.current = onDraw;
        resizeCallbackRef.current = onResize;
    }, [onDraw, onResize]);

    // 1. LIFECYCLE & RESIZE OBSERVER
    useEffect(() => {
        isMountedRef.current = true;
        if (!wrapperRef.current || !canvasRef.current) return;

        const resizeObserver = new ResizeObserver((entries) => {
            // Safety check for unmount
            if (!isMountedRef.current) return;

            for (const entry of entries) {
                // Use contentRect directly to avoid DOM unnecessary reflows
                // This prevents "ResizeObserver loop completed with undelivered notifications"
                const { width, height } = entry.contentRect;

                // Rounding is crucial for canvas sharp rendering
                const newW = Math.floor(width);
                const newH = Math.floor(height);

                // Prevent 0-size crashes (Mobile view switch often passes 0 temporarily)
                if (newW === 0 || newH === 0) continue;

                if (canvasRef.current && (canvasRef.current.width !== newW || canvasRef.current.height !== newH)) {
                    // Update DOM size immediately to prevent visual glitches (white flash)
                    canvasRef.current.width = newW;
                    canvasRef.current.height = newH;

                    // DEBOUNCE the logical resize (camera centering / logic updates)
                    // This prevents expensive game logic from running hundreds of times during a drag resize
                    if (resizeTimerRef.current) window.clearTimeout(resizeTimerRef.current);
                    resizeTimerRef.current = window.setTimeout(() => {
                        if (isMountedRef.current) {
                            resizeCallbackRef.current();
                        }
                    }, 50); // 50ms debounce
                }
            }
        });

        resizeObserver.observe(wrapperRef.current);

        return () => {
            isMountedRef.current = false;
            resizeObserver.disconnect();
            if (resizeTimerRef.current) window.clearTimeout(resizeTimerRef.current);
            cancelAnimationFrame(frameRef.current);
        };
    }, [wrapperRef, canvasRef]);

    // 2. MAIN GAME LOOP
    useEffect(() => {
        let lastTime = 0;
        let acc = 0;
        const targetFPS = 60;
        const step = 1000 / targetFPS;
        let frameCount = 0;
        let lastFpsTime = 0;

        const loop = (t: number) => {
            // Safety Guard: Stop loop immediately if unmounted
            if (!isMountedRef.current) return;

            if (!canvasRef.current) {
                frameRef.current = requestAnimationFrame(loop);
                return;
            }
            const ctx = canvasRef.current.getContext('2d');
            if (!ctx) {
                frameRef.current = requestAnimationFrame(loop);
                return;
            }

            if (!lastTime) lastTime = t;
            const dt = t - lastTime;
            lastTime = t;

            // FPS Counter
            frameCount++;
            if (t - lastFpsTime >= 1000) {
                fpsRef.current = frameCount;
                frameCount = 0;
                lastFpsTime = t;
            }

            // Logic Update (Fixed Time Step)
            if (engine.isRunning) {
                acc += dt;
                // Spiral of Death protection: Clamp max simulation time per frame
                if (acc > 250) acc = 250; 

                const frameEvents: GameEvent[] = [];
                while (acc >= step) {
                    const sdt = (step / 1000) * engine.timeScale;
                    engine.tick(sdt);
                    engine.battleTime += sdt;
                    acc -= step;
                    frameEvents.push(...engine.events);
                }

                if (frameEvents.length > 0) {
                    rendererRef.current.processEventsWithEngine(frameEvents, engine);
                }
            }

            // Render Update
            rendererRef.current.update(dt / 1000, engine);
            drawCallbackRef.current(ctx, fpsRef.current);

            frameRef.current = requestAnimationFrame(loop);
        };

        frameRef.current = requestAnimationFrame(loop);

        return () => {
            cancelAnimationFrame(frameRef.current);
        };
    }, [engine, canvasRef, rendererRef]);

    return { fpsRef };
};

