import React, { useRef, useState, useEffect } from 'react';
import { Agent, GameEngine } from '../../../engine/game';
import { TreeNode } from '../parts/TreeNode';

interface BehaviorTreeTabProps {
    agent: Agent;
    version: number; // Force update trigger
    engine: GameEngine;
}

export const BehaviorTreeTab: React.FC<BehaviorTreeTabProps> = ({ agent, version, engine }) => {
    // BT Interaction State
    const [btScale, setBtScale] = useState(0.8);
    const [btPos, setBtPos] = useState({x: 0, y: 20});
    const btContainerRef = useRef<HTMLDivElement>(null);
    const [btFps, setBtFps] = useState(20); 

    // Local state to force re-render when we lazy-build the AI
    const [, forceUpdate] = useState(0);

    // Dragging Logic
    const isDraggingBT = useRef(false);
    const lastTouchPos = useRef<{x: number, y: number} | null>(null);
    const lastPinchDist = useRef<number>(0);

    // Auto-Build AI if missing (e.g. before game start)
    useEffect(() => {
        if (!agent.bt && engine) {
            // Lazy build the behavior tree
            agent.bt = engine.ai.buildAI(agent, engine);
            // CRITICAL: Force React to re-render now that agent.bt is populated
            forceUpdate(n => n + 1);
        }
    }, [agent, engine]);

    // Reset view on agent change
    useEffect(() => {
        setBtPos({x: 0, y: 20});
        setBtScale(0.8);
    }, [agent.id]);

    const handleBtWheel = (e: React.WheelEvent) => {
        e.stopPropagation();
        setBtScale(s => Math.max(0.2, Math.min(2.0, s + (e.deltaY > 0 ? -0.1 : 0.1))));
    };

    const handleBtMouseDown = () => { isDraggingBT.current = true; };
    const handleBtMouseMove = (e: React.MouseEvent) => {
        if (isDraggingBT.current) setBtPos(p => ({ x: p.x + e.movementX, y: p.y + e.movementY }));
    };
    const handleBtMouseUp = () => { isDraggingBT.current = false; };

    // Touch Logic
    const handleBtTouchStart = (e: React.TouchEvent) => {
        if (e.touches.length === 1) {
            lastTouchPos.current = { x: e.touches[0].clientX, y: e.touches[0].clientY };
            isDraggingBT.current = true;
        } else if (e.touches.length === 2) {
            const t1 = e.touches[0];
            const t2 = e.touches[1];
            lastPinchDist.current = Math.hypot(t1.clientX - t2.clientX, t1.clientY - t2.clientY);
            isDraggingBT.current = false;
        }
    };
    const handleBtTouchMove = (e: React.TouchEvent) => {
        if (e.touches.length === 1 && lastTouchPos.current && isDraggingBT.current) {
            const touch = e.touches[0];
            const dx = touch.clientX - lastTouchPos.current.x;
            const dy = touch.clientY - lastTouchPos.current.y;
            setBtPos(p => ({ x: p.x + dx, y: p.y + dy }));
            lastTouchPos.current = { x: touch.clientX, y: touch.clientY };
        } else if (e.touches.length === 2) {
            const t1 = e.touches[0];
            const t2 = e.touches[1];
            const currentDist = Math.hypot(t1.clientX - t2.clientX, t1.clientY - t2.clientY);
            if (lastPinchDist.current > 0) {
                const delta = currentDist - lastPinchDist.current;
                setBtScale(s => Math.max(0.2, Math.min(2.0, s + delta * 0.005)));
            }
            lastPinchDist.current = currentDist;
        }
    };
    const handleBtTouchEnd = () => {
        isDraggingBT.current = false;
        lastTouchPos.current = null;
        lastPinchDist.current = 0;
    };

    return (
        <div 
            className="flex-1 bg-[#0f1115] relative overflow-hidden flex flex-col min-h-0 cursor-grab active:cursor-grabbing" 
            ref={btContainerRef} 
            onWheel={handleBtWheel} 
            onMouseDown={handleBtMouseDown} 
            onMouseMove={handleBtMouseMove} 
            onMouseUp={handleBtMouseUp} 
            onMouseLeave={handleBtMouseUp}
            onTouchStart={handleBtTouchStart}
            onTouchMove={handleBtTouchMove}
            onTouchEnd={handleBtTouchEnd}
            style={{touchAction: 'none'}}
        >
            <div className="absolute top-4 left-4 z-10 glass-panel px-3 py-2 flex items-center gap-3">
                <div className="text-xs font-bold text-slate-400 uppercase">刷新率</div>
                <input type="range" min="1" max="60" value={btFps} onChange={e => setBtFps(parseInt(e.target.value))} className="w-24 h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-cyan-500" />
                <span className="text-cyan-400 font-mono text-xs w-6 text-right">{btFps}</span>
            </div>

            <div className="absolute top-4 right-4 z-10 glass-panel px-3 py-2 text-xs font-mono text-slate-400">
                縮放: {Math.round(btScale * 100)}%
            </div>

            <div className="absolute w-full h-full flex justify-center items-start pt-20 pb-20 origin-top will-change-transform" 
                    style={{
                        transform: `translate(${btPos.x}px, ${btPos.y}px) scale(${btScale})`, 
                        backgroundImage: 'radial-gradient(#334155 1px, transparent 1px)', 
                        backgroundSize: '32px 32px'
                    }}>
                <div id="bt-root-content" className="inline-block px-12 pb-12 flex flex-col items-center">
                    {agent.bt ? (
                        <TreeNode node={agent.bt} version={version} now={Date.now()} />
                    ) : (
                        <div className="flex flex-col items-center justify-center pt-20 opacity-50">
                            <div className="animate-spin rounded-full h-8 w-8 border-t-2 border-b-2 border-cyan-500 mb-4"></div>
                            <span className="text-slate-400 font-mono text-sm">初始化神經網路...</span>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

import { GameEngine, Agent } from "../game";
import { Role, Team, Skill, AnimState } from "../../types";
import { UNIT_DB } from "../../data/units";
import { COLORS } from "../../constants";
import { HexUtils } from "../utils";

export class AgentManager {
    constructor() {}

    public addAgent(engine: GameEngine, team: Team, q: number, r: number, hpOverride?: number): Agent | null {
        if (!engine.map.isValid(q, r) || engine.map.isBlocked(q, r, engine)) return null;

        const a = new Agent(team, q, r, engine.mapConfig);

        // Smart Role Selection Strategy
        // Count existing roles in the team to maintain composition balance
        const allRoles = [Role.TANK, Role.WARRIOR, Role.RANGER, Role.MAGE, Role.SUPPORT];
        const teamAgents = engine.agents.filter(ag => ag.team === team);
        const roleCounts = new Map<Role, number>();
        allRoles.forEach(role => roleCounts.set(role, 0));
        teamAgents.forEach(ag => roleCounts.set(ag.role, (roleCounts.get(ag.role) || 0) + 1));

        // Find roles with minimum count
        let minCount = 999;
        roleCounts.forEach(c => { if(c < minCount) minCount = c; });

        const candidates = allRoles.filter(role => roleCounts.get(role) === minCount);
        a.role = candidates[Math.floor(Math.random() * candidates.length)];

        // ID Generation
        const suffix = Math.random().toString(36).substr(2, 4).toUpperCase();
        a.id = `${a.role}-${suffix}`;

        // Apply Base Stats from DB
        const stats = UNIT_DB[a.role];
        a.maxHp = hpOverride || stats.maxHp;
        a.hp = a.maxHp;
        a.maxMp = stats.maxMp;
        a.moveSpeed = stats.moveSpeed; 

        // Critical Fix: Copy Physics/Movement properties
        a.movementType = stats.movementType;
        a.jump = stats.jump;
        a.weight = stats.weight;

        // Skill Selection: 1 Ult, 1 Active, 1 Basic
        const validSkills = engine.skillDB.filter(s => s.role === a.role && (s.team === undefined || s.team === team));
        const rnd = (ar: Skill[]) => ar.length > 0 ? ar[Math.floor(Math.random() * ar.length)].id : null;

        a.skillIds = [
            rnd(validSkills.filter(s => s.tag === 'ULT')),
            rnd(validSkills.filter(s => s.tag === 'ACTIVE')),
            rnd(validSkills.filter(s => s.tag === 'BASIC'))
        ];

        // Spawn Effect
        a.spawnTimer = 0.5;
        engine.events.push({ 
            type: 'SPAWN', 
            pos: { x: a.px, y: a.py },
            color: COLORS[team],
            sourceId: a.id
        });

        // CRITICAL FIX: If game is already running, we must build AI immediately
        // otherwise this unit will be brainless until next restart.
        if (engine.isRunning) {
            a.skills = a.skillIds.map(id => {
                if (!id) return null;
                return engine.skillDB.find(s => s.id === id) || null;
            });
            a.bt = engine.ai.buildAI(a, engine);
            a.animState = AnimState.IDLE;
        }

        // Register
        engine.agents.push(a);
        engine.agentMap.set(HexUtils.hash(q, r), a);

        return a;
    }

    public handleDeadState(a: Agent, engine: GameEngine) {
        if (a.fullyDead) return;

        if (!a.deadLogged) {
            engine.log(a, '死亡', null, '陣亡');

            // Push Event: Renderer will handle the visual explosion (Shatter)
            engine.events.push({ 
                type: 'DEATH', 
                pos: {x: a.px, y: a.py}, 
                sourceId: a.id,
                team: a.team // Pass team for color coding debris
            });

            a.deadLogged = true;
            a.setAnim(AnimState.DEAD);

            // Remove from spatial map so others can walk here
            engine.agentMap.delete(HexUtils.hash(a.q, a.r));

            // INSTANT VANISH: logic is done, body is hidden, particles take over
            a.fullyDead = true; 
            a.visualStatus = 'NONE';
            a.isMoving = false; 
            a.path = [];
        }
    }
}

