  const [showLogs, setShowLogs] = useState(false);
  const [showDB, setShowDB] = useState(false);
  const [showUnitDetail, setShowUnitDetail] = useState(false);

  const [transitionPhase, setTransitionPhase] = useState<'IDLE' | 'IN' | 'OUT'>('IDLE');
  const [showFactionWarning, setShowFactionWarning] = useState(false);

  // --- Logic ---

  const setupShowcaseMap = useCallback(() => {
      const engine = engineRef.current;
      engine.stop();
      setWinner(null);
      setSelectedAgent(null);
      setShowUnitDetail(false); // Close details on reset
      engine.mapConfig.w = Math.floor(10 + Math.random() * 4);
      engine.mapConfig.h = Math.floor(8 + Math.random() * 4);
      engine.randomizeEnvironment(); 
      setCurrentSceneId(engine.currentScene.id);
  }, []);

  const spawnShowcaseUnits = useCallback(() => {
      const engine = engineRef.current;
      const validHexes = (Array.from(engine.mapKeys) as string[]).map(k => {
          const [q, r] = k.split(',').map(Number);
          return {q, r};
      });
      for (let i = validHexes.length - 1; i > 0; i--) {
          const j = Math.floor(Math.random() * (i + 1));
          [validHexes[i], validHexes[j]] = [validHexes[j], validHexes[i]];
      }
      let spawnIndex = 0;
      const spawn = (team: Team) => {
          if (spawnIndex < validHexes.length) {
              const h = validHexes[spawnIndex++];
              const hp = 500 + Math.floor(Math.random() * 400); 
              engine.addAgent(team, h.q, h.r, hp);
          }
      };
      for(let i=0; i<5; i++) spawn(Team.BLUE);
      for(let i=0; i<5; i++) spawn(Team.RED);
      engine.play();
      setIsPlaying(true);
  }, []);

  const startShowcaseMatch = useCallback(() => {
      setupShowcaseMap();
      spawnShowcaseUnits();
  }, [setupShowcaseMap, spawnShowcaseUnits]);

  useEffect(() => {
      startShowcaseMatch();
  }, [startShowcaseMatch]);

  const enterManualMode = () => {
      setIsShowcaseMode(false);
      engineRef.current.stop();
      setIsPlaying(false);
      setWinner(null);
      engineRef.current.clear(true); 
      engineRef.current.agents = [];
      setUnitCount(0);
      setMapW(engineRef.current.mapConfig.w);
      setMapH(engineRef.current.mapConfig.h);
      setCurrentSceneId(engineRef.current.currentScene.id);
  };

  useEffect(() => {
    const interval = setInterval(() => {
        setUnitCount(engineRef.current.agents.length);
    }, 500); 
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
      engineRef.current.timeScale = timeScale;
  }, [timeScale]);

  // --- Map Editor Logic ---

  const handleUpdateMapSize = useCallback((w: number, h: number) => {
      setMapW(w);
      setMapH(h);
      engineRef.current.mapConfig.w = w;
      engineRef.current.mapConfig.h = h;
      engineRef.current.clear(false); 
      setSelectedAgent(null);
      setWinner(null);
  }, []);

  const handleSetScene = useCallback((id: string) => {
      const scene = SCENE_DB.find(s => s.id === id);
      if (scene) {
          engineRef.current.currentScene = scene;
          engineRef.current.map.rebuildMap(engineRef.current);
          setCurrentSceneId(id);
      }
  }, []);

  const handleRandomBattlefield = useCallback(() => {
      const engine = engineRef.current;
      engine.stop();
      setWinner(null);
      setSelectedAgent(null);
      engine.clear(false); 

      engine.randomizeEnvironment();
      setMapW(engine.mapConfig.w);
      setMapH(engine.mapConfig.h);
      setCurrentSceneId(engine.currentScene.id);

      const validHexes = (Array.from(engine.mapKeys) as string[]).map(k => {
          const [q, r] = k.split(',').map(Number);
          return {q, r};
      });
      for (let i = validHexes.length - 1; i > 0; i--) {
          const j = Math.floor(Math.random() * (i + 1));
          [validHexes[i], validHexes[j]] = [validHexes[j], validHexes[i]];
      }
      let spawnIndex = 0;
      const spawn = (team: Team) => {
          if (spawnIndex < validHexes.length) {
              const h = validHexes[spawnIndex++];
              const hp = 500 + Math.floor(Math.random() * 400); 
              engine.addAgent(team, h.q, h.r, hp);
          }
      };
      for(let i=0; i<5; i++) spawn(Team.BLUE);
      for(let i=0; i<5; i++) spawn(Team.RED);

      setIsPlaying(false); 
  }, []);

  const handleReset = useCallback(() => {
      engineRef.current.restart();
      setIsPlaying(false); 
      setWinner(null);
  }, []);

  // --- Interaction ---

  const togglePlay = useCallback(() => {
    if (winner !== null) return;

    if (isPlaying) {
        engineRef.current.stop();
        setIsPlaying(false);
    } else {
        const hasBlue = engineRef.current.agents.some(a => a.team === Team.BLUE);
        const hasRed = engineRef.current.agents.some(a => a.team === Team.RED);

        if (!hasBlue || !hasRed) {
            setShowFactionWarning(true);
            setTimeout(() => setShowFactionWarning(false), 2500);
            return;
        }

        engineRef.current.play();
        setIsPlaying(true);
        setTool(ToolType.SELECT);
    }
  }, [isPlaying, winner]);

  const onWin = (team: Team) => {
    setWinner(team);
    if (isShowcaseMode) {
        setTimeout(() => {
            setTransitionPhase('OUT');
            engineRef.current.agents = [];
            engineRef.current.combat.projectiles = [];
            setTimeout(() => {
                setupShowcaseMap(); 
                setTransitionPhase('IN'); 
                setTimeout(() => {
                    setTransitionPhase('IDLE');
                    spawnShowcaseUnits(); 
                }, 1200);
            }, 1500);
        }, 2000);
    } else {
        setIsPlaying(false);
    }
  };

  const handleSelectAgent = (a: Agent | null) => {
      setSelectedAgent(a);
      if (!a) setShowUnitDetail(false);
  };

  return (
    <div className="h-[100dvh] w-screen bg-slate-950 text-slate-200 overflow-hidden font-sans flex flex-col relative select-none touch-none">

      {/* WARNING NOTIFICATION */}
      {showFactionWarning && (
            <div className="absolute top-24 left-1/2 -translate-x-1/2 z-50 animate-bounce-in pointer-events-none w-[90%] max-w-md">
                <div className="bg-red-950/90 text-red-200 px-6 py-3 rounded border border-red-500 flex items-center gap-3 shadow-xl">
                    <span className="text-xl">⚠️</span>
                    <div className="flex flex-col">
                        <span className="text-xs font-bold tracking-widest text-red-400 uppercase">部署錯誤</span>
                        <span className="text-xs">請部署雙方單位以開始戰鬥。</span>
                    </div>
                </div>
            </div>
      )}

      {/* SHOWCASE OVERLAY */}
      {isShowcaseMode && (
        <ShowcaseOverlay 
            onEnter={enterManualMode} 
            timeScale={timeScale} 
            setTimeScale={setTimeScale} 
        />
      )}

      {/* --- HUD LAYERS --- */}

      {/* 1. Playback Controls (Top Center) */}
      <PlaybackHUD 
          hidden={isShowcaseMode}
          isPlaying={isPlaying}
          winner={winner}
          timeScale={timeScale}
          onTogglePlay={togglePlay}
          onRestart={handleReset}
          onSetTimeScale={setTimeScale}
          onShowcase={() => { setIsShowcaseMode(true); startShowcaseMatch(); }}
      />

      {/* 2. System Menu (Top Right) */}
      {!isShowcaseMode && (
          <SystemMenu 
              onToggleLogs={() => setShowLogs(!showLogs)} 
              onToggleDB={() => setShowDB(!showDB)} 
          />
      )}

      {/* 3. Unit Inspector (Floating Right Bottom) */}
      {!isShowcaseMode && selectedAgent && (
          <UnitInspectorHUD 
              agent={selectedAgent} 
              onClose={() => handleSelectAgent(null)} 
              onExpand={() => setShowUnitDetail(true)}
          />
      )}

      {/* 4. MODALS (Logs / DB / Unit Detail) */}
      {/* Wrapper */}
      {(showLogs || showDB || (showUnitDetail && selectedAgent)) && !isShowcaseMode && (
          <div className="absolute inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4 md:p-8 animate-fade-in" 
               onClick={() => { setShowLogs(false); setShowDB(false); setShowUnitDetail(false); }}>

              {/* Maximize modal size for better visibility */}
              <div className="w-full h-[95%] max-w-[95%] bg-slate-900 border border-slate-700 shadow-2xl rounded-lg overflow-hidden flex flex-col transition-all" onClick={e => e.stopPropagation()}>

                  {/* Modal Header */}
                  <div className="flex justify-between items-center p-3 md:p-4 border-b border-slate-800 bg-slate-950 shrink-0">
                      <h2 className="text-base md:text-lg font-bold text-cyan-400 truncate pr-4">
                          {showLogs && '戰況紀錄'}
                          {showDB && '技能資料庫'}
                          {showUnitDetail && '單位神經網路分析'}
                      </h2>
                      <button onClick={() => { setShowLogs(false); setShowDB(false); setShowUnitDetail(false); }} className="text-slate-500 hover:text-white px-2 py-1">✕</button>
                  </div>

                  {/* Modal Content */}
                  <div className="flex-1 overflow-hidden relative bg-slate-900 min-h-0">
                      {showLogs && <LogTab engine={engineRef.current} />}
                      {showDB && <SkillDbTab db={engineRef.current.skillDB} onUpdate={() => {}} />}
                      {showUnitDetail && selectedAgent && <UnitDetailView agent={selectedAgent} db={engineRef.current.skillDB} engine={engineRef.current} />}
                  </div>
              </div>
          </div>
      )}

      {/* MAIN GAME VIEW */}
      <div className="flex-1 relative z-0 bg-slate-900">
            <GameCanvas 
                engine={engineRef.current} 
                tool={tool}
                selectedObstacle={selectedObstacle}
                hpInput={hpInput}
                selectedAgent={selectedAgent}
                hoveredSkill={hoveredSkill}
                isShowcaseMode={isShowcaseMode}
                spawnMode={spawnMode}
                draftRole={draftRole}
                onSelect={handleSelectAgent} 
                onWin={onWin}
                winner={winner}
                rematch={() => { setWinner(null); engineRef.current.restart(); setIsPlaying(true); }}
                transitionPhase={transitionPhase}
            />
      </div>

      {/* 5. Map Editor Toolbar (Bottom) */}
      {!isShowcaseMode && (
          <MapEditorToolbar 
              tool={tool}
              setTool={setTool}
              mapW={mapW} setMapW={(w) => handleUpdateMapSize(w, mapH)}
              mapH={mapH} setMapH={(h) => handleUpdateMapSize(mapW, h)}
              currentSceneId={currentSceneId}
              onSetScene={handleSetScene}
              spawnMode={spawnMode} setSpawnMode={setSpawnMode}
              draftRole={draftRole} setDraftRole={setDraftRole}
              hpInput={hpInput} setHpInput={setHpInput}
              selectedObstacle={selectedObstacle} setSelectedObstacle={setSelectedObstacle}
              onRandomBattlefield={handleRandomBattlefield}
              onReset={handleReset}
          />
      )}
    </div>
  );
}

export default App;

import React, { useRef, useState, useEffect } from 'react';
import { Agent, GameEngine } from '../../../engine/game';
import { TreeNode } from '../parts/TreeNode';

interface BehaviorTreeTabProps {
    agent: Agent;
    version: number; // Force update trigger
    engine: GameEngine;
}

export const BehaviorTreeTab: React.FC<BehaviorTreeTabProps> = ({ agent, version, engine }) => {
    // BT Interaction State
    const [btScale, setBtScale] = useState(0.8);
    const [btPos, setBtPos] = useState({x: 0, y: 50});
    const btContainerRef = useRef<HTMLDivElement>(null);
    const [btFps, setBtFps] = useState(20); 

    // Local state to force re-render when we lazy-build the AI
    const [, forceUpdate] = useState(0);

    // Dragging Logic
    const isDraggingBT = useRef(false);
    const lastMousePos = useRef<{x: number, y: number} | null>(null);
    const lastTouchPos = useRef<{x: number, y: number} | null>(null);
    const lastPinchDist = useRef<number>(0);

    // Auto-Build AI if missing (e.g. before game start or hot-swap)
    useEffect(() => {
        if (!agent.bt && engine) {
            // Lazy build the behavior tree
            agent.bt = engine.ai.buildAI(agent, engine);
            // CRITICAL: Force React to re-render now that agent.bt is populated
            forceUpdate(n => n + 1);
        }
    }, [agent, engine]);

    // Reset view on agent change
    useEffect(() => {
        setBtPos({x: 0, y: 50});
        setBtScale(0.8);
    }, [agent.id]);

    const handleBtWheel = (e: React.WheelEvent) => {
        e.stopPropagation();
        const delta = e.deltaY > 0 ? -0.1 : 0.1;
        setBtScale(s => Math.max(0.2, Math.min(2.0, s + delta)));
    };

    // Improved Mouse Handler using explicit delta
    const handleBtMouseDown = (e: React.MouseEvent) => { 
        isDraggingBT.current = true;
        lastMousePos.current = { x: e.clientX, y: e.clientY };
    };

    const handleBtMouseMove = (e: React.MouseEvent) => {
        if (isDraggingBT.current && lastMousePos.current) {
            const dx = e.clientX - lastMousePos.current.x;
            const dy = e.clientY - lastMousePos.current.y;
            setBtPos(p => ({ x: p.x + dx, y: p.y + dy }));
            lastMousePos.current = { x: e.clientX, y: e.clientY };
        }
    };

    const handleBtMouseUp = () => { 
        isDraggingBT.current = false; 
        lastMousePos.current = null;
    };

    const handleMouseLeave = () => { 
        isDraggingBT.current = false; 
        lastMousePos.current = null;
    };

    // Touch Logic
    const handleBtTouchStart = (e: React.TouchEvent) => {
        if (e.touches.length === 1) {
            lastTouchPos.current = { x: e.touches[0].clientX, y: e.touches[0].clientY };
            isDraggingBT.current = true;
        } else if (e.touches.length === 2) {
            const t1 = e.touches[0];
            const t2 = e.touches[1];
            lastPinchDist.current = Math.hypot(t1.clientX - t2.clientX, t1.clientY - t2.clientY);
            isDraggingBT.current = false;
        }
    };
    const handleBtTouchMove = (e: React.TouchEvent) => {
        if (e.touches.length === 1 && lastTouchPos.current && isDraggingBT.current) {
            const touch = e.touches[0];
            const dx = touch.clientX - lastTouchPos.current.x;
            const dy = touch.clientY - lastTouchPos.current.y;
            setBtPos(p => ({ x: p.x + dx, y: p.y + dy }));
            lastTouchPos.current = { x: touch.clientX, y: touch.clientY };
        } else if (e.touches.length === 2) {
            const t1 = e.touches[0];
            const t2 = e.touches[1];
            const currentDist = Math.hypot(t1.clientX - t2.clientX, t1.clientY - t2.clientY);
            if (lastPinchDist.current > 0) {
                const delta = currentDist - lastPinchDist.current;
                setBtScale(s => Math.max(0.2, Math.min(2.0, s + delta * 0.005)));
            }
            lastPinchDist.current = currentDist;
        }
    };
    const handleBtTouchEnd = () => {
        isDraggingBT.current = false;
        lastTouchPos.current = null;
        lastPinchDist.current = 0;
    };

    return (
        <div 
            className="flex-1 bg-[#0f1115] relative overflow-hidden flex flex-col min-h-0 w-full h-full cursor-grab active:cursor-grabbing select-none" 
            ref={btContainerRef} 
            onWheel={handleBtWheel} 
            onMouseDown={handleBtMouseDown} 
            onMouseMove={handleBtMouseMove} 
            onMouseUp={handleBtMouseUp} 
            onMouseLeave={handleMouseLeave}
            onTouchStart={handleBtTouchStart}
            onTouchMove={handleBtTouchMove}
            onTouchEnd={handleBtTouchEnd}
            style={{ touchAction: 'none' }}
        >
            {/* UI Overlay */}
            <div className="absolute top-4 left-4 z-20 glass-panel px-3 py-2 flex items-center gap-3 pointer-events-auto">
                <div className="text-xs font-bold text-slate-400 uppercase">刷新率</div>
                <input type="range" min="1" max="60" value={btFps} onChange={e => setBtFps(parseInt(e.target.value))} className="w-24 h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-cyan-500" />
                <span className="text-cyan-400 font-mono text-xs w-6 text-right">{btFps}</span>
            </div>

            <div className="absolute top-4 right-4 z-20 glass-panel px-3 py-2 text-xs font-mono text-slate-400 pointer-events-none">
                {agent.bt ? 'AI: ACTIVE' : 'AI: NULL'} | SCALE: {Math.round(btScale * 100)}%
            </div>

            {/* Content Layer with Transform */}
            {/* We use a wrapper to handle the transform origin correctly from center-top */}
            <div 
                className="absolute inset-0 w-full h-full flex justify-center items-start origin-top will-change-transform pointer-events-none"
                style={{
                    transform: `translate(${btPos.x}px, ${btPos.y}px) scale(${btScale})`, 
                    backgroundImage: 'radial-gradient(#334155 1px, transparent 1px)', 
                    backgroundSize: '32px 32px'
                }}
            >
                {/* The actual Tree Content - must have size to be rendered */}
                <div className="inline-block min-w-max pt-10 pb-20">
                    {agent.bt ? (
                        <TreeNode node={agent.bt} version={version} now={Date.now()} />
                    ) : (
                        <div className="flex flex-col items-center justify-center pt-20 opacity-50">
                            <div className="animate-spin rounded-full h-8 w-8 border-t-2 border-b-2 border-cyan-500 mb-4"></div>
                            <span className="text-slate-400 font-mono text-sm">初始化神經網路...</span>
                            <span className="text-slate-600 font-mono text-xs mt-2">(若長時間無反應請重置回合)</span>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

import { useRef, useEffect, MutableRefObject } from 'react';
import { GameEngine, Agent } from '../engine/game';
import { ToolType, Hex, Team, Role, Skill } from '../types';
import { HexUtils } from '../engine/utils';
import { GameRenderer } from '../engine/renderer';
import { BLOCK_HEIGHT } from '../constants';

interface GameInputProps {
    canvasRef: MutableRefObject<HTMLCanvasElement | null>;
    engine: GameEngine;
    rendererRef: MutableRefObject<GameRenderer>;
    cameraRef: MutableRefObject<{ x: number; y: number; zoom: number }>;

    // Tool State
    tool: ToolType;
    selectedObstacle: string;
    hpInput: number;
    spawnMode: 'RANDOM' | 'DRAFT';
    draftRole: Role;
    winner: Team | null;

    // Callbacks
    onSelect: (a: Agent | null) => void;
    onCameraPan: (dx: number, dy: number) => void;
    onCameraZoom: (delta: number) => void;
}

export const useGameInput = ({
    canvasRef, engine, rendererRef, cameraRef,
    tool, selectedObstacle, hpInput, spawnMode, draftRole, winner,
    onSelect, onCameraPan, onCameraZoom
}: GameInputProps) => {

    // Interaction State Machine
    type InteractionMode = 'IDLE' | 'DOWN' | 'DRAG_UNIT' | 'DRAG_OBS' | 'PAN' | 'PAINT';
    const interactionMode = useRef<InteractionMode>('IDLE');

    // Refs for mutable props to prevent Effect re-binding
    const toolRef = useRef(tool);
    const obsRef = useRef(selectedObstacle);
    const hpRef = useRef(hpInput);
    const spawnRef = useRef(spawnMode);
    const roleRef = useRef(draftRole);
    const winnerRef = useRef(winner);

    useEffect(() => {
        toolRef.current = tool;
        obsRef.current = selectedObstacle;
        hpRef.current = hpInput;
        spawnRef.current = spawnMode;
        roleRef.current = draftRole;
        winnerRef.current = winner;
    }, [tool, selectedObstacle, hpInput, spawnMode, draftRole, winner]);

    // Drag Data
    const pressedAgentRef = useRef<Agent | null>(null);
    const draggedObstacleRef = useRef<{ type: string; originQ: number; originR: number; px: number; py: number; } | null>(null);

    // Tracking
    const pressStartPos = useRef<{x: number, y: number} | null>(null);
    const lastMousePos = useRef<{x: number, y: number} | null>(null);
    const dragStartHex = useRef<{q: number, r: number} | null>(null);
    const lastPaintHex = useRef<string>(""); 

    // Touch
    const lastPinchDist = useRef<number>(0);
    const lastTouchPos = useRef<{x: number, y: number} | null>(null);
    const hoveredHexRef = useRef<Hex | null>(null);

    // --- Helpers ---

    const getHexFromCoords = (sx: number, sy: number) => {
        const hex = rendererRef.current.getHexAtScreenPoint(sx, sy, cameraRef.current, engine);
        if (hex) return hex;
        return HexUtils.fromPx(
            sx / cameraRef.current.zoom + cameraRef.current.x,
            sy / cameraRef.current.zoom + cameraRef.current.y,
            engine.mapConfig
        );
    };

    const getWorldPosFromCoords = (sx: number, sy: number) => {
        const wx = sx / cameraRef.current.zoom + cameraRef.current.x;
        const hex = rendererRef.current.getHexAtScreenPoint(sx, sy, cameraRef.current, engine);
        let h = BLOCK_HEIGHT + 6;
        if (hex) h = rendererRef.current.getTerrainHeight(hex.q, hex.r, engine);
        const wy = sy / cameraRef.current.zoom + cameraRef.current.y + h;
        return { x: wx, y: wy };
    };

    const getHitAgentFromCoords = (sx: number, sy: number) => {
        const wx = sx / cameraRef.current.zoom + cameraRef.current.x;
        const wy = sy / cameraRef.current.zoom + cameraRef.current.y;
        const sorted = [...engine.agents].sort((a, b) => b.py - a.py); // Front to back

        for (const agent of sorted) {
            if (agent.hp <= 0 && agent.fullyDead) continue;
            const h = rendererRef.current.getTerrainHeight(agent.q, agent.r, engine);
            const baseX = agent.px;
            const baseY = agent.py - h;
            const dx = Math.abs(wx - baseX);
            const dy = wy - (baseY - 40); 
            if (dx < 35 && Math.abs(dy) < 60) return agent;
        }
        return null;
    };

    const executeToolAction = (h: Hex) => {
        const _tool = toolRef.current;
        const _winner = winnerRef.current;
        const _obs = obsRef.current;
        const _spawn = spawnRef.current;
        const _role = roleRef.current;
        const _hp = hpRef.current;

        if (engine.isRunning || _winner !== null) return;
        const k = HexUtils.key(h);
        if (lastPaintHex.current === k) return; 

        lastPaintHex.current = k;
        const existingAgent = engine.getAgentAt(h.q, h.r);
        let agent: Agent | null = null;

        if (_tool === ToolType.DELETE) {
            if (engine.hasObstacle(h.q, h.r)) engine.removeObstacle(h.q, h.r);
            if (existingAgent) {
                engine.removeAgent(h.q, h.r);
                onSelect(null);
            }
            return;
        }

        if (_tool === ToolType.OBSTACLE) {
            if (existingAgent) engine.removeAgent(h.q, h.r);
            engine.setObstacle(h.q, h.r, _obs);
            return;
        }

        if (!existingAgent && !engine.hasObstacle(h.q, h.r)) {
            if (_tool === ToolType.ADD_BLUE) agent = engine.addAgent(Team.BLUE, h.q, h.r, _hp);
            else if (_tool === ToolType.ADD_RED) agent = engine.addAgent(Team.RED, h.q, h.r, _hp);
        }

        if (agent && _spawn === 'DRAFT') {
            agent.role = _role;
            const validSkills = engine.skillDB.filter(s => s.role === agent!.role && (s.team === undefined || s.team === agent!.team));
            const rnd = (ar: Skill[]) => ar.length > 0 ? ar[Math.floor(Math.random() * ar.length)].id : null;
            agent.skillIds = [
                rnd(validSkills.filter(s => s.tag === 'ULT')),
                rnd(validSkills.filter(s => s.tag === 'ACTIVE')),
                rnd(validSkills.filter(s => s.tag === 'BASIC'))
            ];
            agent.saveState();
            agent.reset(engine.mapConfig);
        }
    };

    // --- Input Handlers ---

    const handleDown = (sx: number, sy: number, button: number = 0) => {
        pressStartPos.current = { x: sx, y: sy };
        lastMousePos.current = { x: sx, y: sy };
        lastPaintHex.current = "";
        interactionMode.current = 'DOWN';

        if (button === 2 || engine.isRunning) {
            interactionMode.current = 'PAN';
            return;
        }

        const hitAgent = getHitAgentFromCoords(sx, sy);
        if (hitAgent) {
            pressedAgentRef.current = hitAgent;
            if (toolRef.current !== ToolType.DELETE) {
                dragStartHex.current = { q: hitAgent.q, r: hitAgent.r };
            }
            return;
        }

        const h = getHexFromCoords(sx, sy);
        if (engine.isValid(h.q, h.r) && engine.hasObstacle(h.q, h.r) && toolRef.current !== ToolType.DELETE) {
            const obsType = engine.obstacles.get(HexUtils.key(h));
            if (obsType) {
                draggedObstacleRef.current = { type: obsType, originQ: h.q, originR: h.r, px: 0, py: 0 };
            }
        }
    };

    const handleMove = (sx: number, sy: number) => {
        // Delta Calculation
        const prev = lastMousePos.current || { x: sx, y: sy };
        const dx = sx - prev.x;
        const dy = sy - prev.y;
        lastMousePos.current = { x: sx, y: sy };

        const h = getHexFromCoords(sx, sy);
        hoveredHexRef.current = engine.isValid(h.q, h.r) ? h : null;

        const cvs = canvasRef.current;
        if (cvs) {
            const hitAgent = getHitAgentFromCoords(sx, sy);
            if (interactionMode.current === 'DRAG_UNIT' || interactionMode.current === 'DRAG_OBS') cvs.style.cursor = 'grabbing';
            else if (interactionMode.current === 'PAN') cvs.style.cursor = 'move';
            else if (hitAgent) cvs.style.cursor = 'pointer'; 
            else if (engine.hasObstacle(h.q, h.r)) cvs.style.cursor = 'grab';
            else if (toolRef.current === ToolType.SELECT) cvs.style.cursor = 'default';
            else cvs.style.cursor = 'crosshair'; 
        }

        if (interactionMode.current === 'IDLE') return;

        if (interactionMode.current === 'PAN') {
            onCameraPan(-dx, -dy); // Invert drag for pan
            return;
        }

        if (interactionMode.current === 'PAINT') {
            if (engine.isValid(h.q, h.r)) executeToolAction(h);
            return;
        }

        if (interactionMode.current === 'DRAG_UNIT' && pressedAgentRef.current) {
            const wPos = getWorldPosFromCoords(sx, sy);
            pressedAgentRef.current.px = wPos.x;
            pressedAgentRef.current.py = wPos.y;
            return;
        }

        if (interactionMode.current === 'DRAG_OBS' && draggedObstacleRef.current) {
            const wPos = getWorldPosFromCoords(sx, sy);
            draggedObstacleRef.current.px = wPos.x;
            draggedObstacleRef.current.py = wPos.y;
            return;
        }

        if (interactionMode.current === 'DOWN' && pressStartPos.current) {
            const dist = Math.sqrt((sx - pressStartPos.current.x)**2 + (sy - pressStartPos.current.y)**2);
            if (dist > 10) {
                const _tool = toolRef.current;

                if (pressedAgentRef.current && _tool !== ToolType.DELETE) {
                    interactionMode.current = 'DRAG_UNIT';
                    pressedAgentRef.current.physics.z = 20; 
                    onSelect(pressedAgentRef.current);
                    return;
                }
                if (draggedObstacleRef.current && _tool !== ToolType.DELETE) {
                    interactionMode.current = 'DRAG_OBS';
                    const { originQ, originR } = draggedObstacleRef.current;
                    engine.removeObstacle(originQ, originR);
                    onSelect(null);
                    const wPos = getWorldPosFromCoords(sx, sy);
                    draggedObstacleRef.current.px = wPos.x;
                    draggedObstacleRef.current.py = wPos.y;
                    return;
                }
                if (engine.isValid(h.q, h.r) && (_tool === ToolType.OBSTACLE || _tool === ToolType.DELETE)) {
                    interactionMode.current = 'PAINT';
                    executeToolAction(h);
                } else {
                    interactionMode.current = 'PAN';
                    // We consume the initial drag to prevent jump
                    onCameraPan(-dx, -dy);
                }
            }
        }
    };

    const handleUp = (sx: number, sy: number) => {
        const h = getHexFromCoords(sx, sy);
        const _tool = toolRef.current;

        if (interactionMode.current === 'DOWN') {
            if (pressedAgentRef.current) {
                if (_tool === ToolType.DELETE) {
                    engine.removeAgent(pressedAgentRef.current.q, pressedAgentRef.current.r);
                    onSelect(null);
                } else {
                    onSelect(pressedAgentRef.current);
                }
            } else if (engine.hasObstacle(h.q, h.r)) {
                if (_tool === ToolType.DELETE) engine.removeObstacle(h.q, h.r);
            } else if (_tool !== ToolType.SELECT && _tool !== ToolType.DELETE) {
                if (engine.isValid(h.q, h.r)) executeToolAction(h);
            } else {
                onSelect(null);
            }
        }

        if (interactionMode.current === 'DRAG_UNIT' && pressedAgentRef.current) {
            const agent = pressedAgentRef.current;
            agent.physics.z = 0;
            const valid = engine.isValid(h.q, h.r) && !engine.hasObstacle(h.q, h.r) && (!engine.getAgentAt(h.q, h.r) || engine.getAgentAt(h.q, h.r) === agent);

            if (valid) {
                engine.updateAgentPosition(agent, h.q, h.r);
                const p = HexUtils.toPx(h.q, h.r, engine.mapConfig);
                agent.px = p.x; agent.py = p.y;
            } else if (dragStartHex.current) {
                agent.q = dragStartHex.current.q;
                agent.r = dragStartHex.current.r;
                const p = HexUtils.toPx(agent.q, agent.r, engine.mapConfig);
                agent.px = p.x; agent.py = p.y;
                engine.updateAgentPosition(agent, agent.q, agent.r);
            }
            onSelect(agent);
        }

        if (interactionMode.current === 'DRAG_OBS' && draggedObstacleRef.current) {
            const { type, originQ, originR } = draggedObstacleRef.current;
            const valid = engine.isValid(h.q, h.r) && !engine.getAgentAt(h.q, h.r) && !engine.hasObstacle(h.q, h.r);

            if (valid) engine.setObstacle(h.q, h.r, type);
            else engine.setObstacle(originQ, originR, type); 
        }

        interactionMode.current = 'IDLE';
        pressedAgentRef.current = null;
        draggedObstacleRef.current = null;
        pressStartPos.current = null;
        lastMousePos.current = null;
        lastPaintHex.current = "";
        if (canvasRef.current) canvasRef.current.style.cursor = 'default';
    };

    // --- Listeners Binding ---
    useEffect(() => {
        const cvs = canvasRef.current;
        if (!cvs) return;

        const getCoords = (e: MouseEvent | Touch) => {
            const rect = cvs.getBoundingClientRect();
            return { x: e.clientX - rect.left, y: e.clientY - rect.top };
        };

        const onMouseDown = (e: MouseEvent) => {
            const {x, y} = getCoords(e);
            handleDown(x, y, e.button);
        };
        const onMouseMove = (e: MouseEvent) => {
            const {x, y} = getCoords(e);
            handleMove(x, y);
        };
        const onMouseUp = (e: MouseEvent) => {
            const {x, y} = getCoords(e);
            handleUp(x, y);
        };

        const onTouchStart = (e: TouchEvent) => {
            if (e.cancelable) e.preventDefault();

            if (e.touches.length === 1) {
                const {x, y} = getCoords(e.touches[0]);
                lastTouchPos.current = {x, y};
                handleDown(x, y, 0);
            } else if (e.touches.length === 2) {
                const t1 = getCoords(e.touches[0]);
                const t2 = getCoords(e.touches[1]);
                lastPinchDist.current = Math.hypot(t1.x - t2.x, t1.y - t2.y);
                interactionMode.current = 'IDLE';
                pressedAgentRef.current = null;
                draggedObstacleRef.current = null;
            }
        };

        const onTouchMove = (e: TouchEvent) => {
            if (e.cancelable) e.preventDefault();

            if (e.touches.length === 1 && lastTouchPos.current) {
                if (lastPinchDist.current > 0) {
                    const {x, y} = getCoords(e.touches[0]);
                    lastTouchPos.current = {x, y};
                    lastPinchDist.current = 0;
                    return;
                }

                const {x, y} = getCoords(e.touches[0]);
                // Manual delta for touch
                // Note: Touch delta is not used directly, we rely on state tracking
                // But for move handler we need sx, sy
                handleMove(x, y);
                lastTouchPos.current = {x, y};
            } else if (e.touches.length === 2) {
                const t1 = getCoords(e.touches[0]);
                const t2 = getCoords(e.touches[1]);
                const dist = Math.hypot(t1.x - t2.x, t1.y - t2.y);
                if (lastPinchDist.current > 0) {
                    const delta = dist - lastPinchDist.current;
                    onCameraZoom(delta * 0.005);
                }
                lastPinchDist.current = dist;
            }
        };

        const onTouchEnd = (e: TouchEvent) => {
            if (e.cancelable) e.preventDefault();

            if (e.changedTouches.length > 0 && lastTouchPos.current) {
                if (e.touches.length === 0) {
                    const {x, y} = getCoords(e.changedTouches[0]);
                    handleUp(x, y);
                }
            }
            if (e.touches.length < 2) {
                lastPinchDist.current = 0;
            }
            if (e.touches.length === 0) {
                lastTouchPos.current = null;
            }
        };

        const onTouchCancel = (e: TouchEvent) => {
            if (e.cancelable) e.preventDefault();
            interactionMode.current = 'IDLE';
            pressedAgentRef.current = null;
            draggedObstacleRef.current = null;
            lastTouchPos.current = null;
            lastPinchDist.current = 0;
        };

        const onWheel = (e: WheelEvent) => {
            e.preventDefault();
            const delta = e.deltaY > 0 ? -0.1 : 0.1;
            onCameraZoom(delta);
        };

        const onCtx = (e: MouseEvent) => e.preventDefault();

        cvs.addEventListener('mousedown', onMouseDown);
        window.addEventListener('mousemove', onMouseMove);
        window.addEventListener('mouseup', onMouseUp);
        cvs.addEventListener('wheel', onWheel, { passive: false });
        cvs.addEventListener('contextmenu', onCtx);
        cvs.addEventListener('touchstart', onTouchStart, { passive: false });
        cvs.addEventListener('touchmove', onTouchMove, { passive: false });
        cvs.addEventListener('touchend', onTouchEnd, { passive: false });
        cvs.addEventListener('touchcancel', onTouchCancel, { passive: false });

        return () => {
            cvs.removeEventListener('mousedown', onMouseDown);
            window.removeEventListener('mousemove', onMouseMove);
            window.removeEventListener('mouseup', onMouseUp);
            cvs.removeEventListener('wheel', onWheel);
            cvs.removeEventListener('contextmenu', onCtx);
            cvs.removeEventListener('touchstart', onTouchStart);
            cvs.removeEventListener('touchmove', onTouchMove);
            cvs.removeEventListener('touchend', onTouchEnd);
            cvs.removeEventListener('touchcancel', onTouchCancel);
        };
    }, [engine, onSelect, onCameraPan, onCameraZoom]); 

    return {
        pressedAgent: pressedAgentRef.current,
        draggedObstacle: draggedObstacleRef.current,
        hoveredHex: hoveredHexRef.current
    };
};

import { useRef, useEffect, MutableRefObject } from 'react';
import { GameEngine, Agent } from '../engine/game';
import { ToolType, Hex, Team, Role, Skill } from '../types';
import { HexUtils } from '../engine/utils';
import { GameRenderer } from '../engine/renderer';
import { BLOCK_HEIGHT } from '../constants';

interface GameInputProps {
    canvasRef: MutableRefObject<HTMLCanvasElement | null>;
    engine: GameEngine;
    rendererRef: MutableRefObject<GameRenderer>;
    cameraRef: MutableRefObject<{ x: number; y: number; zoom: number }>;

    // Tool State
    tool: ToolType;
    selectedObstacle: string;
    hpInput: number;
    spawnMode: 'RANDOM' | 'DRAFT';
    draftRole: Role;
    winner: Team | null;

    // Callbacks
    onSelect: (a: Agent | null) => void;
    onCameraPan: (dx: number, dy: number) => void;
    onCameraZoom: (delta: number) => void;
}

export const useGameInput = ({
    canvasRef, engine, rendererRef, cameraRef,
    tool, selectedObstacle, hpInput, spawnMode, draftRole, winner,
    onSelect, onCameraPan, onCameraZoom
}: GameInputProps) => {

    // Interaction State Machine
    type InteractionMode = 'IDLE' | 'DOWN' | 'DRAG_UNIT' | 'DRAG_OBS' | 'PAN' | 'PAINT';
    const interactionMode = useRef<InteractionMode>('IDLE');

    // Refs for mutable props to prevent Effect re-binding
    const toolRef = useRef(tool);
    const obsRef = useRef(selectedObstacle);
    const hpRef = useRef(hpInput);
    const spawnRef = useRef(spawnMode);
    const roleRef = useRef(draftRole);
    const winnerRef = useRef(winner);

    useEffect(() => {
        toolRef.current = tool;
        obsRef.current = selectedObstacle;
        hpRef.current = hpInput;
        spawnRef.current = spawnMode;
        roleRef.current = draftRole;
        winnerRef.current = winner;
    }, [tool, selectedObstacle, hpInput, spawnMode, draftRole, winner]);

    // Drag Data
    const pressedAgentRef = useRef<Agent | null>(null);
    const draggedObstacleRef = useRef<{ type: string; originQ: number; originR: number; px: number; py: number; } | null>(null);

    // Tracking
    const pressStartPos = useRef<{x: number, y: number} | null>(null);
    const lastMousePos = useRef<{x: number, y: number} | null>(null);
    const dragStartHex = useRef<{q: number, r: number} | null>(null);
    const lastPaintHex = useRef<string>(""); 

    // Touch
    const lastPinchDist = useRef<number>(0);
    const lastTouchPos = useRef<{x: number, y: number} | null>(null);
    const hoveredHexRef = useRef<Hex | null>(null);

    // --- Helpers ---

    const getHexFromCoords = (sx: number, sy: number) => {
        const hex = rendererRef.current.getHexAtScreenPoint(sx, sy, cameraRef.current, engine);
        if (hex) return hex;
        return HexUtils.fromPx(
            sx / cameraRef.current.zoom + cameraRef.current.x,
            sy / cameraRef.current.zoom + cameraRef.current.y,
            engine.mapConfig
        );
    };

    const getWorldPosFromCoords = (sx: number, sy: number) => {
        const wx = sx / cameraRef.current.zoom + cameraRef.current.x;
        const hex = rendererRef.current.getHexAtScreenPoint(sx, sy, cameraRef.current, engine);
        let h = BLOCK_HEIGHT + 6;
        if (hex) h = rendererRef.current.getTerrainHeight(hex.q, hex.r, engine);
        const wy = sy / cameraRef.current.zoom + cameraRef.current.y + h;
        return { x: wx, y: wy };
    };

    const getHitAgentFromCoords = (sx: number, sy: number) => {
        const wx = sx / cameraRef.current.zoom + cameraRef.current.x;
        const wy = sy / cameraRef.current.zoom + cameraRef.current.y;
        const sorted = [...engine.agents].sort((a, b) => b.py - a.py); // Front to back

        for (const agent of sorted) {
            if (agent.hp <= 0 && agent.fullyDead) continue;
            const h = rendererRef.current.getTerrainHeight(agent.q, agent.r, engine);
            const baseX = agent.px;
            const baseY = agent.py - h;
            const dx = Math.abs(wx - baseX);
            const dy = wy - (baseY - 40); 
            if (dx < 35 && Math.abs(dy) < 60) return agent;
        }
        return null;
    };

    const executeToolAction = (h: Hex) => {
        const _tool = toolRef.current;
        const _winner = winnerRef.current;
        const _obs = obsRef.current;
        const _spawn = spawnRef.current;
        const _role = roleRef.current;
        const _hp = hpRef.current;

        if (engine.isRunning || _winner !== null) return;
        const k = HexUtils.key(h);
        if (lastPaintHex.current === k) return; 

        lastPaintHex.current = k;
        const existingAgent = engine.getAgentAt(h.q, h.r);
        let agent: Agent | null = null;

        if (_tool === ToolType.DELETE) {
            if (engine.hasObstacle(h.q, h.r)) engine.removeObstacle(h.q, h.r);
            if (existingAgent) {
                engine.removeAgent(h.q, h.r);
                onSelect(null);
            }
            return;
        }

        if (_tool === ToolType.OBSTACLE) {
            if (existingAgent) engine.removeAgent(h.q, h.r);
            engine.setObstacle(h.q, h.r, _obs);
            return;
        }

        if (!existingAgent && !engine.hasObstacle(h.q, h.r)) {
            if (_tool === ToolType.ADD_BLUE) agent = engine.addAgent(Team.BLUE, h.q, h.r, _hp);
            else if (_tool === ToolType.ADD_RED) agent = engine.addAgent(Team.RED, h.q, h.r, _hp);
        }

        if (agent && _spawn === 'DRAFT') {
            agent.role = _role;
            const validSkills = engine.skillDB.filter(s => s.role === agent!.role && (s.team === undefined || s.team === agent!.team));
            const rnd = (ar: Skill[]) => ar.length > 0 ? ar[Math.floor(Math.random() * ar.length)].id : null;
            agent.skillIds = [
                rnd(validSkills.filter(s => s.tag === 'ULT')),
                rnd(validSkills.filter(s => s.tag === 'ACTIVE')),
                rnd(validSkills.filter(s => s.tag === 'BASIC'))
            ];
            agent.saveState();
            agent.reset(engine.mapConfig);
        }
    };

    // --- Input Handlers ---

    const handleDown = (sx: number, sy: number, button: number = 0) => {
        pressStartPos.current = { x: sx, y: sy };
        lastMousePos.current = { x: sx, y: sy };
        lastPaintHex.current = "";
        interactionMode.current = 'DOWN';

        if (button === 2 || engine.isRunning) {
            interactionMode.current = 'PAN';
            return;
        }

        const hitAgent = getHitAgentFromCoords(sx, sy);
        if (hitAgent) {
            pressedAgentRef.current = hitAgent;
            if (toolRef.current !== ToolType.DELETE) {
                dragStartHex.current = { q: hitAgent.q, r: hitAgent.r };
            }
            return;
        }

        const h = getHexFromCoords(sx, sy);
        if (engine.isValid(h.q, h.r) && engine.hasObstacle(h.q, h.r) && toolRef.current !== ToolType.DELETE) {
            const obsType = engine.obstacles.get(HexUtils.key(h));
            if (obsType) {
                draggedObstacleRef.current = { type: obsType, originQ: h.q, originR: h.r, px: 0, py: 0 };
            }
        }
    };

    const handleMove = (sx: number, sy: number) => {
        // Delta Calculation
        const prev = lastMousePos.current || { x: sx, y: sy };
        const dx = sx - prev.x;
        const dy = sy - prev.y;
        lastMousePos.current = { x: sx, y: sy };

        const h = getHexFromCoords(sx, sy);
        hoveredHexRef.current = engine.isValid(h.q, h.r) ? h : null;

        const cvs = canvasRef.current;
        if (cvs) {
            const hitAgent = getHitAgentFromCoords(sx, sy);
            if (interactionMode.current === 'DRAG_UNIT' || interactionMode.current === 'DRAG_OBS') cvs.style.cursor = 'grabbing';
            else if (interactionMode.current === 'PAN') cvs.style.cursor = 'move';
            else if (hitAgent) cvs.style.cursor = 'pointer'; 
            else if (engine.hasObstacle(h.q, h.r)) cvs.style.cursor = 'grab';
            else if (toolRef.current === ToolType.SELECT) cvs.style.cursor = 'default';
            else cvs.style.cursor = 'crosshair'; 
        }

        if (interactionMode.current === 'IDLE') return;

        if (interactionMode.current === 'PAN') {
            // FIX: Removed inversion (-dx, -dy) to make drag follow mouse
            onCameraPan(dx, dy); 
            return;
        }

        if (interactionMode.current === 'PAINT') {
            if (engine.isValid(h.q, h.r)) executeToolAction(h);
            return;
        }

        if (interactionMode.current === 'DRAG_UNIT' && pressedAgentRef.current) {
            const wPos = getWorldPosFromCoords(sx, sy);
            pressedAgentRef.current.px = wPos.x;
            pressedAgentRef.current.py = wPos.y;
            return;
        }

        if (interactionMode.current === 'DRAG_OBS' && draggedObstacleRef.current) {
            const wPos = getWorldPosFromCoords(sx, sy);
            draggedObstacleRef.current.px = wPos.x;
            draggedObstacleRef.current.py = wPos.y;
            return;
        }

        if (interactionMode.current === 'DOWN' && pressStartPos.current) {
            const dist = Math.sqrt((sx - pressStartPos.current.x)**2 + (sy - pressStartPos.current.y)**2);
            if (dist > 10) {
                const _tool = toolRef.current;

                if (pressedAgentRef.current && _tool !== ToolType.DELETE) {
                    interactionMode.current = 'DRAG_UNIT';
                    pressedAgentRef.current.physics.z = 20; 
                    onSelect(pressedAgentRef.current);
                    return;
                }
                if (draggedObstacleRef.current && _tool !== ToolType.DELETE) {
                    interactionMode.current = 'DRAG_OBS';
                    const { originQ, originR } = draggedObstacleRef.current;
                    engine.removeObstacle(originQ, originR);
                    onSelect(null);
                    const wPos = getWorldPosFromCoords(sx, sy);
                    draggedObstacleRef.current.px = wPos.x;
                    draggedObstacleRef.current.py = wPos.y;
                    return;
                }
                if (engine.isValid(h.q, h.r) && (_tool === ToolType.OBSTACLE || _tool === ToolType.DELETE)) {
                    interactionMode.current = 'PAINT';
                    executeToolAction(h);
                } else {
                    interactionMode.current = 'PAN';
                    // We consume the initial drag to prevent jump
                    // FIX: Removed inversion here too
                    onCameraPan(dx, dy);
                }
            }
        }
    };

    const handleUp = (sx: number, sy: number) => {
        const h = getHexFromCoords(sx, sy);
        const _tool = toolRef.current;

        if (interactionMode.current === 'DOWN') {
            if (pressedAgentRef.current) {
                if (_tool === ToolType.DELETE) {
                    engine.removeAgent(pressedAgentRef.current.q, pressedAgentRef.current.r);
                    onSelect(null);
                } else {
                    onSelect(pressedAgentRef.current);
                }
            } else if (engine.hasObstacle(h.q, h.r)) {
                if (_tool === ToolType.DELETE) engine.removeObstacle(h.q, h.r);
            } else if (_tool !== ToolType.SELECT && _tool !== ToolType.DELETE) {
                if (engine.isValid(h.q, h.r)) executeToolAction(h);
            } else {
                onSelect(null);
            }
        }

        if (interactionMode.current === 'DRAG_UNIT' && pressedAgentRef.current) {
            const agent = pressedAgentRef.current;
            agent.physics.z = 0;
            const valid = engine.isValid(h.q, h.r) && !engine.hasObstacle(h.q, h.r) && (!engine.getAgentAt(h.q, h.r) || engine.getAgentAt(h.q, h.r) === agent);

            if (valid) {
                engine.updateAgentPosition(agent, h.q, h.r);
                const p = HexUtils.toPx(h.q, h.r, engine.mapConfig);
                agent.px = p.x; agent.py = p.y;
            } else if (dragStartHex.current) {
                agent.q = dragStartHex.current.q;
                agent.r = dragStartHex.current.r;
                const p = HexUtils.toPx(agent.q, agent.r, engine.mapConfig);
                agent.px = p.x; agent.py = p.y;
                engine.updateAgentPosition(agent, agent.q, agent.r);
            }
            onSelect(agent);
        }

        if (interactionMode.current === 'DRAG_OBS' && draggedObstacleRef.current) {
            const { type, originQ, originR } = draggedObstacleRef.current;
            const valid = engine.isValid(h.q, h.r) && !engine.getAgentAt(h.q, h.r) && !engine.hasObstacle(h.q, h.r);

            if (valid) engine.setObstacle(h.q, h.r, type);
            else engine.setObstacle(originQ, originR, type); 
        }

        interactionMode.current = 'IDLE';
        pressedAgentRef.current = null;
        draggedObstacleRef.current = null;
        pressStartPos.current = null;
        lastMousePos.current = null;
        lastPaintHex.current = "";
        if (canvasRef.current) canvasRef.current.style.cursor = 'default';
    };

    // --- Listeners Binding ---
    useEffect(() => {
        const cvs = canvasRef.current;
        if (!cvs) return;

        const getCoords = (e: MouseEvent | Touch) => {
            const rect = cvs.getBoundingClientRect();
            return { x: e.clientX - rect.left, y: e.clientY - rect.top };
        };

        const onMouseDown = (e: MouseEvent) => {
            const {x, y} = getCoords(e);
            handleDown(x, y, e.button);
        };
        const onMouseMove = (e: MouseEvent) => {
            const {x, y} = getCoords(e);
            handleMove(x, y);
        };
        const onMouseUp = (e: MouseEvent) => {
            const {x, y} = getCoords(e);
            handleUp(x, y);
        };

        const onTouchStart = (e: TouchEvent) => {
            if (e.cancelable) e.preventDefault();

            if (e.touches.length === 1) {
                const {x, y} = getCoords(e.touches[0]);
                lastTouchPos.current = {x, y};
                handleDown(x, y, 0);
            } else if (e.touches.length === 2) {
                const t1 = getCoords(e.touches[0]);
                const t2 = getCoords(e.touches[1]);
                lastPinchDist.current = Math.hypot(t1.x - t2.x, t1.y - t2.y);
                interactionMode.current = 'IDLE';
                pressedAgentRef.current = null;
                draggedObstacleRef.current = null;
            }
        };

        const onTouchMove = (e: TouchEvent) => {
            if (e.cancelable) e.preventDefault();

            if (e.touches.length === 1 && lastTouchPos.current) {
                if (lastPinchDist.current > 0) {
                    const {x, y} = getCoords(e.touches[0]);
                    lastTouchPos.current = {x, y};
                    lastPinchDist.current = 0;
                    return;
                }

                const {x, y} = getCoords(e.touches[0]);
                // Manual delta for touch
                // Note: Touch delta is not used directly, we rely on state tracking
                // But for move handler we need sx, sy
                handleMove(x, y);
                lastTouchPos.current = {x, y};
            } else if (e.touches.length === 2) {
                const t1 = getCoords(e.touches[0]);
                const t2 = getCoords(e.touches[1]);
                const dist = Math.hypot(t1.x - t2.x, t1.y - t2.y);
                if (lastPinchDist.current > 0) {
                    const delta = dist - lastPinchDist.current;
                    onCameraZoom(delta * 0.005);
                }
                lastPinchDist.current = dist;
            }
        };

        const onTouchEnd = (e: TouchEvent) => {
            if (e.cancelable) e.preventDefault();

            if (e.changedTouches.length > 0 && lastTouchPos.current) {
                if (e.touches.length === 0) {
                    const {x, y} = getCoords(e.changedTouches[0]);
                    handleUp(x, y);
                }
            }
            if (e.touches.length < 2) {
                lastPinchDist.current = 0;
            }
            if (e.touches.length === 0) {
                lastTouchPos.current = null;
            }
        };

        const onTouchCancel = (e: TouchEvent) => {
            if (e.cancelable) e.preventDefault();
            interactionMode.current = 'IDLE';
            pressedAgentRef.current = null;
            draggedObstacleRef.current = null;
            lastTouchPos.current = null;
            lastPinchDist.current = 0;
        };

        const onWheel = (e: WheelEvent) => {
            e.preventDefault();
            const delta = e.deltaY > 0 ? -0.1 : 0.1;
            onCameraZoom(delta);
        };

        const onCtx = (e: MouseEvent) => e.preventDefault();

        cvs.addEventListener('mousedown', onMouseDown);
        window.addEventListener('mousemove', onMouseMove);
        window.addEventListener('mouseup', onMouseUp);
        cvs.addEventListener('wheel', onWheel, { passive: false });
        cvs.addEventListener('contextmenu', onCtx);
        cvs.addEventListener('touchstart', onTouchStart, { passive: false });
        cvs.addEventListener('touchmove', onTouchMove, { passive: false });
        cvs.addEventListener('touchend', onTouchEnd, { passive: false });
        cvs.addEventListener('touchcancel', onTouchCancel, { passive: false });

        return () => {
            cvs.removeEventListener('mousedown', onMouseDown);
            window.removeEventListener('mousemove', onMouseMove);
            window.removeEventListener('mouseup', onMouseUp);
            cvs.removeEventListener('wheel', onWheel);
            cvs.removeEventListener('contextmenu', onCtx);
            cvs.removeEventListener('touchstart', onTouchStart);
            cvs.removeEventListener('touchmove', onTouchMove);
            cvs.removeEventListener('touchend', onTouchEnd);
            cvs.removeEventListener('touchcancel', onTouchCancel);
        };
    }, [engine, onSelect, onCameraPan, onCameraZoom]); 

    return {
        pressedAgent: pressedAgentRef.current,
        draggedObstacle: draggedObstacleRef.current,
        hoveredHex: hoveredHexRef.current
    };
};

import React, { useState } from 'react';
import { ToolType, Role } from '../../types';
import { SCENE_DB } from '../../data/scenes';
import { OBSTACLE_DB } from '../../data/obstacles';

interface MapEditorToolbarProps {
    tool: ToolType;
    setTool: (t: ToolType) => void;

    // Configs
    mapW: number;
    setMapW: (v: number) => void;
    mapH: number;
    setMapH: (v: number) => void;
    currentSceneId: string;
    onSetScene: (id: string) => void;

    // Spawn Settings
    spawnMode: 'RANDOM' | 'DRAFT';
    setSpawnMode: (m: 'RANDOM' | 'DRAFT') => void;
    draftRole: Role;
    setDraftRole: (r: Role) => void;
    hpInput: number;
    setHpInput: (v: number) => void;

    // Obstacle Settings
    selectedObstacle: string;
    setSelectedObstacle: (v: string) => void;

    // Actions
    onRandomBattlefield: () => void;
    onReset: () => void;
}

export const MapEditorToolbar: React.FC<MapEditorToolbarProps> = (props) => {
    const { 
        tool, setTool, 
        mapW, setMapW, mapH, setMapH, currentSceneId, onSetScene,
        spawnMode, setSpawnMode, draftRole, setDraftRole, hpInput, setHpInput,
        selectedObstacle, setSelectedObstacle,
        onRandomBattlefield, onReset
    } = props;

    const [showConfig, setShowConfig] = useState(false);

    // Contextual Sub-bar content
    const renderContextBar = () => {
        if (tool === ToolType.ADD_BLUE || tool === ToolType.ADD_RED) {
            return (
                <div className="flex items-center gap-2 bg-slate-900/90 p-2 rounded-t-lg border-x border-t border-slate-700 mx-auto w-fit animate-slide-up">
                    <div className="flex bg-slate-950 rounded p-0.5 border border-slate-700">
                        <button onClick={() => setSpawnMode('RANDOM')} className={`px-2 py-1 text-[10px] rounded ${spawnMode === 'RANDOM' ? 'bg-cyan-900 text-cyan-300' : 'text-slate-500'}`}>隨機</button>
                        <button onClick={() => setSpawnMode('DRAFT')} className={`px-2 py-1 text-[10px] rounded ${spawnMode === 'DRAFT' ? 'bg-amber-900 text-amber-300' : 'text-slate-500'}`}>自選</button>
                    </div>

                    {spawnMode === 'DRAFT' && (
                        <select 
                            value={draftRole} 
                            onChange={(e) => setDraftRole(e.target.value as Role)}
                            className="bg-slate-950 border border-slate-700 text-slate-300 text-xs px-2 py-1 rounded outline-none"
                        >
                            {Object.values(Role).map(r => <option key={r} value={r}>{r}</option>)}
                        </select>
                    )}

                    <div className="w-px h-4 bg-slate-700 mx-1"></div>

                    <div className="flex items-center gap-1">
                        <span className="text-[10px] text-slate-500 font-bold">HP</span>
                        <input 
                            type="number" 
                            value={hpInput} 
                            onChange={(e) => setHpInput(parseInt(e.target.value))} 
                            className="w-12 bg-slate-950 border border-slate-700 text-center text-xs text-green-400 rounded py-1 outline-none focus:border-green-500"
                        />
                    </div>
                </div>
            );
        }
        if (tool === ToolType.OBSTACLE) {
            return (
                <div className="flex items-center gap-2 bg-slate-900/90 p-2 rounded-t-lg border-x border-t border-slate-700 mx-auto w-fit animate-slide-up">
                    <span className="text-[10px] text-slate-500 font-bold">類型</span>
                    <select 
                        value={selectedObstacle} 
                        onChange={(e) => setSelectedObstacle(e.target.value)}
                        className="bg-slate-950 border border-slate-700 text-slate-300 text-xs px-2 py-1 rounded outline-none w-32"
                    >
                        {Object.values(OBSTACLE_DB).map(o => <option key={o.id} value={o.id}>{o.name}</option>)}
                    </select>
                </div>
            );
        }
        return null;
    };

    return (
        <div className="fixed bottom-0 left-0 w-full z-50 pointer-events-none flex flex-col items-center pb-[env(safe-area-inset-bottom)]">

            {/* 1. Contextual Sub-bar (Floating above main bar) */}
            <div className="pointer-events-auto mb-[-1px] z-0 relative">
                {renderContextBar()}
            </div>

            {/* 2. Main Toolbar */}
            <div className="pointer-events-auto bg-slate-950/95 backdrop-blur border-t border-slate-800 shadow-2xl w-full flex flex-col sm:flex-row items-center justify-between px-2 py-2 sm:px-4 gap-2 sm:gap-0 z-10">

                {/* Left: Map Config Toggle */}
                <div className="flex items-center gap-2 w-full sm:w-auto justify-between sm:justify-start">
                    <button 
                        onClick={() => setShowConfig(!showConfig)}
                        className={`flex items-center gap-2 px-3 py-2 rounded border transition-all ${showConfig ? 'bg-slate-800 border-cyan-500 text-cyan-400' : 'bg-transparent border-slate-700 text-slate-400 hover:text-slate-200'}`}
                    >
                        <span className="text-lg">⚙️</span>
                        <span className="text-xs font-bold hidden sm:inline">地圖設定</span>
                    </button>

                    {/* Quick Scene Selector (Mobile optimized) */}
                    <select 
                        value={currentSceneId} 
                        onChange={(e) => onSetScene(e.target.value)}
                        className="bg-slate-900 border border-slate-700 text-slate-300 text-xs px-2 py-2 rounded outline-none sm:w-32"
                    >
                        {SCENE_DB.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                    </select>
                </div>

                {/* Center: Tools */}
                <div className="flex items-center gap-1 sm:gap-2 bg-slate-900/50 p-1 rounded-lg border border-slate-800">
                    <button onClick={() => setTool(ToolType.SELECT)} className={`w-10 h-10 rounded flex items-center justify-center text-lg transition-all ${tool === ToolType.SELECT ? 'bg-slate-700 text-white shadow-sm' : 'text-slate-500 hover:text-slate-300'}`} title="選取">↖</button>
                    <div className="w-px h-6 bg-slate-700 mx-1"></div>
                    <button onClick={() => setTool(ToolType.ADD_BLUE)} className={`w-10 h-10 rounded flex items-center justify-center text-xl transition-all ${tool === ToolType.ADD_BLUE ? 'bg-blue-900/50 border border-blue-500 text-blue-400 shadow-[0_0_10px_rgba(59,130,246,0.3)]' : 'text-slate-500 hover:text-blue-400'}`} title="部署藍軍">🔵</button>
                    <button onClick={() => setTool(ToolType.ADD_RED)} className={`w-10 h-10 rounded flex items-center justify-center text-xl transition-all ${tool === ToolType.ADD_RED ? 'bg-red-900/50 border border-red-500 text-red-400 shadow-[0_0_10px_rgba(239,68,68,0.3)]' : 'text-slate-500 hover:text-red-400'}`} title="部署紅軍">🔴</button>
                    <div className="w-px h-6 bg-slate-700 mx-1"></div>
                    <button onClick={() => setTool(ToolType.OBSTACLE)} className={`w-10 h-10 rounded flex items-center justify-center text-xl transition-all ${tool === ToolType.OBSTACLE ? 'bg-amber-900/30 border border-amber-500 text-amber-400' : 'text-slate-500 hover:text-amber-400'}`} title="放置障礙">🧱</button>
                    <button onClick={() => setTool(ToolType.DELETE)} className={`w-10 h-10 rounded flex items-center justify-center text-xl transition-all ${tool === ToolType.DELETE ? 'bg-slate-800 border border-red-500 text-red-500' : 'text-slate-500 hover:text-red-500'}`} title="移除">❌</button>
                </div>

                {/* Right: Actions */}
                <div className="flex items-center gap-2 w-full sm:w-auto justify-end">
                    <button 
                        onClick={onRandomBattlefield}
                        className="px-4 py-2 bg-purple-900/30 border border-purple-500/50 hover:border-purple-400 text-purple-300 rounded text-xs font-bold tracking-wider flex items-center gap-2 hover:shadow-[0_0_15px_rgba(168,85,247,0.3)] transition-all"
                    >
                        <span>🎲</span> 隨機戰場
                    </button>
                    <button 
                        onClick={onReset}
                        className="w-10 h-10 flex items-center justify-center rounded border border-slate-700 text-slate-400 hover:text-white hover:border-slate-500 transition-all bg-slate-900"
                        title="重置單位狀態"
                    >
                        ↺
                    </button>
                </div>
            </div>

            {/* 3. Slide-up Config Panel */}
            {showConfig && (
                <div className="pointer-events-auto absolute bottom-full left-0 mb-2 ml-2 p-4 bg-slate-900/95 border border-slate-700 rounded-lg shadow-2xl animate-slide-up w-64 backdrop-blur">
                    <div className="text-xs font-bold text-slate-500 uppercase mb-3">地圖參數</div>
                    <div className="grid grid-cols-2 gap-3 mb-4">
                        <div>
                            <label className="text-[10px] text-slate-400 block mb-1">寬度</label>
                            <input type="number" value={mapW} onChange={e => setMapW(Math.max(4, Math.min(30, parseInt(e.target.value))))} className="tactical-input w-full text-center"/>
                        </div>
                        <div>
                            <label className="text-[10px] text-slate-400 block mb-1">高度</label>
                            <input type="number" value={mapH} onChange={e => setMapH(Math.max(4, Math.min(30, parseInt(e.target.value))))} className="tactical-input w-full text-center"/>
                        </div>
                    </div>
                    <div className="text-[9px] text-slate-500">
                        * 調整尺寸將會清空當前地圖
                    </div>
                </div>
            )}
        </div>
    );
};

import { useRef, useEffect, MutableRefObject } from 'react';
import { GameEngine, Agent } from '../engine/game';
import { ToolType, Hex, Team, Role, Skill } from '../types';
import { HexUtils } from '../engine/utils';
import { GameRenderer } from '../engine/renderer';
import { BLOCK_HEIGHT } from '../constants';

interface GameInputProps {
    canvasRef: MutableRefObject<HTMLCanvasElement | null>;
    engine: GameEngine;
    rendererRef: MutableRefObject<GameRenderer>;
    cameraRef: MutableRefObject<{ x: number; y: number; zoom: number }>;

    // Tool State
    tool: ToolType;
    selectedObstacle: string;
    hpInput: number;
    spawnMode: 'RANDOM' | 'DRAFT';
    draftRole: Role;
    winner: Team | null;

    // Callbacks
    onSelect: (a: Agent | null) => void;
    onCameraPan: (dx: number, dy: number) => void;
    onCameraZoom: (delta: number) => void;
}

export const useGameInput = ({
    canvasRef, engine, rendererRef, cameraRef,
    tool, selectedObstacle, hpInput, spawnMode, draftRole, winner,
    onSelect, onCameraPan, onCameraZoom
}: GameInputProps) => {

    // Interaction State
    type InteractionMode = 'IDLE' | 'DOWN' | 'DRAG_UNIT' | 'DRAG_OBS' | 'PAN' | 'PAINT';
    const interactionMode = useRef<InteractionMode>('IDLE');

    // Props Refs
    const toolRef = useRef(tool);
    const obsRef = useRef(selectedObstacle);
    const hpRef = useRef(hpInput);
    const spawnRef = useRef(spawnMode);
    const roleRef = useRef(draftRole);
    const winnerRef = useRef(winner);

    useEffect(() => {
        toolRef.current = tool;
        obsRef.current = selectedObstacle;
        hpRef.current = hpInput;
        spawnRef.current = spawnMode;
        roleRef.current = draftRole;
        winnerRef.current = winner;
    }, [tool, selectedObstacle, hpInput, spawnMode, draftRole, winner]);

    // Operational Refs
    const pressedAgentRef = useRef<Agent | null>(null);
    const draggedObstacleRef = useRef<{ type: string; originQ: number; originR: number; px: number; py: number; } | null>(null);
    const pressStartPos = useRef<{x: number, y: number} | null>(null);
    const dragStartHex = useRef<{q: number, r: number} | null>(null);
    const lastPaintHex = useRef<string>(""); 
    const hoveredHexRef = useRef<Hex | null>(null);

    // --- Helpers ---

    const getHexFromCoords = (sx: number, sy: number) => {
        const hex = rendererRef.current.getHexAtScreenPoint(sx, sy, cameraRef.current, engine);
        if (hex) return hex;
        return HexUtils.fromPx(
            sx / cameraRef.current.zoom + cameraRef.current.x,
            sy / cameraRef.current.zoom + cameraRef.current.y,
            engine.mapConfig
        );
    };

    const getWorldPosFromCoords = (sx: number, sy: number) => {
        const wx = sx / cameraRef.current.zoom + cameraRef.current.x;
        const hex = rendererRef.current.getHexAtScreenPoint(sx, sy, cameraRef.current, engine);
        let h = BLOCK_HEIGHT + 6;
        if (hex) h = rendererRef.current.getTerrainHeight(hex.q, hex.r, engine);
        const wy = sy / cameraRef.current.zoom + cameraRef.current.y + h;
        return { x: wx, y: wy };
    };

    const getHitAgentFromCoords = (sx: number, sy: number) => {
        const wx = sx / cameraRef.current.zoom + cameraRef.current.x;
        const wy = sy / cameraRef.current.zoom + cameraRef.current.y;
        const sorted = [...engine.agents].sort((a, b) => b.py - a.py); 

        for (const agent of sorted) {
            if (agent.hp <= 0 && agent.fullyDead) continue;
            const h = rendererRef.current.getTerrainHeight(agent.q, agent.r, engine);
            const baseX = agent.px;
            const baseY = agent.py - h;
            const dx = Math.abs(wx - baseX);
            const dy = wy - (baseY - 40); 
            if (dx < 35 && Math.abs(dy) < 60) return agent;
        }
        return null;
    };

    const executeToolAction = (h: Hex) => {
        const _tool = toolRef.current;
        const _winner = winnerRef.current;
        const _obs = obsRef.current;
        const _hp = hpRef.current;

        if (engine.isRunning || _winner !== null) return;
        const k = HexUtils.key(h);
        if (lastPaintHex.current === k) return; 

        lastPaintHex.current = k;
        const existingAgent = engine.getAgentAt(h.q, h.r);
        let agent: Agent | null = null;

        if (_tool === ToolType.DELETE) {
            if (engine.hasObstacle(h.q, h.r)) engine.removeObstacle(h.q, h.r);
            if (existingAgent) {
                engine.removeAgent(h.q, h.r);
                onSelect(null);
            }
            return;
        }

        if (_tool === ToolType.OBSTACLE) {
            if (existingAgent) engine.removeAgent(h.q, h.r);
            engine.setObstacle(h.q, h.r, _obs);
            return;
        }

        if (!existingAgent && !engine.hasObstacle(h.q, h.r)) {
            if (_tool === ToolType.ADD_BLUE) agent = engine.addAgent(Team.BLUE, h.q, h.r, _hp);
            else if (_tool === ToolType.ADD_RED) agent = engine.addAgent(Team.RED, h.q, h.r, _hp);
        }

        if (agent && spawnRef.current === 'DRAFT') {
            agent.role = roleRef.current;
            const validSkills = engine.skillDB.filter(s => s.role === agent!.role && (s.team === undefined || s.team === agent!.team));
            const rnd = (ar: Skill[]) => ar.length > 0 ? ar[Math.floor(Math.random() * ar.length)].id : null;
            agent.skillIds = [
                rnd(validSkills.filter(s => s.tag === 'ULT')),
                rnd(validSkills.filter(s => s.tag === 'ACTIVE')),
                rnd(validSkills.filter(s => s.tag === 'BASIC'))
            ];
            agent.saveState();
            agent.reset(engine.mapConfig);
        }
    };

    // --- Core Logic Shared by Mouse & Touch ---

    const handleStart = (sx: number, sy: number, isRightClick: boolean) => {
        pressStartPos.current = { x: sx, y: sy };
        lastPaintHex.current = "";
        interactionMode.current = 'DOWN';

        if (isRightClick || engine.isRunning) {
            interactionMode.current = 'PAN';
            return;
        }

        const hitAgent = getHitAgentFromCoords(sx, sy);
        if (hitAgent) {
            pressedAgentRef.current = hitAgent;
            if (toolRef.current !== ToolType.DELETE) {
                dragStartHex.current = { q: hitAgent.q, r: hitAgent.r };
            }
            return;
        }

        const h = getHexFromCoords(sx, sy);
        if (engine.isValid(h.q, h.r) && engine.hasObstacle(h.q, h.r) && toolRef.current !== ToolType.DELETE) {
            const obsType = engine.obstacles.get(HexUtils.key(h));
            if (obsType) {
                draggedObstacleRef.current = { type: obsType, originQ: h.q, originR: h.r, px: 0, py: 0 };
            }
        }
    };

    const handleMoveLogic = (sx: number, sy: number, dx: number, dy: number) => {
        const h = getHexFromCoords(sx, sy);
        hoveredHexRef.current = engine.isValid(h.q, h.r) ? h : null;

        const cvs = canvasRef.current;
        if (cvs) {
            if (interactionMode.current === 'PAN') cvs.style.cursor = 'move';
            else if (interactionMode.current === 'DRAG_UNIT' || interactionMode.current === 'DRAG_OBS') cvs.style.cursor = 'grabbing';
            else cvs.style.cursor = 'default';
        }

        if (interactionMode.current === 'IDLE') return;

        if (interactionMode.current === 'PAN') {
            // FIX: Inverted sign based on feedback
            // Previously `dx`, now `-dx`. 
            // If dragging LEFT (dx < 0), we want camera to move RIGHT (x increases) to show map to the left.
            // onCameraPan does (x - delta). 
            // So if we pass (-dx), and dx is negative (-10), we pass (10). x - 10. Camera Left.
            // Wait, previous logic was `onCameraPan(dx, dy)`.
            // Let's force inverting the input delta to flip the feel.
            onCameraPan(-dx, -dy); 
            return;
        }

        if (interactionMode.current === 'PAINT') {
            if (engine.isValid(h.q, h.r)) executeToolAction(h);
            return;
        }

        if (interactionMode.current === 'DRAG_UNIT' && pressedAgentRef.current) {
            const wPos = getWorldPosFromCoords(sx, sy);
            pressedAgentRef.current.px = wPos.x;
            pressedAgentRef.current.py = wPos.y;
            return;
        }

        if (interactionMode.current === 'DRAG_OBS' && draggedObstacleRef.current) {
            const wPos = getWorldPosFromCoords(sx, sy);
            draggedObstacleRef.current.px = wPos.x;
            draggedObstacleRef.current.py = wPos.y;
            return;
        }

        if (interactionMode.current === 'DOWN' && pressStartPos.current) {
            const dist = Math.sqrt((sx - pressStartPos.current.x)**2 + (sy - pressStartPos.current.y)**2);
            if (dist > 10) {
                const _tool = toolRef.current;

                if (pressedAgentRef.current && _tool !== ToolType.DELETE) {
                    interactionMode.current = 'DRAG_UNIT';
                    pressedAgentRef.current.physics.z = 20; 
                    onSelect(pressedAgentRef.current);
                    return;
                }
                if (draggedObstacleRef.current && _tool !== ToolType.DELETE) {
                    interactionMode.current = 'DRAG_OBS';
                    const { originQ, originR } = draggedObstacleRef.current;
                    engine.removeObstacle(originQ, originR);
                    onSelect(null);
                    const wPos = getWorldPosFromCoords(sx, sy);
                    draggedObstacleRef.current.px = wPos.x;
                    draggedObstacleRef.current.py = wPos.y;
                    return;
                }
                if (engine.isValid(h.q, h.r) && (_tool === ToolType.OBSTACLE || _tool === ToolType.DELETE)) {
                    interactionMode.current = 'PAINT';
                    executeToolAction(h);
                } else {
                    interactionMode.current = 'PAN';
                    // Consume initial drag
                    onCameraPan(-dx, -dy);
                }
            }
        }
    };

    const handleEnd = (sx: number, sy: number) => {
        const h = getHexFromCoords(sx, sy);
        const _tool = toolRef.current;

        if (interactionMode.current === 'DOWN') {
            // Click Logic
            if (pressedAgentRef.current) {
                if (_tool === ToolType.DELETE) {
                    engine.removeAgent(pressedAgentRef.current.q, pressedAgentRef.current.r);
                    onSelect(null);
                } else {
                    onSelect(pressedAgentRef.current);
                }
            } else if (engine.hasObstacle(h.q, h.r)) {
                if (_tool === ToolType.DELETE) engine.removeObstacle(h.q, h.r);
            } else if (_tool !== ToolType.SELECT && _tool !== ToolType.DELETE) {
                if (engine.isValid(h.q, h.r)) executeToolAction(h);
            } else {
                onSelect(null);
            }
        }

        if (interactionMode.current === 'DRAG_UNIT' && pressedAgentRef.current) {
            const agent = pressedAgentRef.current;
            agent.physics.z = 0;
            const valid = engine.isValid(h.q, h.r) && !engine.hasObstacle(h.q, h.r) && (!engine.getAgentAt(h.q, h.r) || engine.getAgentAt(h.q, h.r) === agent);

            if (valid) {
                engine.updateAgentPosition(agent, h.q, h.r);
                const p = HexUtils.toPx(h.q, h.r, engine.mapConfig);
                agent.px = p.x; agent.py = p.y;
            } else if (dragStartHex.current) {
                agent.q = dragStartHex.current.q;
                agent.r = dragStartHex.current.r;
                const p = HexUtils.toPx(agent.q, agent.r, engine.mapConfig);
                agent.px = p.x; agent.py = p.y;
                engine.updateAgentPosition(agent, agent.q, agent.r);
            }
            onSelect(agent);
        }

        if (interactionMode.current === 'DRAG_OBS' && draggedObstacleRef.current) {
            const { type, originQ, originR } = draggedObstacleRef.current;
            const valid = engine.isValid(h.q, h.r) && !engine.getAgentAt(h.q, h.r) && !engine.hasObstacle(h.q, h.r);

            if (valid) engine.setObstacle(h.q, h.r, type);
            else engine.setObstacle(originQ, originR, type); 
        }

        interactionMode.current = 'IDLE';
        pressedAgentRef.current = null;
        draggedObstacleRef.current = null;
        pressStartPos.current = null;
        lastPaintHex.current = "";
        if (canvasRef.current) canvasRef.current.style.cursor = 'default';
    };

    // --- MOUSE BINDINGS ---
    useEffect(() => {
        const cvs = canvasRef.current;
        if (!cvs) return;

        let lastMouse = { x: 0, y: 0 };

        const getCoords = (e: MouseEvent) => {
            const rect = cvs.getBoundingClientRect();
            return { x: e.clientX - rect.left, y: e.clientY - rect.top };
        };

        const onMouseDown = (e: MouseEvent) => {
            const {x, y} = getCoords(e);
            lastMouse = {x, y};
            handleStart(x, y, e.button === 2);
        };

        const onMouseMove = (e: MouseEvent) => {
            const {x, y} = getCoords(e);
            const dx = x - lastMouse.x;
            const dy = y - lastMouse.y;
            lastMouse = {x, y};
            handleMoveLogic(x, y, dx, dy);
        };

        const onMouseUp = (e: MouseEvent) => {
            const {x, y} = getCoords(e);
            handleEnd(x, y);
        };

        const onWheel = (e: WheelEvent) => {
            e.preventDefault();
            const delta = e.deltaY > 0 ? -0.1 : 0.1;
            onCameraZoom(delta);
        };

        const onCtx = (e: MouseEvent) => e.preventDefault();

        cvs.addEventListener('mousedown', onMouseDown);
        window.addEventListener('mousemove', onMouseMove);
        window.addEventListener('mouseup', onMouseUp);
        cvs.addEventListener('wheel', onWheel, { passive: false });
        cvs.addEventListener('contextmenu', onCtx);

        return () => {
            cvs.removeEventListener('mousedown', onMouseDown);
            window.removeEventListener('mousemove', onMouseMove);
            window.removeEventListener('mouseup', onMouseUp);
            cvs.removeEventListener('wheel', onWheel);
            cvs.removeEventListener('contextmenu', onCtx);
        };
    }, [engine]); // Dependencies reduced

    // --- TOUCH BINDINGS ---
    useEffect(() => {
        const cvs = canvasRef.current;
        if (!cvs) return;

        let lastTouch = { x: 0, y: 0 };
        let lastPinch = 0;

        const getCoords = (t: Touch) => {
            const rect = cvs.getBoundingClientRect();
            return { x: t.clientX - rect.left, y: t.clientY - rect.top };
        };

        const onTouchStart = (e: TouchEvent) => {
            if (e.cancelable) e.preventDefault();

            if (e.touches.length === 1) {
                const {x, y} = getCoords(e.touches[0]);
                lastTouch = {x, y};
                handleStart(x, y, false);
            } else if (e.touches.length === 2) {
                const t1 = getCoords(e.touches[0]);
                const t2 = getCoords(e.touches[1]);
                lastPinch = Math.hypot(t1.x - t2.x, t1.y - t2.y);
                interactionMode.current = 'IDLE';
                pressedAgentRef.current = null;
            }
        };

        const onTouchMove = (e: TouchEvent) => {
            if (e.cancelable) e.preventDefault();

            if (e.touches.length === 1) {
                const {x, y} = getCoords(e.touches[0]);
                // Ignore pinch logic if 1 finger
                if (lastPinch > 0) {
                    lastPinch = 0;
                    lastTouch = {x, y}; // Reset to avoid jump
                    return;
                }
                const dx = x - lastTouch.x;
                const dy = y - lastTouch.y;
                lastTouch = {x, y};
                handleMoveLogic(x, y, dx, dy);

            } else if (e.touches.length === 2) {
                const t1 = getCoords(e.touches[0]);
                const t2 = getCoords(e.touches[1]);
                const dist = Math.hypot(t1.x - t2.x, t1.y - t2.y);

                if (lastPinch > 0) {
                    const delta = dist - lastPinch;
                    onCameraZoom(delta * 0.005);
                }
                lastPinch = dist;
            }
        };

        const onTouchEnd = (e: TouchEvent) => {
            if (e.cancelable) e.preventDefault();
            if (e.touches.length === 0) {
                // Last finger lifted
                if (e.changedTouches.length > 0) {
                    const {x, y} = getCoords(e.changedTouches[0]);
                    handleEnd(x, y);
                }
                lastPinch = 0;
            }
        };

        cvs.addEventListener('touchstart', onTouchStart, { passive: false });
        cvs.addEventListener('touchmove', onTouchMove, { passive: false });
        cvs.addEventListener('touchend', onTouchEnd, { passive: false });
        cvs.addEventListener('touchcancel', onTouchEnd, { passive: false });

        return () => {
            cvs.removeEventListener('touchstart', onTouchStart);
            cvs.removeEventListener('touchmove', onTouchMove);
            cvs.removeEventListener('touchend', onTouchEnd);
            cvs.removeEventListener('touchcancel', onTouchEnd);
        };
    }, [engine]);

    return {
        pressedAgent: pressedAgentRef.current,
        draggedObstacle: draggedObstacleRef.current,
        hoveredHex: hoveredHexRef.current
    };
};

import React, { useState } from 'react';
import { ToolType, Role } from '../../types';
import { SCENE_DB } from '../../data/scenes';
import { OBSTACLE_DB } from '../../data/obstacles';

interface MapEditorToolbarProps {
    tool: ToolType;
    setTool: (t: ToolType) => void;

    // Configs
    mapW: number;
    setMapW: (v: number) => void;
    mapH: number;
    setMapH: (v: number) => void;
    currentSceneId: string;
    onSetScene: (id: string) => void;

    // Spawn Settings
    spawnMode: 'RANDOM' | 'DRAFT';
    setSpawnMode: (m: 'RANDOM' | 'DRAFT') => void;
    draftRole: Role;
    setDraftRole: (r: Role) => void;
    hpInput: number;
    setHpInput: (v: number) => void;

    // Obstacle Settings
    selectedObstacle: string;
    setSelectedObstacle: (v: string) => void;

    // Actions
    onRandomBattlefield: () => void;
    onReset: () => void;
}

export const MapEditorToolbar: React.FC<MapEditorToolbarProps> = (props) => {
    const { 
        tool, setTool, 
        mapW, setMapW, mapH, setMapH, currentSceneId, onSetScene,
        spawnMode, setSpawnMode, draftRole, setDraftRole, hpInput, setHpInput,
        selectedObstacle, setSelectedObstacle,
        onRandomBattlefield, onReset
    } = props;

    const [showConfig, setShowConfig] = useState(false);

    // Contextual Sub-bar content
    const renderContextBar = () => {
        if (tool === ToolType.ADD_BLUE || tool === ToolType.ADD_RED) {
            return (
                <div className="flex items-center gap-2 bg-slate-900/90 p-2 rounded-t-lg border-x border-t border-slate-700 mx-auto w-fit animate-slide-up">
                    <div className="flex bg-slate-950 rounded p-0.5 border border-slate-700">
                        <button onClick={() => setSpawnMode('RANDOM')} className={`px-2 py-1 text-[10px] rounded ${spawnMode === 'RANDOM' ? 'bg-cyan-900 text-cyan-300' : 'text-slate-500'}`}>隨機</button>
                        <button onClick={() => setSpawnMode('DRAFT')} className={`px-2 py-1 text-[10px] rounded ${spawnMode === 'DRAFT' ? 'bg-amber-900 text-amber-300' : 'text-slate-500'}`}>自選</button>
                    </div>

                    {spawnMode === 'DRAFT' && (
                        <select 
                            value={draftRole} 
                            onChange={(e) => setDraftRole(e.target.value as Role)}
                            className="bg-slate-950 border border-slate-700 text-slate-300 text-xs px-2 py-1 rounded outline-none"
                        >
                            {Object.values(Role).map(r => <option key={r} value={r}>{r}</option>)}
                        </select>
                    )}

                    <div className="w-px h-4 bg-slate-700 mx-1"></div>

                    <div className="flex items-center gap-1">
                        <span className="text-[10px] text-slate-500 font-bold">HP</span>
                        <input 
                            type="number" 
                            value={hpInput} 
                            onChange={(e) => setHpInput(parseInt(e.target.value))} 
                            className="w-12 bg-slate-950 border border-slate-700 text-center text-xs text-green-400 rounded py-1 outline-none focus:border-green-500"
                        />
                    </div>
                </div>
            );
        }
        if (tool === ToolType.OBSTACLE) {
            return (
                <div className="flex items-center gap-2 bg-slate-900/90 p-2 rounded-t-lg border-x border-t border-slate-700 mx-auto w-fit animate-slide-up">
                    <span className="text-[10px] text-slate-500 font-bold">類型</span>
                    <select 
                        value={selectedObstacle} 
                        onChange={(e) => setSelectedObstacle(e.target.value)}
                        className="bg-slate-950 border border-slate-700 text-slate-300 text-xs px-2 py-1 rounded outline-none w-32"
                    >
                        {Object.values(OBSTACLE_DB).map(o => <option key={o.id} value={o.id}>{o.name}</option>)}
                    </select>
                </div>
            );
        }
        return null;
    };

    return (
        // Changed: Fixed -> Absolute, Added z-index 100, Removed env padding as absolute handles container edge
        <div className="absolute bottom-0 left-0 w-full z-[100] pointer-events-none flex flex-col items-center">

            {/* 1. Contextual Sub-bar (Floating above main bar) */}
            <div className="pointer-events-auto mb-[-1px] z-0 relative">
                {renderContextBar()}
            </div>

            {/* 2. Main Toolbar */}
            <div className="pointer-events-auto bg-slate-950/95 backdrop-blur border-t border-slate-800 shadow-2xl w-full flex flex-col sm:flex-row items-center justify-between px-2 py-2 sm:px-4 gap-2 sm:gap-0 z-10 pb-4 sm:pb-2">

                {/* Left: Map Config Toggle */}
                <div className="flex items-center gap-2 w-full sm:w-auto justify-between sm:justify-start">
                    <button 
                        onClick={() => setShowConfig(!showConfig)}
                        className={`flex items-center gap-2 px-3 py-2 rounded border transition-all ${showConfig ? 'bg-slate-800 border-cyan-500 text-cyan-400' : 'bg-transparent border-slate-700 text-slate-400 hover:text-slate-200'}`}
                    >
                        <span className="text-lg">⚙️</span>
                        <span className="text-xs font-bold hidden sm:inline">地圖設定</span>
                    </button>

                    {/* Quick Scene Selector (Mobile optimized) */}
                    <select 
                        value={currentSceneId} 
                        onChange={(e) => onSetScene(e.target.value)}
                        className="bg-slate-900 border border-slate-700 text-slate-300 text-xs px-2 py-2 rounded outline-none sm:w-32"
                    >
                        {SCENE_DB.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                    </select>
                </div>

                {/* Center: Tools */}
                <div className="flex items-center gap-1 sm:gap-2 bg-slate-900/50 p-1 rounded-lg border border-slate-800">
                    <button onClick={() => setTool(ToolType.SELECT)} className={`w-10 h-10 rounded flex items-center justify-center text-lg transition-all ${tool === ToolType.SELECT ? 'bg-slate-700 text-white shadow-sm' : 'text-slate-500 hover:text-slate-300'}`} title="選取">↖</button>
                    <div className="w-px h-6 bg-slate-700 mx-1"></div>
                    <button onClick={() => setTool(ToolType.ADD_BLUE)} className={`w-10 h-10 rounded flex items-center justify-center text-xl transition-all ${tool === ToolType.ADD_BLUE ? 'bg-blue-900/50 border border-blue-500 text-blue-400 shadow-[0_0_10px_rgba(59,130,246,0.3)]' : 'text-slate-500 hover:text-blue-400'}`} title="部署藍軍">🔵</button>
                    <button onClick={() => setTool(ToolType.ADD_RED)} className={`w-10 h-10 rounded flex items-center justify-center text-xl transition-all ${tool === ToolType.ADD_RED ? 'bg-red-900/50 border border-red-500 text-red-400 shadow-[0_0_10px_rgba(239,68,68,0.3)]' : 'text-slate-500 hover:text-red-400'}`} title="部署紅軍">🔴</button>
                    <div className="w-px h-6 bg-slate-700 mx-1"></div>
                    <button onClick={() => setTool(ToolType.OBSTACLE)} className={`w-10 h-10 rounded flex items-center justify-center text-xl transition-all ${tool === ToolType.OBSTACLE ? 'bg-amber-900/30 border border-amber-500 text-amber-400' : 'text-slate-500 hover:text-amber-400'}`} title="放置障礙">🧱</button>
                    <button onClick={() => setTool(ToolType.DELETE)} className={`w-10 h-10 rounded flex items-center justify-center text-xl transition-all ${tool === ToolType.DELETE ? 'bg-slate-800 border border-red-500 text-red-500' : 'text-slate-500 hover:text-red-500'}`} title="移除">❌</button>
                </div>

                {/* Right: Actions */}
                <div className="flex items-center gap-2 w-full sm:w-auto justify-end">
                    <button 
                        onClick={onRandomBattlefield}
                        className="px-4 py-2 bg-purple-900/30 border border-purple-500/50 hover:border-purple-400 text-purple-300 rounded text-xs font-bold tracking-wider flex items-center gap-2 hover:shadow-[0_0_15px_rgba(168,85,247,0.3)] transition-all"
                    >
                        <span>🎲</span> 隨機戰場
                    </button>
                    <button 
                        onClick={onReset}
                        className="w-10 h-10 flex items-center justify-center rounded border border-slate-700 text-slate-400 hover:text-white hover:border-slate-500 transition-all bg-slate-900"
                        title="重置單位狀態"
                    >
                        ↺
                    </button>
                </div>
            </div>

            {/* 3. Slide-up Config Panel */}
            {showConfig && (
                <div className="pointer-events-auto absolute bottom-full left-0 mb-2 ml-2 p-4 bg-slate-900/95 border border-slate-700 rounded-lg shadow-2xl animate-slide-up w-64 backdrop-blur">
                    <div className="text-xs font-bold text-slate-500 uppercase mb-3">地圖參數</div>
                    <div className="grid grid-cols-2 gap-3 mb-4">
                        <div>
                            <label className="text-[10px] text-slate-400 block mb-1">寬度</label>
                            <input type="number" value={mapW} onChange={e => setMapW(Math.max(4, Math.min(30, parseInt(e.target.value))))} className="tactical-input w-full text-center"/>
                        </div>
                        <div>
                            <label className="text-[10px] text-slate-400 block mb-1">高度</label>
                            <input type="number" value={mapH} onChange={e => setMapH(Math.max(4, Math.min(30, parseInt(e.target.value))))} className="tactical-input w-full text-center"/>
                        </div>
                    </div>
                    <div className="text-[9px] text-slate-500">
                        * 調整尺寸將會清空當前地圖
                    </div>
                </div>
            )}
        </div>
    );
};
